(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.0"]={"from":0,"a":[["\u0003לפני אידיהן\u0004 (חגיהם) \u0003של גוים שלשה ימים\u0004 — \u0003אסור לשאת ולתת עמהם\u0004 במסחר, \u0003להשאילן\u0004 דברים או \u0003לשאול מהן, להלוותן\u0004 כסף או \u0003ללוות מהן, לפורען\u0004 כלומר, לפרוע את החובות להם, \u0003ולפרוע מהן\u0004 כלומר, להיפרע חובות מהם, וכל אלה כדי שלא תבוא על ידי כך שמחה לאותו גוי וילך ויודה על כך לעבודה זרה שלו ביום חגו. \u0003ר' יהודה אומר: נפרעין מהן, מפני שמיצר\u0004 (מצטער) \u0003הוא לו\u0004 שהוציא מכספו, ועל כך אינו מודה. \u0003אמרו לו: אף על פי שמיצר הוא עכשיו\u0004 בשעת פירעון, \u0003שמח הוא לאחר זמן\u0004 שנפטר מן ההתחייבות, וילך לעבודה זרה שלו ביום חגו ויודה על כך.","\u0003רב ושמואל\u0004 נחלקו בגירסת לשון המשנה, \u0003חד תני\u0004 \u0005[אחד\u0006 מהם \u0005שונה]:\u0006 \u0003\"אידיהן\", וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005שונה]:\u0006 \u0003\"עידיהן\".\u0004 ומעירים: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"אידיהן\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"עידיהן\" לא משתבש\u0004 \u0005[טועה],\u0006 שיש מקום לשתי הגרסות.","ומסבירים: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"אידיהן\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי קרוב יום אידם\"\u0004 (דברים לב, לה); והכוונה היא ליום מפלתם, וימי חגיהם של עובדי עבודה זרה יביאו למפלתם לעתיד לבוא. \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"עידיהן\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יתנו עדיהם ויצדקו\"\u0004 (ישעיהו מג, ט), שימי חגיהם יעידו עליהם שעבדו עבודה זרה.","ושואלים: \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"אידיהן\", מאי טעמא לא תני\u0004 \u0005[מה טעם אינו שונה]\u0006 \u0003\"עידיהן\"?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול הוא לומר לך]:\u0006 השימוש בלשון \u0003תברא\u0004 \u0005[שבר,\u0006 מפלה\u0005]\u0006 \u0003עדיף.\u0004 ושואלים: \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"עידיהן\", מאי טעמא לא תני\u0004 \u0005[מה טעם אינו שונה]\u0006 \u0003\"אידיהן\"?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול הוא לומר לך]:\u0006 \u0003מאן קא גרים להו תברא\u0004 \u0005[מי גורם להם\u0006 את \u0005השבר]?\u0006 \u0003עדות שהעידו בעצמן, הלכך\u0004 [\u0005על כן]\u0006 לשון \u0003עדות עדיפא\u0004 \u0005[עדיפה].\u0006","ושואלים: \u0003והאי\u0004 \u0005[ו\u0006כתוב \u0005זה\u0006\u0005]\u0006 \u0003\"יתנו עדיהם ויצדקו\"\u0004 האם \u0003באומות העולם כתיב\u0004 \u0005[נאמר]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בישראל כתיב\u0004 \u0005[נאמר],\u0006 ש\u0003אמר ר' יהושע בן לוי: כל מצו‍ת שישראל עושין בעולם הזה,\u0004 הן \u0003באות ומעידות להם לעולם הבא, שנאמר: \"יתנו עדיהם ויצדקו\"\u0004 — \u0003אלו ישראל,\u0004 שמעשיהם הטובים מעידים עליהם ועושים אותם צודקים, \u0003\"ישמעו ויאמרו אמת\"\u0004 — \u0003אלו אומות העולם\u0004 שמודים על כך!","\u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003\"עידיהן\"\u0004 — \u0003מהכא\u0004 \u0005[מכאן]\u0006 הוא למד את המלה, מן הכתוב: \u0003\"יצרי פסל כלם תהו וחמודיהם בל יועילו ועדיהם המה\u0004 בל יראו ובל ידעו\" (ישעיהו מד, ט), ומכאן ש\"עידיהם\" הם העבודה הזרה שעבדו.","ומביאים מה שדרשו חכמים על הפסוק שעסקנו בו: \"כל הגויים נקבצו יחדיו ויאספו לאומים, מי בהם יגיד זאת וראשונות ישמיעונו, יתנו עדיהם ויצדקו וישמעו ויאמרו אמת\" (ישעיהו מג, ט). \u0003דרש ר' חנינא בר פפא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' שמלאי: לעתיד לבא מביא הקדוש ברוך הוא ספר תורה [ומניחו] בחיקו, ואומר: למי שעסק בה\u0004 — \u0003יבא ויטול שכרו.\u0004","\u0003מיד מתקבצין ובאין אומות העולם בערבוביא, שנאמר: \"כל\u0004 \u0003הגוים נקבצו יחדו [וגו']\", אמר\u0004 (אומר) \u0003להם הקדוש ברוך הוא: אל תכנסו לפני בערבוביא, אלא תכנס כל אומה ואומה\u0004"],["\u0003וסופריה\u0004 כלומר, חכמיה ומלומדיה, \u0003שנאמר: \"ויאספו לאמים\"\u0004 (ישעיהו מג, ט), \u0003ואין \"לאום\" אלא מלכות, שנאמר: \"ולאם מלאם יאמץ\"\u0004 (בראשית כה, כג). ותמהים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003ערבוביא קמי\u0004 \u0005[לפני]\u0006 \u0003הקדוש ברוך הוא\u0004 שהוא צריך לגעור בהם שיעמדו כל אחד לעצמו, כדי שיוכל לדון איתם? \u0003אלא\u0004 המטרה היא \u0003כי היכי דלא ליערבבו אינהו [בהדי הדדי]\u0004 \u0005[כדי שלא יתערבבו הם זה עם זה],\u0006 \u0003דלישמעו מאי דאמר להו\u0004 \u0005[שישמעו מה שאומר להם]\u0006 הקב\"ה.","\u0003[מיד] נכנסה לפניו מלכות רומי תחלה.\u0004 ומבררים, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 היא נכנסת תחילה? \u0003משום דחשיבא\u0004 \u0005[ש\u0006היא \u0005החשובה]\u0006 מכל האומות. \u0003ומנלן דחשיבא\u0004 \u0005[ומנין לנו ש\u0006היא \u0005החשובה]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בספר דניאל על המלכות (\"החיה\") הרביעית מן האומות העתידות לשלוט בעולם: \u0003\"ותאכל כל ארעא ותדושנה ותדקינה\"\u0004 \u0005[ותאכל\u0006 את \u0005כל הארץ ותדוש ותרמוס אותה]\u0006 (דניאל ז, כג), \u0003אמר ר' יוחנן:\u0004 מלכות האוכלת את כל העולם \u0003זו רומי חייבת\u0004 (הרשעה) \u0003שטבעה יצא בכל העולם,\u0004 שהיא ממלכה גדולה וחזקה מאד הידועה בכל העולם.","ושואלים: \u0003ומנא לן דמאן דחשיב עייל ברישא\u0004 \u0005[ומנין לנו שמי שחשוב נכנס בתחילה]?\u0006 \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא:\u0004 כאשר \u0003מלך וצבור\u0004 באים לדין — \u0003מלך נכנס תחלה לדין, שנאמר: \"לעשות משפט עבדו ומשפט עמו ישראל\" [וגו']\u0004 (מלכים א ח, נט). \u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שמכניסים לדין תחילה את המלך? \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לאו אורח ארעא למיתב מלכא מאבראי\u0004 \u0005[אין\u0006 זו \u0005דרך ארץ שישב מלך מבחוץ\u0006 ויחכה\u0005],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 דנים אותו לעצמו תחילה, \u0003מקמי דליפוש\u0004 \u0005[לפני שיתרבה]\u0006 \u0003חרון אף\u0004 בגלל חטאיהם של הרבים.","נכנסת מלכות רומי, \u0003אמר להם הקדוש ברוך הוא: במאי\u0004 \u0005[במה]\u0006 \u0003עסקתם? אומרים לפניו: רבונו של עולם, הרבה שווקים תקנינו, הרבה מרחצאות עשינו, הרבה כסף וזהב הרבינו, וכולם לא עשינו אלא בשביל ישראל כדי שיתעסקו בתורה\u0004 כשכל אלו מוכנים לפניהם.","\u0003אמר להם הקדוש ברוך הוא: שוטים שבעולם,\u0004 וכי אותי אתם רוצים לרמות? \u0003כל מה שעשיתם\u0004 — \u0003לצורך עצמכם עשיתם: תקנתם שווקים\u0004 — \u0003להושיב בהן זונות, מרחצאות\u0004 עשיתם — \u0003לעדן בהן עצמכם, כסף וזהב\u0004 שאומרים אתם שהרביתם — \u0003שלי הוא\u0004 ולא שלכם, \u0003שנאמר: \"לי הכסף ולי הזהב נאם ה' צבאות\"\u0004 (חגי ב, ח),","\u0003כלום יש בכם מגיד זאת? [\u0004והוא \u0003שנאמר\u0004 בהמשך הפסוק שאנו דורשים אותו \"כל הגוים נקבצו יחדיו\" — \u0003\"מי בכם יגיד זאת\"\u0004 (ישעיהו מג, ט)\u0003], ואין \"זאת\" אלא תורה, שנאמר: \"וזאת התורה אשר שם משה\"\u0004 (דברים ד, מד), ומי שלא עסק בה לא מגיע לו שכר! \u0003מיד יצאו בפחי נפש.\u0004","\u0003יצאת מלכות רומי, ונכנסה מלכות פרס אחריה. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 היא נכנסת? \u0003דהא חשיבא בתרה\u0004 \u0005[שהיא חשובה אחריה].\u0006 \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 דבר זה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בחזון דניאל: \u0003\"וארו חיוא אחרי תנינא דמיא לדב\"\u0004 \u0005[והנה חיה אחרת\u0006 \u0005שניה דומה לדוב]\u0006 (דניאל ז, ה), \u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003רב יוסף:\u0004 החיה הזו \u0003אלו פרסיים, שאוכלין ושותין\u0004 הרבה \u0003כדוב, ומסורבלין\u0004 שמנים ומרובים \u0003[בשר] כדוב, ומגדלין שער\u0004 הרבה \u0003כדוב, ואין להם מנוחה כדוב\u0004 שהוא תמיד נע ונד.","\u0003אמר להם הקדוש ברוך הוא: במאי\u0004 \u0005[במה]\u0006 \u0003עסקתם? אומרים לפניו: רבונו של עולם, הרבה גשרים גשרנו, הרבה כרכים כבשנו, הרבה מלחמות עשינו, וכולם לא עשינו אלא בשביל ישראל כדי שיתעסקו בתורה.\u0004","\u0003אמר להם הקדוש ברוך הוא: כל מה שעשיתם\u0004 — \u0003לצורך עצמכם עשיתם: תקנתם גשרים\u0004 — \u0003ליטול מהם מכס, כרכים\u0004 — \u0003לעשות בהם אנגריא\u0004 כלומר, להשתמש ביושביהם לעבודת כפיה, \u0003מלחמות\u0004 — \u0003אני עשיתי, שנאמר: \"ה' איש מלחמה\"\u0004 (שמות טו, ג), \u0003כלום יש בכם מגיד זאת? שנאמר: \"מי בכם יגיד זאת\", ואין \"זאת\" אלא תורה, שנאמר: \"וזאת התורה אשר שם משה\"!\u0004 \u0003מיד יצאו מלפניו בפחי נפש.\u0004","ושואלים: \u0003וכי מאחר דחזית\u0004 \u0005[שרואה]\u0006 \u0003מלכות פרס למלכות רומי דלא מהניא ולא מידי\u0004 \u0005[שאינה מועילה דבר]\u0006 בטענות מסוג זה, \u0003מאי טעמא עיילא\u0004 \u0005[מה טעם נכנסת]?\u0006 ומשיבים: בכל זאת, חשבו הפרסיים שלהם יש סיכוי, \u0003אמרי\u0004 \u0005[אומרים\u0006 הם\u0005]:\u0006 \u0003אינהו סתרי\u0004 \u0005[הם\u0006 הרומאים \u0005הרסו]\u0006 את \u0003בית המקדש\u0004 (השני), \u0003ואנן בנינן\u0004 \u0005[ואנו בנינו]\u0006 אותו, שהרי ברשות ובעידוד כורש מלך פרס נבנה הבית השני. וממשיך המדרש: \u0003וכן\u0004 נעשה הדיון כעין זה \u0003לכל אומה ואומה.\u0004","ושואלים: \u0003וכי מאחר דחזו לקמאי דלא מהני ולא מידי\u0004 \u0005[ש\u0006שאר העמים \u0005רואים את הראשונים,\u0006 רומי ופרס, \u0005שאינם מועילים דבר\u0006 בטענותיהם\u0005],\u0006 \u0003מאי טעמא עיילי\u0004 \u0005[מה טעם\u0006 הם \u0005נכנסים]?\u0006 ומשיבים: \u0003סברי\u0004 \u0005[חושבים]\u0006 הם: \u0003הנך אישתעבדו בהו\u0004 \u0005[אלו,\u0006 רומי ופרס, \u0005שעבדו בהם]\u0006 \u0003בישראל\u0004 ולכן אינם מקבלים שכר, \u0003ואנן\u0004 \u0005[ואנו]\u0006 \u0003לא שעבדנו בישראל.\u0004 ושואלים: \u0003מאי שנא הני דחשיבי\u0004 \u0005[במה שונים אלה,\u0006 רומי ופרס, \u0005שהוחשבו],\u0006 שהוזכרו במפורש, \u0003ומאי שנא הני דלא חשיבי להו\u0004 \u0005[ובמה שונים אלה,\u0006 מלכויות אחרות, \u0005שלא הוחשבו],\u0006 שלא הזכירן? \u0003משום דהנך משכי במלכותייהו עד דאתי משיחא\u0004 \u0005[שאלה,\u0006 רומי ופרס, \u0005נמשכים במלכותם עד שיבוא משיח].\u0006","וממשיך המדרש: אחרי שהקב\"ה שואל את כל העמים האם עסקו בתורה, \u0003אומרים לפניו\u0004 העמים: \u0003רבונו של עולם, כלום נתת לנו\u0004 את התורה \u0003ולא קיבלנוה?\u0004 וכיון שלא נתת אותה לנו — מדוע עלינו לתת את הדין על שלא קיימנוה? ושואלים: \u0003ומי מצי למימר הכי\u0004 \u0005[והאם יכולים לומר כך]\u0006 שלא נתן להם? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתיאור נתינת התורה: \u0003\"ויאמר ה' מסיני בא וזרח משעיר למו\"\u0004 (דברים לג, ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אלוה מתימן יבוא\u0004 וקדוש מהר פארן\" (חבקוק ג, ג), ויש לשאול: \u0003מאי בעי\u0004 \u0005[מה מבקש]\u0006 ה' \u0003בשעיר, ומאי בעי\u0004 \u0005[ומה מבקש]\u0006 \u0003בפארן?\u0004 שהרי לא שם ניתנה התורה!","אלא \u0003אמר ר' יוחנן: מלמד שהחזירה הקדוש ברוך הוא\u0004 את התורה \u0003על כל אומה ולשון,\u0004 כגון בשעיר לאדומים ובפארן לישמעאלים, \u0003ולא קבלוה, עד שבא אצל ישראל וקבלוה.\u0004 ואם כן, איך יכולים הם לטעון שלא נתן להם את התורה?!","\u0003אלא הכי אמרי\u0004 \u0005[כך\u0006 הם \u0005אומרים]:\u0006 \u0003כלום קיבלנוה ולא קיימנוה?\u0004 ותמהים על הסבר זה: \u0003ועל דא תברתהון\u0004 \u0005[ועל זה השבר שלהם],\u0006 כלומר, הרי דבר זה עצמו הוא הפירכה לטענתם, שהרי הם נשאלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא קבלתוה?\u0004 \u0003אלא כך אומרים לפניו\u0004 אומות העולם: \u0003רבונו של עולם, כלום כפית עלינו הר כגיגית ולא קבלנוה, כמו שעשית לישראל?\u0004","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתיצבו בתחתית ההר\"\u0004 (שמות יט, יז), \u0003ואמר רב דימי בר חמא: מלמד שכפה\u0004 (הפך) \u0003הקדוש ברוך הוא\u0004 את \u0003הר\u0004 סיני \u0003כגיגית על ישראל\u0004 (והוא מה שנאמר שהתייצבו בתחתית ההר), \u0003ואמר להם: אם אתם מקבלין את התורה\u0004 — \u0003מוטב\u0004 לכם, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003שם\u0004 מתחת להר \u0003תהא קבורתכם!\u0004 אם כן, יש לעמים טענה שגם אותם היה אפשר לכפות בכך לקבל את התורה!","\u0003מיד אומר להם הקדוש ברוך הוא: הראשונות ישמיעונו,\u0004 כלומר מהמצוות הראשונות נלמד, \u0003שנאמר\u0004 בפסוק אותו אנו דורשים \u0003: \"וראשונות ישמיענו\"\u0004 (ישעיהו מג, ט), אותן \u0003שבע מצו‍ת\u0004 של בני נח, שלפני מתן תורה, \u0003ש\u0004אף אתם \u0003קיבלתם, היכן קיימתם?\u0004","ושואלים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003לא קיימום?\u0004 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 בפירוש הפסוק \u0003\"עמד וימדד ארץ ראה ויתר גוים\"\u0004 (חבקוק ג, ו), \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ראה? ראה שבע מצו‍ת שקבלו עליהן בני נח ולא קיימום, כיון שלא קיימום עמד והתירן להן.\u0004 ותוהים: \u0003איתגורי איתגור?\u0004 \u0005[\u0006וכי \u0005הרוויחו]?\u0006 \u0003אם כן מצינו\u0004 ש\u0003חוטא נשכר\u0004 בחטאו!","\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא:\u0004"],["\u0003לומר, שאף על פי שמקיימין אותן\u0004 את שבע המצוות הללו — \u0003אין מקבלין עליהם שכר.\u0004","ושואלים: \u0003ולא?\u0004 האם הגויים אינם מקבלים שכר עליהן? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: מנין שאפילו\u0004 הוא \u0003גוי ועוסק בתורה שהוא ככהן גדול? תלמוד לומר: \"אשר יעשה אתם האדם וחי בהם\"\u0004 (ויקרא יח, ה), \u0003כהנים לוים וישראלים לא נאמר, אלא \"האדם\",\u0004 באופן כללי, \u0003הא למדת\u0004 מכאן, \u0003שאפילו גוי ועוסק בתורה\u0004 — \u0003הרי הוא ככהן גדול,\u0004 משמע שמקבלים שכר!","\u0003אלא לומר לך, שאין מקבלין עליהם שכר כ\u0004מי ש\u0003מצווה ועושה, אלא\u0004 פחות מזה, \u0003כמי שאינו מצווה ועושה,\u0004 כפי ש\u0003אמר ר' חנינא: גדול המצווה ועושה יותר מ\u0004מי \u0003שאינו מצווה ועושה.\u0004 ושבים לדיון שבין הקב\"ה ואומות העולם, שאמר להם הקב\"ה שלא קיבלו את התורה משום שלא קיימו מה שנצטוו.","\u0003אלא כך אומרים הגוים לפני הקדוש ברוך הוא: רבונו של עולם, ישראל שקיבלוה\u0004 את התורה \u0003היכן קיימוה?\u0004","\u0003אמר להם הקדוש ברוך הוא: אני מעיד בהם שקיימו את התורה כולה. אומרים לפניו: רבונו של עולם, כלום יש אב שמעיד על בנו? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בני בכורי ישראל\"\u0004 (שמות ד, כב), ואם כן, הקב\"ה, שהוא אב לישראל, אינו יכול להעיד עליהם! \u0003אמר להם הקדוש ברוך הוא: שמים וארץ יעידו בהם שקיימו את התורה כולה.\u0004","\u0003אומרים לפניו: רבונו של עולם, שמים וארץ נוגעין בעדותן,\u0004 יש להם עניין להעיד שישראל קיימו את התורה, \u0003שנאמר: \"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\"\u0004 (ירמיהו לג, כה), \u0003ואמר\u0004 בעניין זה \u0003ר' שמעון בן לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויהי ערב ויהי בקר יום הששי\"\u0004 (בראשית א, לא), בה\"א הידיעה? \u0003מלמד שהתנה הקדוש ברוך הוא עם מעשה בראשית\u0004 תנאי זה, \u0003ואמר: אם ישראל מקבלין את תורתי\u0004 בזמן מתן תורה — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אני אחזיר אתכם לתוהו ובוהו;\u0004","\u0003והיינו דאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003חזקיה\u0004 באופן אחר: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"משמים השמעת דין ארץ יראה ושקטה\"\u0004 (תהלים עו, ט), \u0003אם יראה למה שקטה, ואם שקטה למה יראה?\u0004 והרי מי שירא אינו שקט, ומי ששקט — סימן שאינו ירא! \u0003אלא בתחלה,\u0004 כאשר בא הקב\"ה לתת את התורה לישראל (\"השמעת דין\"), \u0003יראה\u0004 הארץ שמא לא יקבלו ישראל את התורה, ואז תתבטל הארץ מקיומה, \u0003ולבסוף,\u0004 כשקיבלוה, \u0003שקטה.\u0004 ואם כן, אין השמים והארץ יכולים להעיד לישראל על התורה!","\u0003אמר להם הקדוש ברוך הוא\u0004 לאומות: \u0003מכם יבאו\u0004 אנשים \u0003ויעידו בהן בישראל שקיימו את התורה כולה: יבא נמרוד ויעיד באברהם שלא עבד עבודה זרה, יבא לבן ויעיד ביעקב שלא נחשד על הגזל, תבא אשת פוטיפרע ותעיד ביוסף שלא נחשד על העבירה\u0004 של ניאוף,","\u0003יבא נבוכדנצר ויעיד בחנניה מישאל ועזריה שלא השתחוו לצלם, יבא דריוש ויעיד בדניאל שלא ביטל את התפלה\u0004 (ראה דניאל פרק ו), \u0003יבא בלדד השוחי וצופר הנעמתי ואליפז התימני ואליהו בן ברכאל הבוזי,\u0004 חבריו של איוב (ראה איוב ב, יא. איוב לב, ב), \u0003ויעידו בהם בישראל שקיימו את כל התורה כולה, שנאמר:\u0004 \"כל הגויים נקבצו יחדיו... \u0003יתנו עדיהם ויצדקו\"\u0004 (ישעיהו מג, ט). כלומר, הגוים שנאספו יתנו עדות לישראל ויראו את צדקתם.","\u0003אמרו לפניו\u0004 הגוים: \u0003רבונו של עולם, תנה לנו מראש,\u0004 תן לנו עתה את התורה מתחילה, \u0003ונעשנה. אמר להן הקדוש ברוך הוא: שוטים שבעולם,\u0004 וכי יכולים אתם לבקש זאת? \u0003מי שטרח בערב שבת\u0004 הוא \u0003יאכל בשבת, מי שלא טרח בערב שבת מהיכן יאכל בשבת?\u0004 וכבר עבר הזמן שבו האדם יכול להתכונן ולעשות מצוות. \u0003אלא אף על פי כן,\u0004 כדי שלא תתרעמו, \u0003מצוה קלה יש לי וסוכה שמה, לכו ועשו אותה.\u0004","ושואלים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]\u0006 שאפשר לעשות מצוות לאחר ימי העולם הזה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יהושע בן לוי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \"ושמרת את המצוה... \u0003אשר אנכי מצוך היום\u0004 לעשותם\" (דברים ז, יא)? מה צורך במלה \"היום\"? אלא יש בכך הדגשה: \u0003\"היום\",\u0004 כלומר, בעולם הזה, הוא הזמן \u0003לעשותם\u0004 — \u0003ולא למחר\u0004 בעולם הבא \u0003לעשותם.\u0004 ועוד הדגשה בעניין זה: \u0003\"היום\u0004 הוא הזמן \u0003לעשותם\"\u0004 — \u0003ולא היום ליטול שכר,\u0004 אלא בעולם הבא!","\u0003אלא,\u0004 בכל זאת נתן להם הקב\"ה הזדמנות, לפי \u0003שאין הקדוש ברוך הוא בא בטרוניא\u0004 (בעלילה) \u0003עם בריותיו,\u0004 ורוצה שירגישו שדינם נעשה בצדק. ושואלים: \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורים לכך,\u0006 לסוכה\u0005]\u0006 \u0003\"מצוה קלה\"?\u0004 והתשובה היא: \u0003משום דלית ביה\u0004 \u0005[שאין בכך]\u0006 \u0003חסרון כיס,\u0004 שאין צריך להוציא על כך כסף, אלא אפשר לבנות ממה שיש בידו.","\u0003מיד כל אחד [ואחד]\u0004 מן הגוים \u0003נוטל והולך ועושה סוכה בראש גגו, ו\u0004מה עושה \u0003הקדוש ברוך הוא? מקדיר\u0004 (מחמם) \u0003עליהם\u0004 את ה\u0003חמה בתקופת תמוז, וכל אחד ואחד\u0004 שיושב בסוכה, וכל כך חם לו עד שאינו יכול לסבול, \u0003מבעט בסוכתו ויוצא, שנאמר\u0004 כאשר מתייצבים הגוים על ה': \u0003\"ננתקה את מוסרותימו ונשליכה ממנו עבתימו\"\u0004 (תהלים ב, ג). ושואלים: מפני מה \u0003מקדיר\u0004 עליהם חמה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת: אין הקדוש ברוך הוא בא בטרוניא, עם בריותיו!\u0004 ומשיבים: אין זו עלילה סתם, \u0003משום\u0004 שאצל \u0003ישראל נמי\u0004 \u0005[גם כן]\u0006 \u0003זימני\u0004 \u0005[פעמים]\u0006"],["\u0003דמשכא להו\u0004 \u0005[שנמשכת להם]\u0006 \u0003תקופת תמוז\u0004 החמה \u0003עד חגא\u0004 \u0005[חג הסוכות]\u0006 \u0003והוי להו צערא\u0004 \u0005[ויש להם צער]\u0006 לשבת בסוכה. ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מצטער פטור מן הסוכה,\u0004 ואם כן, מן הדין אף ישראל אין צריכים לשבת בה! ומשיבים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003פטור\u0004 מן הסוכה ויכול לצאת, \u0003בעוטי מי מבעטי\u0004 \u0005[לבעוט האם\u0006 ישראל \u0005בועטים\u0006 הם\u0005]?\u0006","\u0003מיד, הקדוש ברוך הוא יושב ומשחק\u0004 (וצוחק) \u0003עליהן, שנאמר\u0004 בהמשך הדברים: \u0003\"יושב בשמים ישחק\u0004 ה' ילעג למו\" (תהלים ב, ד). ועל כך \u0003אמר ר' יצחק: אין שחוק לפני הקדוש ברוך הוא אלא אותו היום בלבד.\u0004","\u0003איכא דמתני להא\u0004 \u0005[יש ששונים את זה\u0006 שאמר\u0005]\u0006 \u0003ר' יצחק אהא\u0004 \u0005[על\u0006 דבר \u0005זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: לעתיד לבא באין אומות העולם ומתגיירין.\u0004 ומיד תוהים: \u0003ומי מקבלינן מינייהו\u0004 \u0005[האם מקבלים אנו מהם\u0006 גרים\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מקבלין גרים לימות המשיח, כיוצא בו לא קבלו גרים לא בימי דוד ולא בימי שלמה,\u0004 מפני שאז היתה שעת גדולה לישראל, ולא סמכו על הבאים להצטרף לישראל דווקא בשעת גדולתם, שכוונתם לשם שמים!","\u0003אלא\u0004 הכוונה היא \u0003שנעשו גרים גרורים,\u0004 שמעצמם נגררים אחרי ישראל, \u0003ומניחין תפילין בראשיהן, תפילין בזרועותיהם,\u0004 ושמים \u0003ציצית בבגדיהם, מזוזה בפתחיהם.\u0004","\u0003כיון שרואין\u0004 אותם גרים \u0003מלחמת גוג ומגוג, אומר להן\u0004 כל גר כזה לגוג ומגוג: \u0003על מה באתם? אומרים לו: על ה' ועל משיחו\u0004 אנו באים להילחם, \u0003שנאמר: \"למה רגשו גוים ולאמים יהגו ריק...\u0004","על ה' ועל משיחו\" (תהלים ב, א —ב), \u0003וכל אחד\u0004 ואחד מן הגרים הללו \u0003מנתק מצותו והולך, שנאמר: \"ננתקה את מוסרותימו\u0004 ונשליכה ממנו עבותימו\" (תהלים ב, ג), \u0003ו\u0004אז \u0003הקדוש ברוך הוא יושב ומשחק, שנאמר: \"יושב בשמים ישחק\u0004 ה' ילעג למו\" (תהלים ב, ד). \u0003אמר ר' יצחק: אין לו להקדוש ברוך הוא שחוק אלא אותו היום בלבד.\u0004","ושואלים: \u0003איני\u0004 \u0005[האם כך הוא]\u0006 שאין להקב\"ה שחוק? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: שתים עשרה שעות הוי\u0004 \u0005[הריהו]\u0006 \u0003היום, שלש\u0004 שעות \u0003הראשונות\u0004 — \u0003הקדוש ברוך הוא יושב ועוסק בתורה,\u0004 שלוש שעות \u0003שניות\u0004 — \u0003יושב ודן את כל העולם כולו, כיון שרואה שנתחייב עולם כלייה\u0004 לפי הדין, \u0003עומד מכסא הדין ויושב על כסא רחמים,\u0004 והעולם נשאר קיים מתוך הרחמים.","שלוש שעות ה\u0003שלישיות\u0004 — \u0003יושב\u0004 הקב\"ה \u0003וזן את כל העולם כולו מקרני ראמים עד ביצי כנים,\u0004 שלוש שעות ה\u0003רביעיות\u0004 — \u0003יושב ומשחק עם לויתן, שנאמר: \"לויתן זה יצרת לשחק בו\"\u0004 (תהלים קד, כו), ואם כן יוצא שהקב\"ה שוחק בכל יום! \u0003אמר רב נחמן בר יצחק: עם בריותיו משחק,\u0004 משתעשע, כמו שהוא משחק עם לויתן, \u0003ועל בריותיו אינו משחק\u0004 בלעג \u0003אלא אותו היום בלבד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא לרב נחמן בר יצחק: מיום שחרב בית המקדש אין\u0004 עוד \u0003שחוק להקדוש ברוך הוא.\u0004 ושואלים: \u0003ומנלן דליכא\u0004 \u0005[ומנין לנו שאין]\u0006 \u0003שחוק? אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"ויקרא ה' אלהים צבאות ביום ההוא לבכי ולמספד ולקרחה\" וגו'\u0004 (ישעיהו כב, יב), \u0003דלמא ההוא יומא ותו לא\u0004 \u0005[שמא אותו יום\u0006 קרא לבכי וכו' \u0005ולא עוד]!\u0006","\u0003אלא\u0004 תאמר שהוא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם אשכחך ירושלם תשכח ימיני תדבק לשוני לחכי אם לא אזכרכי\"\u0004 (תהלים קלז, ה—ו), אולם גם מכאן אין הוכחה, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003שכחה הוא דליכא\u0004 \u0005[שאין\u0006 לפניו\u0005],\u0006 \u0003אבל שחוק מיהא איכא\u0004 \u0005[על כל פנים יש]!\u0006 \u0003אלא\u0004 יש ללמוד דבר זה \u0003מהא\u0004 \u0005[מזו]\u0006 שנאמר: \u0003\"החשיתי מעולם אחריש אתאפק\u0004 כיולדה אפעה\" (ישעיהו מב, יד).","ושואלים: אם כן, מכיון שאין הקב\"ה משחק עוד, \u0003ב\u0004שלוש שעות ה\u0003רביעיות מאי עביד\u0004 \u0005[מה\u0006 הוא \u0005עושה]?\u0006 ומשיבים: \u0003יושב ומלמד תינוקות של בית רבן תורה, שנאמר:\u0004 \u0003\"את מי יורה דעה ואת מי יבין שמועה גמולי מחלב עתיקי משדים\"\u0004 (ישעיהו כח, ט), וכוונתו: \u0003למי\u0004 הקב\"ה \u0003יורה דעה ולמי\u0004 הוא \u0003יבין שמועה? לגמולי מחלב ולעתיקי משדים,\u0004 כלומר: לאותם אלה שזה עתה נגמלו מלינוק.","ושואלים: \u0003ומעיקרא מאן הוה מיגמר להו\u0004 \u0005[ומתחילה\u0006 לפני החורבן \u0005מי היה מלמד אותם]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 המלאך \u0003מיטטרון; ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא עביד\u0004 \u0005[\u0006את זה ואת \u0005זה היה עושה\u0006 הקב\"ה\u0005],\u0006 גם משחק עם הלויתן וגם מלמד תינוקות, ועכשיו אינו משחק עוד.","ושואלים: \u0003וב\u0004שתים עשרה שעות של \u0003ליליא מאי עביד\u0004 \u0005[ובלילה מה\u0006 הוא \u0005עושה]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003מעין\u0004 \u0005[בדומה]\u0006 למה שעושה ב\u0003יממא\u0004 \u0005[יום],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003רוכב על כרוב קל שלו ושט בשמונה עשר אלף עולמות, שנאמר: \"רכב אלהים רבתים אלפי שנאן\"\u0004 (תהלים סח, יח), \u0003אל תקרי \"שנאן\" אלא \"שאינן\",\u0004 שאם לוקחים שתי רבבות (\"רבותים\", עשרים אלף) ומוציאים מהם שני אלפים (\"אלפי\" — אלפיים, \"שנאן\" — שאינן), הרי נשארים שמונה עשר אלף עולמות. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 בלילה \u0003יושב\u0004 הקב\"ה \u0003ושומע שירה מפי חיות, שנאמר: \"יומם יצוה ה' חסדו ובלילה שירה עמי\"\u0004 (תהלים מב, ט).","\u0003אמר ר' לוי: כל הפוסק מדברי תורה ועוסק בדברי שיחה\u0004 — \u0003מאכילין לו גחלי רתמים, שנאמר: \"הקטפים מלוח עלי שיח ושרש רתמים לחמם\"\u0004 (איוב ל, ד). \u0003אמר ריש לקיש: כל העוסק בתורה בלילה\u0004 — \u0003הקדוש ברוך הוא מושך עליו חוט של חסד ביום, שנאמר: \"יומם יצוה ה' חסדו ובלילה שירה עמי\".\u0004 שכך יש להבין את הכתוב: \u0003מה טעם \"יומם יצוה ה' חסדו\"\u0004 אותו חוט של חסד על האדם? \u0003משום\u0004 ש\"ו\u0003בלילה שירו עמי\",\u0004 כלומר, התורה שנקראת שירה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר ריש לקיש: כל העוסק בתורה בעולם הזה הדומה ללילה\u0004 — \u0003הקדוש ברוך הוא מושך עליו חוט של חסד בעולם הבא הדומה ליום, שנאמר: \"יומם יצוה ה' חסדו\u0004 ובלילה שירו עמי\".","ועוד בענין לימוד תורה, \u0003אמר רב יהודה אמר שמואל, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ותעשה אדם כדגי הים כרמש לא משל בו\"\u0004 (חבקוק א, יד), \u0003למה נמשלו בני אדם כדגי הים?\u0004 \u0003לומר לך: מה דגים שבים\u0004 — \u0003כיון שעולין ליבשה מיד מתים, אף בני אדם\u0004 — \u0003כיון שפורשין מדברי תורה ומן המצו‍ת מיד מתים. דבר אחר: מה דגים שבים\u0004 — \u0003כיון שקדרה\u0004 (התלהטה) \u0003עליהם חמה מיד מתים, כך בני אדם\u0004 — \u0003כיון שקדרה עליהם חמה מיד מתים.\u0004","ומעירים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שדבר זה נאמר בפשטות \u0003בעולם הזה, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לעולם הבא.\u0004 ומפרשים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003בעולם הזה\u0004 — \u0003כ\u0004דברי \u0003ר' חנינא,\u0004 ש\u0003אמר ר' חנינא: הכל,\u0004 כל מאורעות הבאים לו לאדם, באים \u0003בידי שמים, חוץ מצנים פחים\u0004 (צינה וחום), \u0003שנאמר: \"צנים פחים בדרך עקש שומר נפשו ירחק מהם\"\u0004 (משלי כב, ה), משמע: אדם יכול להינצל מהם אם ייזהר. ומכאן למדים שחום יתר הוא דבר העשוי להביא לידי סכנת מוות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שכל זה נאמר \u0003לעולם הבא, כ\u0004דברי \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר ר' שמעון בן לקיש: אין גיהנם לעתיד לבא, אלא\u0004 מה קורה? \u0003הקדוש ברוך הוא מוציא חמה מנרתיקה\u0004 מן הנרתיק שהיא נמצאת בו בזמן הזה, \u0003ומקדיר\u0004 ומחמם בה, \u0003רשעים נידונין בה\u0004 בחום הזה ונשרפים, \u0003וצדיקים מתרפאין בה.\u0004 וראיה לדבר: \u0003רשעים נידונין\u0004"],["\u0003בה,\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"[כי] הנה היום בא בער כתנור והיו כל זדים וכל עשה רשעה קש ולהט אתם היום הבא אמר ה' צבאות אשר לא יעזב להם שרש וענף\"\u0004 (מלאכי ג, יט), ומפרש: \u0003לא\u0004 יישאר להם \u0003שורש\u0004 — \u0003בעולם הזה, ולא\u0004 יצמח להם \u0003ענף\u0004 \u0003לעולם הבא,\u0004 ומכאן שהשמש של יום ה' היא עצמה תשרוף ותשמיד אותם.","מצד שני, למדים ש\u0003צדיקים מתרפאין בה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהמשך אותו כתוב: \u0003\"וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה\" וגו'\u0004 (מלאכי ג, כ); \u0003ולא עוד, אלא שמתעדנין בה, שנאמר: \"ויצאתם ופשתם\u0004 (כלומר, תשמינו ) \u0003כעגלי מרבק\"\u0004 (מלאכי ג, כ). ושבים לפרש את הפסוק \"ותעשה אדם כדגי הים כרמש לא מושל בו\" (חבקוק א, יד).","\u0003דבר אחר:\u0004 \u0003מה דגים שבים\u0004 — \u0003כל הגדול מחבירו בולע את חבירו, אף בני אדם\u0004 — \u0003אלמלא מוראה של מלכות,\u0004 של השלטון, \u0003כל הגדול מחבירו\u0004 היה \u0003בולע את חבירו. והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' חנינא סגן הכהנים אומר: הוי מתפלל בשלומה של מלכות,\u0004 שיתמיד שלטונה, \u0003ש\u0004כן \u0003אלמלא מוראה של מלכות,\u0004 היה \u0003איש את רעהו חיים בלעו,\u0004 ומורא המלכות הוא המסדיר את החיים בעולם.","\u0003רב חיננא בר פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין הפסוקים, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"שדי לא מצאנהו שגיא כח\"\u0004 (איוב לז, כג), שאין רואים את כוחו, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"גדול אדונינו ורב כח\"\u0004 (תהלים קמז, ה), \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"ימינך ה' נאדרי בכח\"\u0004 (שמות טו, ו), הרי שכוחו נראה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאין רואים את כוחו, הרי זה \u0003בשעת הדין,\u0004 שהוא נוהג ברחמים, \u0003כאן\u0004 שרואים את כוחו — \u0003בשעת מלחמה,\u0004 כשנלחם באויביו.","כיוצא בזה \u0003ר' חמא בר' חנינא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין פסוקים, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"חמה אין לי\"\u0004 (ישעיהו כז, ד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"נקם ה' ובעל חמה\"\u0004 (נחום א, ב)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שחימה אין לו — \u0003בישראל, כאן באומות העולם. רב חיננא בר פפא אמר\u0004 בפירוש הפסוק שהוזכר: \"חימה אין לי מי יתנני שמיר שית במלחמה אפשעה בה אציתנה יחד\", \u0003חמה אין לי,\u0004 איני כועס, לפי \u0003שכבר נשבעתי\u0004 שלא אכלה את ישראל, אבל \u0003מי יתנני\u0004 כלומר, הלואי \u0003שלא נשבעתי,\u0004 שאם לא השביעה — \u0003אהיה שמיר ושית\u0004 במלחמה אפשעה בה אציתנה יחד.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלכסנדרי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"והיה ביום ההוא אבקש להשמיד את כל הגוים\"\u0004 (זכריה יב, ט), \u0003אבקש ממי?\u0004 וכי צריך הקדוש ברוך הוא לבקש רשות? אלא \"אבקש\" משמעו כמו אחפש, אבדוק, \u0003אמר הקדוש ברוך הוא: אבקש בניגני\u0004 (ברשימה) \u0003שלהם, אם יש להם זכות\u0004 — \u0003אפדם, ואם לאו אשמידם.\u0004","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אך לא בעי ישלח יד אם בפידו להן שוע\"\u0004 (איוב ל, כד)? \u0003אמר להן הקדוש ברוך הוא לישראל: כשאני דן את ישראל, אין אני דן אותם כאומות העולם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עוה עוה עוה אשימנה\" וגו'\u0004 (יחזקאל כא, לב), שאיני מצרף את כל העוונות לחשבון אחד גדול ונפרע מהם, \u0003אלא אני נפרע\u0004 (מעניש) \u0003מהן כפיד\u0004 (כניקור) \u0003של תרנגולת,\u0004 שנוטלת בכל פעם רק דבר מועט.","\u0003דבר אחר: אפילו אין ישראל עושין מצוה לפני כי אם מעט, כפיד של תרנגולין שמנקרין באשפה, אני מצרפן לחשבון גדול, [שנאמר: \"אם בפידו] להן שוע\",\u0004 שאף שעושים ישראל מעט מעט (\"בפידו\") תהיה להם תשועה (\"שוע\"). \u0003[דבר אחר]: בשכר שמשוועין\u0004 ומתפללים \u0003לפני\u0004 (\"שוע\") \u0003אני מושיע\u0004 ופודה \u0003אותם\u0004 (\"בפידו\" מלשון פדיון).","\u0003ו\u0004דרך זו שהקדוש ברוך הוא נפרע מישראל מעט מעט, ומחסר מממונם ולא מכלה אותם בחמתו, \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר ר' אבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ואנכי אפדם והמה דברו עלי כזבים\"\u0004 (הושע ז, יג)? \u0003אני אמרתי אפדם בממונם\u0004 מה שמפסידים ממנו \u0003בעולם הזה, כדי שיזכו לעולם הבא, והמה דברו עלי כזבים\u0004 שהקדוש ברוך הוא זועם עליהם ואינו חפץ בהם.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 גם מה ש\u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ואני יסרתי חזקתי זרועתם ואלי יחשבו רע\"\u0004 (הושע ז, טו)? \u0003אמר הקדוש ברוך הוא: אני אמרתי איסרם ביסורין בעולם הזה כדי שיחזקו זרועותם לעולם הבא,\u0004 ואם כן כל זה הוא לטובה, \u0003ואלי יחשבו רע.\u0004","ובענין ייסוריהם של ישראל מסופר, \u0003משתבח להו\u0004 \u0005[היה משבח אותו]\u0006 \u0003ר' אבהו למיני\u0004 \u0005[למינים]\u0006 את \u0003רב ספרא\u0004 ש\u0003אדם גדול הוא, שבקו ליה מיכסא דתליסר שנין\u0004 \u0005[הניחו לו,\u0006 ויתרו לו, \u0005על המכס של שלוש עשרה שנים],\u0006 שסמכו על ר' אבהו, וחשבו שראוי שיעשו הנחה לאדם גדול. \u0003יומא חד אשכחוהו\u0004 \u0005[יום אחד מצאוהו],\u0006 את רב ספרא, \u0003אמרו ליה\u0004 \u0005[לו],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"רק אתכם ידעתי מכל משפחות האדמה על כן אפקד עליכם את כל עונתיכם\"\u0004 (עמוס ג, ב), והוא תמוה: אם ה' אוהב את ישראל מפני מה דווקא עליהם פוקד עוון? וכי \u0003מאן דאית ליה סיסיא\u0004 \u0005[מי שיש לו כעס],\u0006 \u0003ברחמיה מסיק ליה\u0004 \u0005[\u0006וכי \u0005באוהבו\u0006 הוא \u0005מעלה אותו]?\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 \u0003רמו ליה סודרא בצואריה וקא מצערו ליה\u0004 \u0005[השליכו לו סודר בצוארו והיו מצערים אותו],\u0006 מושכים אותו ומבזים אותו.","\u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' אבהו אשכחינהו\u0004 \u0005[מצא אותם]\u0006 שהם עושים כן לרב ספרא, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמאי מצעריתו ליה\u0004 \u0005[מדוע אתם מצערים אותו]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לר' אבהו: \u0003ולאו אמרת לן\u0004 \u0005[והאם לא אמרת לנו]\u0006 ש\u0003אדם גדול הוא? [ו\u0004הרי \u0003לא ידע למימר לן פירושא דהאי פסוקא]\u0004 \u0005[אינו יודע לומר לנו\u0006 את \u0005פירושו של פסוק זה]!\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' אבהו: \u0003אימר דאמרי לכו\u0004 — \u0003בתנאי, בקראי מי אמרי לכו\u0004 \u0005[גם אם אמרתי לכם\u0006 שאדם גדול הוא — הרי זה \u0005במשניות,\u0006 בתורה שבעל פה, אבל \u0005במקרא\u0006 בתורה שבכתב \u0005האם אמרתי לכם\u0006 שהוא יודע\u0005]?\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי שנא אתון דידעיתון\u0004 \u0005[במה שונים אתם,\u0006 חכמי ארץ ישראל, \u0005שאתם יודעים]\u0006 גם במקרא? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנן דשכיחינן גביכון\u0004 — \u0003רמינן אנפשין ומעיינן\u0004 \u0005[אנו, שאנו מצויים איתכם\u0006 ומתווכחים איתכם בפירוש מקראות — \u0005אנו מטילים על עצמנו\u0006 את החובה \u0005ומעיינים\u0006 במקרא\u0005],\u0006 \u0003אינהו לא מעייני\u0004 \u0005[הם,\u0006 חכמי בבל, שאינם צריכים להתווכח עמכם, \u0005אינם מעיינים\u0006 במקרא\u0005].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 אותם המינים לר' אבהו: אם כן, \u0003לימא לן את\u0004 \u0005[אמור לנו אתה]\u0006 את פירושו של פסוק זה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמשול לכם משל, למה הדבר דומה? לאדם שנושה משני בני אדם\u0004 שחייבים לו כסף, ה\u0003אחד\u0004 הוא \u0003אוהבו ואחד\u0004 הוא \u0003שונאו, אוהבו\u0004 — הריהו \u0003נפרע ממנו\u0004 את חובו \u0003מעט מעט, שונאו\u0004 — \u0003נפרע ממנו בבת אחת,\u0004 והוא מה שנאמר בכתוב שה' בכל פעם פוקד על ישראל את עוונותיהם, כדי שלא ייענשו בבת אחת.","ועוד בענין האופן בו נפרע הקדוש ברוך הוא, \u0003אמר ר' אבא בר כהנא, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בתפלת אברהם לה', כשהודיעו שהוא עומד להפוך את סדום: \u0003\"חלילה לך מעשת כדבר הזה להמית צדיק עם רשע\"\u0004 (בראשית יח, כה)? מהו \"חלילה\"? כך \u0003אמר אברהם לפני הקדוש ברוך הוא: רבונו של עולם, חולין\u0004 (\"חלילה\") \u0003הוא\u0004 לך \u0003מעשות כדבר הזה להמית צדיק עם רשע.\u0004","ושואלים: \u0003ולא?\u0004 האם אין הקדוש ברוך הוא עושה כן? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"והכרתי ממך צדיק ורשע\"\u0004 (יחזקאל כא, ח)! ומשיבים: שם מדובר \u0003בצדיק שאינו גמור,\u0004 שיכול להיכרת עם הרשע.","ותוהים: \u0003אבל בצדיק גמור לא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בנבואת חורבן שאמר ה' למשחיתים: \u0003\"וממקדשי תחלו\"\u0004 (יחזקאל ט, ו), כלומר, תתחילו, \u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003רב יוסף\u0004 בביאור מקרא זה: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ממקדשי\" אלא \"ממקודשי\",\u0004 אנשים המקודשים לי, \u0003אלו בני אדם שקיימו את התורה מאל\"ף ועד תי\"ו,\u0004 כלומר, את כל מצוותיה ודבריה, ובכל זאת נכרתו עם הרשעים! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 למרות שקיימו את כל התורה כולה, \u0003כיון שהיה בידם למחות\u0004 ברשעים לבל יחטאו \u0003ולא מיחו, הוו להו\u0004 \u0005[הרי הם]\u0006 נחשבים בשל כך \u0003כצדיקים שאינן גמורים.\u0004","\u0003רב פפא רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד: \u0003\"אל זעם בכל יום\"\u0004 (תהלים ז, יב), ובכל זאת העולם מתקיים, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכתוב אחר: \u0003\"לפני זעמו מי יעמוד\"\u0004 (נחום א, ו)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן ביחיד\u0004 שאין יכול לעמוד בפני זעמו, אינו זועם, \u0003כאן בצבור\u0004 שזכותו מרובה, זועם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אל זעם בכל יום\"\u0004 — \u0003וכמה זעמו? רגע. וכמה\u0004 הוא \u0003רגע? אחת מחמש ריבוא ושלשת אלפים ושמונה מאות וארבעים ושמנה בשעה,\u0004 כלומר, פרק זמן קצר ביותר, ו\u0003זו היא רגע, ואין כל בריה יכולה לכוין אותה רגע חוץ מבלעם הרשע, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006"],["\u0003\"וידע דעת עליון\"\u0004 (במדבר כד, טז), ויש לתמוה: וכי אפשר לפרש את הדבר כפשוטו שהיתה בו דעת רבה כל כך? \u0003אפשר, דעת בהמתו לא הוה ידע\u0004 \u0005[היה יודע],\u0006 \u0003דעת עליון מי הוה ידע\u0004 \u0005[האם היה יודע]?\u0006","ותחילה מבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"דעת בהמתו לא הוה ידע\"\u0004 \u0005[היה יודע]?\u0006 \u0003בעידנא דחזו ליה דהוה רכיב אחמריה\u0004 \u0005[בזמן שראו אותו\u0006 שרי מואב \u0005שהיה רוכב על חמורו],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא לא רכבתא אסוסיא\u0004 \u0005[מה טעם אין אתה רוכב על סוס],\u0006 שהוא ראוי לך יותר? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ברטיבא שדאי ליה\u0004 \u0005[באחו הנחתי אותו],\u0006 את הסוס, לרעות, ולכן אני רוכב על חמור. \u0003מיד: \"ותאמר האתון\u0004 אל בלעם, \u0003הלא אנכי אתנך\"\u0004 (במדבר כב, ל) שאתה משתמש בי כל הזמן! \u0003אמר לה: לטעינא בעלמא\u0004 \u0005[למטען בלבד]\u0006 אבל לא לרכיבה.","\u0003אמרה ליה\u0004 \u0005[לו]\u0006 האתון: \u0003\"אשר רכבת עלי\"!\u0004 (במדבר כב, ל). \u0003אמר לה: אקראי בעלמא\u0004 \u0005[במקרה בלבד],\u0006 לא בקביעות. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"מעודך ועד היום הזה\"\u0004 (במדבר כב, ל)! \u0003ולא עוד,\u0004 הוסיפה האתון, \u0003אלא\u0004 \u0003שאני עושה לך רכיבות ביום ו\u0004מעשה \u0003אישות בלילה,\u0004 ומסבירים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן],\u0006 בדברי האתון: \u0003\"ההסכן הסכנתי\",\u0004 (במדבר כב, ל), \u0003וכתיב התם\u0004 \u0005[ונאמר שם],\u0006 אצל אבישג ודוד המלך: \u0003\"ותהי לו סכנת\u0004 ושכבה בחיקך\" (מלכים א א, ב), משמע שלשון זו מרמזת לענין של משכב.","ושבים לשאלה הראשונה: \u0003אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ויודע דעת עליון\"?\u0004 הכוונה היא \u0003שהיה יודע לכוין אותה שעה שהקדוש ברוך הוא כועס בה. והיינו דקאמר להו\u0004 \u0005[וזה שאמר להם]\u0006 ה\u0003נביא\u0004 לישראל: \u0003\"עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור מן השטים ועד הגלגל למען דעת צדקות ה'\"\u0004 (מיכה ו, ה),","\u0003אמר ר' אלעזר, אמר להן הקדוש ברוך הוא לישראל: עמי, ראו כמה צדקות עשיתי עמכם שלא כעסתי עליכם כל אותן הימים\u0004 שביקש בלעם לקלל את ישראל, ולא יכול היה לכוון לשעת כעס ולקללם, \u0003שאם כעסתי עליכם\u0004 אז, \u0003לא נשתייר משונאיהם של ישראל\u0004 (לשון נקייה, והכוונה לישראל) \u0003שריד ופליט. והיינו דקאמר ליה\u0004 \u0005[וזהו שאמר לו]\u0006 \u0003בלעם לבלק\u0004 בענין זה: \u0003\"מה אקב לא קבה אל ומה אזעם לא זעם ה'\"\u0004 (במדבר כג, ח), שכיון שה' לא זעם איני יכול לעשות דבר.","ומבררים: \u0003וכמה\u0004 הוא \u0003זעמו\u0004 של ה'? \u0003רגע. וכמה\u0004 הוא \u0003רגע? אמר אמימר, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבינא: רגע כמימריה\u0004 \u0005[כאמירתו]\u0006 כמשך הזמן שלוקח להגיד את המלה הזו. ועוד שואלים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003רגע הוה ריתחיה\u0004 \u0005[הוא כעסו]\u0006 של הקב\"ה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי רגע באפו חיים ברצונו\"\u0004 (תהלים ל, ו). \u0003ואיבעית אימא, מהכא\u0004 \u0005[ואם תרצה אמור\u0006 זאת \u0005מכאן]:\u0006 \u0003\"חבי כמעט רגע עד יעבר זעם\"\u0004 (ישעיהו כו, כ).","ושואלים: \u0003אימת רתח\u0004 \u0005[מתי\u0006 הוא \u0005כועס],\u0006 מה הוא הזמן של כעסו? \u0003אמר אביי: בתלת שעי קמייתא, כי חיורא כרבלתא דתרנגולא\u0004 \u0005[בשלוש השעות הראשונות\u0006 של היום, \u0005כאשר מלבינה כרבולת התרנגול]\u0006 זוהי השעה. ושואלים: הלוא \u0003כל שעתא ושעתא מחוור חיורא\u0004 \u0005[כל שעה ושעה\u0006 היא \u0005מלבינה],\u0006 ואם כן מה הסימן שבדבר! ומשיבים: \u0003כל שעתא אית ביה סורייקי סומקי, ההיא שעתא לית ביה סורייקי סומקי\u0004 \u0005[בכל שעה יש בה,\u0006 נשארים בה עדיין \u0005ורידים אדומים, באותה שעה אין בה ורידים אדומים].\u0006","מסופר, \u0003ר' יהושע בן לוי הוה מצער ליה ההוא מינא [בקראי\u0004 \u0005[היה מצער אותו אחד המינים ב\u0006שאלות ובפירושי \u0005מקראות].\u0006 \u0003יומא חד] נקט תרנגולא [ואוקמיה בין כרעיה דערסא]\u0004 \u0005[יום אחד לקח\u0006 ר' יהושע בן לוי \u0005תרנגול והעמיד אותו בין רגלי המיטה]\u0006 \u0003ועיין ביה\u0004 \u0005[והתבונן בו],\u0006 \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003כי מטא ההיא שעתא אלטיה\u0004 \u0005[כאשר תגיע אותה שעה\u0006 של זעם \u0005אקללנו],\u0006 את אותו מין, ואז תחול הקללה. \u0003כי מטא ההיא שעתא נימנם\u0004 \u0005[כיון שהגיע אותה שעה התנמנם]\u0006 ר' יהושע בן לוי ולא הצליח לקללו, שכן חלפה השעה.","\u0003אמר:\u0004 כיון שאירע לי כך, \u0003שמע מינה לאו אורח ארעא למיעבד הכי\u0004 \u0005[משמע מכאן\u0006 ש\u0005אין\u0006 זה \u0005דרך ארץ לעשות כך],\u0006 שהרי \u0003[\"ורחמיו על כל מעשיו\" כתיב\u0004 \u0005[נאמר]\u0006 (תהלים קמה, ט)\u0003],\u0004 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"גם ענוש לצדיק לא טוב\"\u0004 (משלי יז, כו), כלומר, לא טוב לצדיק להעניש.","ובעניין זעמו של הקב\"ה, \u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' מאיר: בשעה שהמלכים\u0004 קמים משנתם ו\u0003מניחין כתריהן\u0004 \u0003בראשיהן ומשתחוין לחמה, מיד כועס [הקדוש ברוך הוא],\u0004 ולכן הכעס הוא בשלש שעות ראשונות. \u0003אמר רב יוסף: לא ליצלי איניש צלותא דמוספי בתלת שעי קמייתא דיומא, ביומא קמא דריש שתא\u0004 \u0005[אל יתפלל אדם תפילת המוספים בשלש שעות הראשונות של היום ביום הראשון של ראש השנה ]\u0006 כשהוא מתפלל \u0003ביחיד,\u0004 \u0003דלמא כיון דמפקיד דינא, דלמא מעייני בעובדיה ודחפו ליה מידחי\u0004 \u0005[שמא כיון ש\u0006אז \u0005נפקד הדין\u0006 על העולם, \u0005שמא יעיינו במעשיו וידחפו אותו וידחוהו]\u0006 מן העולם.","ומקשים: \u0003אי הכי, דצבור נמי\u0004 \u0005[אם כך,\u0006 תפילה \u0005של ציבור גם כן]\u0006 לא תהא בזמן זה! ומשיבים: ה\u0003צבור נפישא זכותיה\u0004 \u0005[מרובה זכותו]\u0006 ואין דוחים אותו גם כשמתפללים בשעה זו. ושואלים: \u0003אי הכי, דיחיד דצפרא נמי לא\u0004 \u0005[אם כך,\u0006 תפילה \u0005של יחיד של בוקר,\u0006 של שחרית, \u0005גם כן לא]\u0006 יתפלל באותן שעות, ולא רק תפילת מוסף! ומשיבים: \u0003כיון דאיכא צבורא דקא מצלו, לא קא מדחי\u0004 \u0005[שיש ציבור שמתפללים\u0006 באותה שעה, \u0005אינו נדחה],\u0006 ומקבלים תפילתו עמם.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 במקום אחר: \u0003שלש\u0004 שעות \u0003ראשונות הקדוש ברוך הוא יושב ועוסק בתורה,\u0004 ולא בדין! ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את סדרי השעות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך],\u0006 וטעם הדבר שלא יתפלל היחיד מוסף בשלוש השעות הראשונות שבהן הקב\"ה עוסק בתורה, הוא משום שלגבי ה\u0003תורה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"אמת\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אמת קנה ואל תמכר\"\u0004 (משלי כג, כג) — \u0003אין הקדוש ברוך הוא עושה\u0004 בשעת התורה \u0003לפנים משורת הדין,\u0004 אבל בזמן שעת ה\u0003דין דלא כתיב ביה\u0004 \u0005[שלא נאמר בו]\u0006 \u0003\"אמת\",\u0004 אלא דין הוא ענין של משפט ושל הערכה — \u0003הקדוש ברוך הוא עושה\u0004 גם \u0003לפנים משורת הדין.\u0004","ושבים לדיון לעיל (עבודה זרה ג,א), ומביאים את \u0003גופא\u0004 \u0005[גופם]\u0006 של הדברים ש\u0003אמר ר' יהושע בן לוי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אשר אנכי מצוך היום לעשותם\"\u0004 (דברים ז, יא)? מכאן נלמד: \u0003\"היום לעשותם\"\u0004 — \u0003ולא למחר\u0004 (לעולם הבא) \u0003לעשותם, \"היום לעשותם\"\u0004 — \u0003ולא היום ליטול שכרן.\u0004","ועוד \u0003אמר ר' יהושע בן לוי: כל מצו‍ת שישראל עושין בעולם הזה, באות ומעידות אותם לעולם הבא, שנאמר: \"יתנו עדיהם ויצדקו ישמעו ויאמרו אמת\"\u0004 (ישעיהו מג, ט), וכך הוא מפרש: \u0003\"יתנו עדיהם ויצדקו\"\u0004 — \u0003אלו ישראל, \"ישמעו ויאמרו אמת\"\u0004 — \u0003אלו אומות העולם.\u0004","\u0003ואמר ר' יהושע בן לוי: כל מצו‍ת שישראל עושין בעולם הזה, באות וטורפות אותם לאומות העולם לעולם הבא על פניהם, שנאמר: \"ושמרתם ועשיתם כי היא חכמתכם ובינתכם לעיני העמים\"\u0004 (דברים ד, ו), \u0003\"נגד העמים\"\u0004 כלומר, מול העמים \u0003לא נאמר, אלא \"לעיני העמים\"\u0004 — על עיניהם ממש, \u0003מלמד שבאות וטורפות לאומות העולם על פניהם לעולם הבא.\u0004","\u0003ואמר ר' יהושע בן לוי: לא עשו ישראל את העגל אלא ליתן פתחון פה לבעלי תשובה, שנאמר\u0004 לאחר מתן תורה: \u0003\"מי יתן והיה לבבם זה להם ליראה אתי כל הימים\" וגו'\u0004 (דברים ה, כו), ואם היו במעלה גדולה זו, כיצד הגיעו לעשות את העגל? אלא לא באו לידי חטא אלא כדי ללמד שאפשר לעשות תשובה על כל עבירה שבעולם, שאפילו עבירה חמורה זו של העגל יש לה תיקון.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: לא דוד ראוי לאותו מעשה\u0004 של בת שבע, \u0003ולא ישראל ראוין לאותו מעשה\u0004 של עגל; \u0003לא דוד ראוי לאותו מעשה\u0004 של בת שבע, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולבי חלל בקרבי\"\u0004 (תהלים קט, כב), שיצרו היה כהרוג בקרבו, ולא היתה סיבה שיוכל לשלוט בו עד כדי כך,","\u0003ולא ישראל ראוין לאותו מעשה, דכתיב\u0004 \u0005[שנאמר]\u0006 באותה שעה: \u0003\"מי יתן והיה לבבם זה להם ליראה אותי כל הימים\"\u0004 (דברים ה, כו), \u0003אלא למה עשו\u0004 את מה שעשו?"],["\u0003לומר לך, שאם חטא יחיד\u0004 — \u0003אומרים לו: כלך\u0004 (לך) \u0003אצל יחיד\u0004 שחטא, דוד המלך, ולמד ממנו שאפשר לעשות תשובה, \u0003ואם חטאו צבור\u0004 — \u0003אומרים לו: כלך\u0004 (לכו) \u0003אצל צבור\u0004 שחטאו.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 הדבר להיאמר גם ביחיד וגם בציבור, \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003יחיד,\u0004 היה אפשר לומר שהוא \u0003משום\u0004 ששם \u0003לא מפרסם חטאיה\u0004 \u0005[מתפרסם חטאו]\u0006 כל כך, \u0003אבל צבור דמפרסם חטאיהו\u0004 \u0005[שמתפרסם חטאם]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שאין להם דרך לעשות תשובה. \u0003ו\u0004מצד אחר, \u0003אי אשמועינן\u0004 \u0005[אם היה משמיע לנו]\u0006 רק ב\u0003צבור\u0004 שניתן לעשות תשובה, הייתי אומר — \u0003משום דנפישי רחמייהו\u0004 \u0005[שמרובים רחמיהם\u0006 ותפילתם\u0005],\u0006 ונשמעים לפני ה', ומתקבלת תשובתם לפניו, \u0003אבל יחיד\u0004 ש\u0003לא אלימא זכותיה\u0004 \u0005[חזקה זכותו]\u0006 כל כך, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יוכל לעשות תשובה, על כן \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005].\u0006","\u0003ו\u0004מה שנאמר לגבי דוד \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן, מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה פירוש \u0003\"נאם דוד בן ישי ונאם הגבר הקם על\"\u0004 (שמואל ב כג, א)? \u0003נאם דוד בן ישי שהקים עולה של תשובה,\u0004 שממנו למדים שאפשר ומוטל על האדם לעשות תשובה.","\u0003ו\u0004עוד \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל העושה מצוה אחת בעולם הזה,\u0004 מצוה זו \u0003מקדמתו והולכת לפניו לעולם הבא, שנאמר: \"והלך לפניך צדקך וכבוד ה' יאספך\"\u0004 (ישעיהו נח, ח), \u0003ו\u0004מן הצד השני, \u0003כל העובר עבירה אחת,\u0004 העבירה הזו \u0003מלפפתו\u0004 (עוטפת אותו) \u0003ומוליכתו ליום הדין, שנאמר: \"ילפתו ארחות דרכם\u0004 ויעלו בתהו ויאבדו\" \u0003וגו'\u0004 (איוב ו, יח).","\u0003ר' אלעזר אומר:\u0004 העבירה \u0003קשורה בו ככלב\u0004 ואינה נפרדת ממנו, \u0003שנאמר\u0004 ביוסף ואשת אדוניו: \u0003\"ולא שמע אליה לשכב אצלה להיות עמה\"\u0004 (בראשית לט, י), לומר \u0003\"לשכב אצלה\"\u0004 — \u0003בעולם הזה,\u0004 ועל ידי כך \u0003\"להיות עמה\"\u0004 — \u0003בעולם הבא.\u0004","ועוד בענין חטא העגל \u0003אמר ריש לקיש: בואו ונחזיק טובה לאבותינו\u0004 שחטאו בעגל, \u0003שאלמלא הן לא חטאו\u0004 — \u0003אנו לא באנו לעולם, שנאמר: \"אני אמרתי אלהים אתם ובני עליון כלכם\"\u0004 (תהלים פב, ו), והוא לאחר מתן תורה, שהיו נעשים כמלאכים ולא היו מולידים ילדים, אבל לאחר ש\u0003חבלתם\u0004 (קלקלתם) \u0003מעשיכם\u0004 בעגל — \u0003\"אכן כאדם תמותון\" וגו'\u0004 (תהלים פב, ז).","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא חטאו\u0004 בעגל \u0003לא הוו מולדו\u0004 \u0005[היו מולידים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לנח ובניו כציווי: \u0003\"ואתם פרו ורבו\"\u0004 (בראשית ט, ז)! ומשיבים: ציווי זה היה \u0003עד\u0004 מתן תורה בהר \u0003סיני,\u0004 שאז היו נעשים כמלאכים — אם לא היו חוטאים. ושואלים: \u0003בסיני נמי כתיב\u0004 \u0005[גם כן נאמר]:\u0006 \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז), שעניינו שישובו לחיי האישות שלהם! ומשיבים: הכוונה היתה שם \u0003לשמחת עונה\u0004 של אישות, אבל לא לפריה ורביה.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"למען ייטב להם ולבניהם\" וגו'\u0004 (דברים ה, כו) משמע שימשיכו להוליד! ומשיבים: הכוונה היא \u0003לאותן\u0004 בנים \u0003העומדים על הר סיני,\u0004 ולא לבאים אחריהם.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"זה ספר תולדת אדם\" וגו'\u0004 (בראשית ה, א)? \u0003וכי ספר היה לו לאדם הראשון?\u0004 אלא \u0003מלמד שהראה לו הקדוש ברוך הוא לאדם הראשון דור דור ודורשיו\u0004 (דרשניו), \u0003דור דור וחכמיו, דור דור ופרנסיו\u0004 (מנהיגיו), \u0003כיון שהגיע\u0004 אדם הראשון \u0003לדורו של ר' עקיבא, שמח בתורתו ונתעצב במיתתו,\u0004 שכן נהרג ביסורים קשים. \u0003אמר: \"ולי מה יקרו רעיך אל\u0004 מה עצמו ראשיהם\" (תהלים קלט, יז). ומשמע מכאן שכבר מתחילה עתידים היו להיוולד דורות נוספים.","\u0003ו\u0004כן \u0003אמר ר' יוסי: אין\u0004 משיח \u0003בן דוד בא עד שיכלו נשמות שבגוף\u0004 שבאוצר הנשמות, \u0003שנאמר: \"[כי לא לעולם אריב ולא לנצח אקצוף] כי רוח מלפני יעטוף ונשמות אני עשיתי\"\u0004 (ישעיהו נז, טו). משמע שצריך שייוולדו ילדים אף בעתיד כדי להגיע לקץ הימים!","ומשיבים: \u0003לא תימא\u0004 \u0005[תאמר]\u0006 אין הכוונה שאלמלא חטאו אבותינו \u0003אנו לא באנו לעולם,\u0004 שבודאי היו מולידים, \u0003אלא כמי שלא באנו לעולם,\u0004 שלא היינו נחשבים בפני הדורות הראשונים שהיו קיימים עד ימינו. ושואלים: \u0003למימרא, דאי לא חטאו לא הוו מייתי\u0004 \u0005[האם לומר, שאם לא היו חוטאים לא היו מתים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי כתובה]\u0006 בתורה \u0003פרשת יבמות\u0004 (דברים כה, ה—י), העוסקת במקרה שמת אחד מן האחים, \u0003ופרשת נחלות\u0004 (דברים, כא, טו —יז), העוסקת בירושת נחלת האב שמת על ידי בניו!","ומשיבים: כל אלה כתובות \u0003על תנאי,\u0004 שאם יחטאו וימותו יחולו דינים אלה. ושואלים: \u0003ומי כתיבי קראי\u0004 \u0005[והאם כתובים מקראות]\u0006 \u0003על תנאי\u0004 כגון זה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דהכי\u0004 \u0005[שכך]\u0006 \u0003אמר ר' שמעון בן לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בסוף מעשה בראשית: \u0003\"ויהי ערב ויהי בקר יום הששי\"\u0004 (בראשית א, לא)? \u0003מלמד שהתנה הקדוש ברוך הוא עם מעשה בראשית, ואמר: אם מקבלין ישראל את התורה\u0004 ביום השישי בסיון — \u0003מוטב,\u0004 יתקיים העולם, \u0003ואם לאו\u0004 — \u0003אחזיר אתכם\u0004 את העולם וברואיו \u0003לתוהו ובוהו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על מה שנאמר שאילו לא חטאו בעגל לא היו מתים, ממה ששנינו בברייתא על הפסוק שלאחר מתן תורה: \u0003\"מי יתן והיה לבבם זה להם\u0004 ליראה אותי כל הימים\" (דברים ה, כו), כשישראל הגיעו למעלה העליונה: \u0003לבטל מהם מלאך המות אי אפשר, שכבר נגזרה גזרה\u0004 מימי בראשית,","\u0003הא לא קיבלו ישראל את התורה אלא כדי שלא תהא אומה ולשון שולטת בהן, שנאמר: \"למען ייטב להם ולבניהם עד עולם\"\u0004 (דברים ה, כו). הרי שגם אם לא היו חוטאים היו מתים, שלא כדברי ריש לקיש!","ומשיבים: \u0003הוא,\u0004 ריש לקיש, ש\u0003אומר\u0004 את דבריו, \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה]\u0006 אמר: \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: לא קיבלו ישראל את התורה אלא כדי שלא יהא מלאך המות שולט בהן, שנאמר: \"אני אמרתי אלהים אתם ובני עליון כלכם\"\u0004 (תהלים פב, ו), וכיון ש\u0003חבלתם מעשיכם\u0004 — \u0003\"אכן כאדם תמותון\"\u0004 (תהלים פב, ז).","ומקשים: \u0003ור' יוסי נמי\u0004 \u0005[גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"למען ייטב להם ולבניהם עד עולם\",\u0004 ונבין מכאן: \u0003טובה הוא דהויא\u0004 \u0005[שיש להם]\u0006 אם יישאר לבבם כפי שהוא, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003מיתה איכא\u0004 \u0005[יש]!\u0006 ומשיבים: \u0003(ר' יוסי) אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003כיון דליכא\u0004 \u0005[שאין]\u0006 \u0003מיתה,\u0004 הרי \u0003אין לך טובה גדולה מזו\u0004 והיא ההבטחה של \"למען ייטב\".","ושואלים מצד אחר: \u0003ותנא קמא,\u0004 האומר שלא נפטרו כלל מן המוות, \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לשאול עליו, \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"אכן כאדם תמותון\"\u0004 ומשמע שרק לאחר שחטאו בעגל נגזר עליהם למות! ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003מיתה\u0004 שנגזרה עליהם? \u0003עניות.\u0004 ומנין שיש לפרש כך? ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ארבעה חשובים\u0004 (נחשבים) \u0003כמתים, אלו הן: עני, סומא\u0004 (עיור), \u0003ומצורע, ומי שאין לו בנים.\u0004","וראיה לדבר: \u0003עני\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 למשה: \"לך שוב מצרים \u0003כי מתו כל האנשים\u0004 המבקשים את נפשך\" (שמות ד, יט), \u0003ומאן נינהו\u0004 ויש לתמוה \u0005[ומי הם\u0006 האנשים \u0005הללו]?\u0006 \u0003דתן ואבירם, ומי\u0004 \u0005[והאם]\u0006 \u0003מתו? מיהוי הוו\u0004 \u0005[הרי היו]\u0006 ונשארו חיים הלאה עד זמנו של קורח! \u0003אלא\u0004 צריך לומר \u0003שירדו מנכסיהם\u0004 (איבדו ממונם ונהיו עניים), והרי הם קרויים כמתים.","\u0003סומא\u0004 נחשב כמת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במחשכים הושיבני כמתי עולם\"\u0004 (איכה ג, ו). \u0003מצורע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על מרים שנצטרעה: \u0003\"אל נא תהי כמת\"\u0004 (במדבר יב, יב). \u0003ומי שאין לו בנים\u0004 נחשב כמת, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי רחל ליעקב: \u0003\"הבה לי בנים ואם אין מתה אנכי\"\u0004 (בראשית ל, א).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אם בחקתי תלכו\"\u0004 (ויקרא כו, ג), \u0003אין \"אם\"\u0004 האמור כאן \u0003אלא לשון תחנונים, וכן הוא אומר\u0004 במקום אחר, שהקב\"ה מבקש: \u0003\"לו עמי שומע לי וגו' כמעט אויביהם אכניע\"\u0004 (תהלים פא, יד —טו), \u0003ואומר: \"לו הקשבת למצותי ויהי כנהר שלומך וגו' ויהי כחול זרעך וצאצאי מעיך\" וגו'\u0004 (ישעיה מח, יח —יט). ושבים לדון בפסוק שהוזכר קודם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"מי יתן והיה לבבם זה להם\u0004 ליראה אותי\" (דברים ה, כו), \u0003אמר להן משה לישראל\u0004 לאחר זמן: \u0003כפויי טובה בני כפויי טובה, בשעה שאמר הקדוש ברוך הוא לישראל: \"מי יתן והיה לבבם זה להם\", היה להם לומר: תן אתה.\u0004","ומסבירים: מדוע קוראים להם \u0003כפויי טובה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונפשנו קצה\u0004"],["\u0003בלחם הקלקל\"\u0004 (במדבר כא, ה); שכך גינו את המן, אף שהיה משובח שבמאכלים. \u0003בני כפויי טובה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר אדם הראשון, לאחר שחטא בעץ הדעת: \u0003\"האשה אשר נתתה עמדי היא נתנה לי מן העץ ואכל\"\u0004 (בראשית ג, יב). ומשמע מדבריו שניתנה לו לרעתו, והחטיאתו, בעוד שה' נתנה לו להיות עזר כנגדו.","ומוסיפים: \u0003אף משה רבינו,\u0004 שאמר דבר זה לישראל, \u0003לא רמזה להן לישראל\u0004 על שלא ביקשו בקשה זו, \u0003אלא לאחר ארבעים שנה, שנאמר: \"ואולך אתכם במדבר ארבעים שנה\"\u0004 (ראה דברים כט, ד), הרי שמדובר היה ארבעים שנה לאחר מתן תורה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בדברי משה אז: \u0003\"ולא נתן ה' לכם לב\u0004 לדעת ועינים לראות ואזנים לשמוע עד היום הזה\" (דברים כט, ג). \u0003אמר רבה, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לא קאי איניש אדעתיה דרביה עד ארבעין שנין\u0004 \u0005[אין אדם עומד על דעת רבו עד ארבעים שנה],\u0006 שהרי משה אמר זאת לישראל רק לאחר ארבעים שנה.","\u0003אמר ר' יוחנן משום\u0004 \u0005[משמו]\u0006 של \u0003ר' בנאה, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אשריכם זרעי על כל מים משלחי רגל השור והחמור\"\u0004 (ישעיהו לב, כ) — \u0003אשריהם ישראל, בזמן שעוסקין בתורה ובגמילות חסדים\u0004 — \u0003יצרם מסור בידם ואין הם מסורים ביד יצרם, שנאמר: \"אשריכם זרעי על כל מים\", ואין זריעה אלא צדקה, שנאמר: \"זרעו לכם לצדקה וקצרו לפי חסד\"\u0004 (הושע י, יב), \u0003ואין מים אלא תורה, שנאמר: \"הוי כל צמא לכו למים\"\u0004 (ישעיהו נה, א).","ובפירוש הביטוי \u0003\"משלחי רגל השור והחמור\"\u0004 לפי דרך זו, \u0003תנא\u0004 \u0005[שנה\u0006 התנא\u0005]\u0006 \u0003דבי אליהו: לעולם ישים אדם עצמו על דברי תורה כשור לעול וכחמור למשאוי.\u0004","לאחר הקדמה ארוכה זו באים לביאור המשנה. שנינו במשנה שלפני אידיהם של גוים \u0003שלשה ימים אסור לשאת ולתת עמהם.\u0004 ושואלים: \u0003ומי בעינן כולי האי\u0004 \u0005[והאם צריכים כל כך]\u0006 הרבה ימים לקנות בהמה לצורך החג, שאנו אוסרים למכור להם קודם חגיהם?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בארבעה פרקים\u0004 (זמנים) \u0003בשנה, המוכר בהמה לחבירו צריך להודיעו: אמה\u0004 של בהמה זו שאני מוכר לך \u0003מכרתי\u0004 היום כדי \u0003לשחוט,\u0004 או את \u0003בתה\u0004 של זו \u0003מכרתי לשחוט,\u0004 כדי שקונה זו לא ישחט באותו היום את הבהמה שהוא קונה, ויגרום שיישחטו בהמה ובתה ביום אחד ויעבור על איסור \"אותו ואת בנו לא תשחטו ביום אחד\" (ויקרא כב, כח).","\u0003ואלו הן\u0004 ארבעה פרקים אלה: \u0003ערב יום טוב האחרון של חג\u0004 (סוכות), \u0003ערב יום טוב הראשון של פסח, וערב עצרת\u0004 (שבועות), \u0003וערב ראש השנה, וכדברי ר' יוסי הגלילי\u0004 — \u0003אף ערב יום הכפורים בגליל!\u0004 משמע שיום אחד קודם החג עוסקים בהכנות לחג, ומדוע כאן אוסרים שלושה ימים?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לעניין \"אותו ואת בנו\", שלצורך \u0003אכילה\u0004 קונים את הבהמה, \u0003סגיא בחד יומא\u0004 \u0005[די ביום אחד]\u0006 להכנות. \u0003הכא\u0004 \u0005[כאן],\u0006 שלצורך \u0003הקרבה\u0004 לעבודה זרה הם מתכוננים, \u0003בעינן תלתא יומי\u0004 \u0005[צריכים שלושה ימים]\u0006 למצוא בהמה הראויה לכך, שאין בה מום. ושואלים: \u0003ולהקרבה סגי בתלתא יומי\u0004 \u0005[די בשלושה ימים]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו]:\u0006 \u0003שואלין בהלכות הפסח קודם הפסח שלשים יום, רבן שמעון בן גמליאל אומר: שתי שבתות\u0004 (שבועות). משמע שכדי להכין להקרבה צריך הרבה יותר זמן!","ודוחים: מכאן אין להקשות, \u0003אנן דשכיחי מומין דפסלי\u0004 \u0005[אנו,\u0006 אצלנו היהודים, \u0005שמצויים\u0006 בדינינו \u0005מומים\u0006 רבים \u0005שפוסלים\u0006 את הקרבן\u0005],\u0006 ו\u0003אפילו בדוקין\u0004 (בתבלול) \u0003שבעין, בעינן תלתין יומין\u0004 \u0005[צריכים אנו שלושים יום]\u0006 להתכונן לצורך קרבנות החג, \u0003אינהו\u0004 \u0005[הם]\u0006 הגוים, שרק פסול של \u0003מחוסר אבר אית להו\u0004 \u0005[יש להם],\u0006 שרק בהמה מחוסרת איבר שלם פסולה עבורם לקרבן, על כן \u0003בתלתא יומי סגי\u0004 \u0005[בשלושה ימים די\u0006 להם\u0005],\u0006 ש","\u0003אמר ר' אלעזר: מנין למחוסר אבר\u0004 ש\u0003אסור לבני נח\u0004 להקריב לשמים? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי ה' לנח: \u0003\"ומכל החי מכל בשר שנים מכל\u0004 תביא אל התיבה להחיות אתך\" (בראשית ו, יט), \u0003אמרה תורה: הבא בהמה שחיין ראשי אברים שלה,\u0004 לכן הוא קורא לזה \"מכל החי\", ומקצת מאלה נועדו אחר כך להקרבה.","ומקשים: \u0003האי מיבעי ליה למעוטי טריפה דלא\u0004 \u0005[\u0006פסוק \u0005זה צריך אותו\u0006 כדי \u0005למעט טריפה שאינה]\u0006 כשרה לקרבן! ודוחים: פסול \u0003טריפה\u0004 לקרבן \u0003מ\"לחיות זרע\"\u0004 (בראשית ז, ג), \u0003נפקא\u0004 \u0005[יוצאת],\u0006 נלמדת, שהרי טריפה אינה יכולה להוליד. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003טריפה אינה יולדת,\u0004 אם כן, מן הכתוב \"לחיות זרע\" למדים לענין טריפה, ו\"מכל החי\" — לענין מחוסר אבר."],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003טריפה יולדת, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי גם היא בכלל \"לחיות זרע\"! ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בעניינם של בעלי החיים שהובאו לתיבת נח מפני המבול: \"תביא אל התיבה להחיות \u0003אתך\"\u0004 (בראשית ו, יט), והכוונה ב\"אתך\" להורות שמדובר \u0003ב\u0004בעלי חיים \u0003דומין לך.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הוה\u0004 \u0005[היה],\u0006 ואם כן, אין מכאן ראיה כלל! ומשיבים: \u0003\"תמים\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (בראשית ו, ט), משמע שהיה שלם בכל איבריו.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003תמים בדרכיו היה\u0004 ולא מדובר בשלימות הגוף! ומשיבים: לעניין זה \u0003\"צדיק\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (בראשית ו, ט), והוא השלם בדרכיו, ואם כן, \"תמים\" משמע שלם בגופו.","ומקשים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003\"תמים\" בדרכיו,\u0004 במידותיו ובאופן התנהגותו, ו\u0003\"צדיק\" במעשיו\u0004 הטובים \u0003הוה\u0004 \u0005[היה],\u0006 ועדיין אין אנו יודעים שלא היה טריפה! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 ש\u0003נח גופיה\u0004 \u0005[עצמו]\u0006 \u0003טריפה הואי\u0004 \u0005[היה],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003נח טריפה הוה\u0004 \u0005[היה],\u0006 וכי \u0003אמר ליה רחמנא\u0004 \u0005[לו הקב\"ה]:\u0006 \u0003כוותך עייל, שלמין לא תעייל\u0004 \u0005[\u0006טריפות \u0005כמותך הכנס\u0006 לתיבה, ו\u0005שלמים אל תכניס]?\u0006","ושואלים: \u0003והשתא דנפקא ליה\u0004 \u0005[ועכשיו שיוצא לו]\u0006 הלימוד לגבי טריפה שפסולה \u0003מ\"אתך\",\u0004 אם כן \u0003\"לחיות זרע\"\u0004 (בראשית ז, ג) \u0003למה לי?\u0004 ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\"אתך\"\u0004 בלבד, \u0003הוה אמינא לצוותא בעלמא\u0004 \u0005[הייתי אומר ל\u0006צורך \u0005חברה בלבד]\u0006 מביא נח את בעלי החיים לתיבה, \u0003ואפילו זקן ואפילו סריס\u0004 יכול להכניס איתו (כל עוד אינו טריפה), \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זרע\",\u0004 דווקא זה שיכול להוליד.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה ששנינו במשנתנו, \"לפני אידיהן \u0003שלשה ימים\",\u0004 האם הכוונה היא \u0003הן ואידיהן,\u0004 כלומר יום חגם עצמו בכלל השלושה, ועוד שני ימים לפניו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הן\u0004 שלושה ימים שלמים \u0003בלא אידיהן,\u0004 שהם כשלעצמם ודאי אסורים?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה להלן, \u0003ר' ישמעאל אומר: שלשה לפניהם ושלשה לאחריהן אסור.\u0004 ומעתה, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ש\u0003הן ואידיהן\u0004 בכלל \"שלושה ימים\", אם כן יוצא ש\u0003ר' ישמעאל יום אידיהן חשיב להו מעיקרא וחשיב להו לבסוף\u0004 \u0005[מחשיב\u0006 גם \u0005מתחילה ומחשיב\u0006 גם \u0005בסוף],\u0006 ונמצא שהוא מונה אותו פעמיים! אלא מכאן שמדובר על שלושה ימים מלבד יום אידם.","ומשיבים: גם אם יום אידם בכלל \"שלושה ימים\", ניתן להסביר כי \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 בלשון \u0003\"שלשה לפניהם\", תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003\"שלשה לאחריהם\",\u0004 שהרי מדובר באותו מספר של ימים לפני יום האיד ולאחריו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לבעיה ממה ש\u0003אמר רב תחליפא בר אבדימי אמר שמואל: נוצרים לדברי ר' ישמעאל לעולם אסור\u0004 לשאת ולתת עמהם, שהרי יום ראשון בכל שבוע הוא יום חגם, ואם שלושה ימים לפניו ושלושה לאחריו אסורים — נמצא שכל השבוע אסור. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לפרש ששלושה ימים במשנתנו \u0003הן ואידיהן\u0004 בכללם, ורק יומיים לפניהם ולאחריהם אסורים, \u0003האיכא\u0004 \u0005[הרי יש]\u0006 \u0003ארבעה וחמשה,\u0004 כלומר יום רביעי ויום חמישי, \u0003דשרי\u0004 \u0005[ש\u0006צריכים להיות \u0005מותרים]\u0006 לדעת ר' ישמעאל!","ומשיבים: \u0003אליבא\u0004 \u0005[לדעת]\u0006 \u0003ר' ישמעאל לא קמבעיא\u0004 \u0005[נסתפק]\u0006 \u0003לי\u0004 ששלושה ימים כוונתו \u0003הן בלא אידיהן, כי קא מבעיא\u0004 \u0005[כאשר נסתפק]\u0006 \u0003לי\u0004 — הרי זה \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בהמשך למשנתנו: \u0003ואלו הן אידיהן של גוים:\u0004 \u0003קלנדא, סטרונייא, וקרטסים. ואמר רב חנין בר רבא:\u0004 מתי חוגגים הגויים חגים אלה? \u0003קלנדא\u0004 — במשך \u0003שמונה ימים אחר תקופה\u0004 (תקופת טבת, היום הקצר בשנה), \u0003סטרונייא\u0004 — \u0003שמונה ימים לפני תקופה, וסימנך,\u0004 כדי שנזכור את סדר הדברים: \u0003\"אחור וקדם צרתני\"\u0004 (תהלים קלט, ה), כלומר, המאוחר (\"אחור\") הוא המוזכר תחילה, ואחר כך המוקדם (\"קדם\").","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שהתנא מונה במשנתנו \u0003הן ו\u0004גם \u0003אידיהן,\u0004 קשה הדבר, שהרי בחגים שהוא הולך ומפרט \u0003עשרה\u0004 ימים \u0003הוו\u0004 \u0005[הם]\u0006 שאסורים, שמונה ימי אידם ועוד יומיים לפני כן! ומשיבים: ה\u0003תנא, כוליה קלנדא חד יומא הוא חשיב ליה\u0004 \u0005[\u0006את \u0005כל\u0006 החג של \u0005קלנדא יום אחד הוא מונה אותו],\u0006 ואין מכאן ראיה.","\u0003אמר רב אשי, תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה מדיוק נוסח לשון המשנה, ששנינו: \u0003\"לפני אידיהן של גוים שלשה ימים\", ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שהכוונה היא ל\u0003הן ואידיהן, ליתני\u0004 \u0005[שישנה]\u0006 כך: \u0003אידיהן של גוים\u0004 אסורים \u0003שלשה ימים!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003האי דקתני\u0004 \u0005[זה ששנה]\u0006 \u0003\"לפני אידיהן\"\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003לאחר אידיהן,\u0004 שלא נבין כי החל מיום אידם נאסרים שלושה ימים, אם כן, \u0003ליתני\u0004 \u0005[שישנה]\u0006 כך: \u0003אידם של גוים\u0004 אסורים \u0003שלשה ימים לפניהם! אלא שמע מינה\u0004 \u0005[למד מכאן],\u0006 שמה שאמרנו \"לפני אידיהן שלושה ימים\" כוונתו \u0003הן בלא אידיהן,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם טעם האיסור לשאת ולתת עם הגוים לפני אידם הוא \u0003משום הרווחה,\u0004 שהדבר גורם להם נחת רוח והם באים ומודים לעבודה זרה שלהם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום\u0004 שהוא עובר על האיסור \u0003\"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שהוא מזמן להם בהמה להקריב אותה לעבודה זרה שאסורה להם?","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מהו ההבדל להלכה בין שני הטעמים הללו? כגון במקרה \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 לגוי \u0003בהמה לדידיה\u0004 \u0005[לעצמו],\u0006 \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שטעם האיסור הוא \u0003משום הרווחה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 אף במקרה זה \u0003קא מרווח ליה\u0004 \u0005[מרויח לו]\u0006 היהודי לגוי. אבל \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003משום\u0004 \"לפני \u0003עור לא תתן מכשל\"\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 במקרה זה \u0003אית ליה לדידיה\u0004 \u0005[יש לו\u0006 לגוי בהמה \u0005משלו],\u0006 ואין היהודי מכשילו בכך.","ושואלים: \u0003וכי אית ליה\u0004 \u0005[וכאשר יש לו\u0006 משלו\u0005]\u0006 \u0003לא עבר\u0004 המסייע לו \u0003משום\u0004 \"לפני \u0003עור לא\u0004 \u0003תתן מכשל\"? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' נתן:\u0004"],["\u0003מנין שלא יושיט אדם כוס של יין לנזיר\u0004 (שאסור לו לשתות יין), \u0003ואבר מן החי לבני נח? תלמוד לומר: \"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד); \u0003והא הכא, דכי לא יהבינן ליה, שקלי איהו\u0004 \u0005[והרי כאן,\u0006 בשני מקרים אלה, \u0005שאם אין אנו נותנים לו, לוקח הוא\u0006 בעצמו\u0005],\u0006 \u0003וקעבר\u0004 \u0005[ו\u0006מכל מקום \u0005הוא עובר]\u0006 \u0003משום \"לפני עור לא תתן מכשל\"!\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דקאי בתרי עברי נהרא\u0004 \u0005[ש\u0006הם \u0005עומדים בשני צדדים של הנהר]\u0006 שהמקבל אינו יכול לקחת בעצמו, ורק על ידי המושיט לו היה מקבלם, ומשום כך הוא עובר על \"לפני עיוור\". ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן כך],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בדברי ר' נתן, \u0003\"לא יושיט\", ולא קתני\u0004 \u0005[שונה]\u0006 \u0003\"לא יתן\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהכוונה היא שהוא מושיט מצד אחד של נהר לצידו השני.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים השאלה\u0005]:\u0006 אם עבר על דברי חכמים שבמשנה ו\u0003נשא ונתן\u0004 עם הנכרים לפני אידיהם, \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003ר' יוחנן אמר: נשא ונתן\u0004 — \u0003אסור\u0004 ליהנות מן הרווח. \u0003ריש לקיש אמר: נשא ונתן\u0004 — \u0003מותר.\u0004 כלומר, אף שעבר על דברי חכמים, אין התוצאות אסורות. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בברייתא: \u0003אידיהן של גוים נשא ונתן\u0004 — הרווחים שמאותו מעשה \u0003אסורין, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שנשא ונתן עם הגוים \u0003לפני אידיהן?\u0004 השיב לו ריש לקיש: \u0003לא,\u0004 הכוונה היא למשא ומתן ב\u0003אידיהן דוקא,\u0004 ביום אידם ממש, אבל לא לפני כן.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היה הדבר, אלא \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן\u0004 ממה ששנינו: \u0003אידיהן של גוים\u0004 אם \u0003נשא ונתן\u0004 — \u0003אסור,\u0004 ונדייק מכאן: \u0003אידיהן\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 בהם אסור, אבל \u0003לפני אידיהן\u0004 — \u0003לא!\u0004 והשיב לו ר' יוחנן: ה\u0003תנא, אידי ואידי\u0004 \u0005[זה וזה],\u0006 לפני האיד והאיד עצמו, \u0003\"אידיהן\" קרי ליה\u0004 \u0005[הוא קורא לו],\u0006 ולכן אין מקום לדיוק זה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש: כשאמרו\u0004 חכמים \u0003אסור לשאת ולתת עמהם\u0004 — \u0003לא אסרו אלא בדבר המתקיים, אבל בדבר שאינו מתקיים\u0004 — \u0003לא\u0004 אסרו, \u0003ואפילו בדבר המתקיים\u0004 אם \u0003נשא ונתן\u0004 — \u0003מותר. תני\u0004 \u0005[שנה]\u0006 \u0003רב זביד בדבי\u0004 \u0005[ב\u0006ברייתא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אושעיא: דבר שאין מתקיים מוכרין להם, אבל אין לוקחין\u0004 (קונים) \u0003מהם.\u0004","מסופר, \u0003ההוא מינאה דשדר ליה דינרא קיסרנאה\u0004 \u0005[מין אחד ששלח לו דינר קיסרי]\u0006 \u0003לר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003ביום אידו\u0004 של אותו מין, \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ריש לקיש קמיה\u0004 \u0005[לפניו],\u0006 \u0003אמר\u0004 לו ר' יהודה נשיאה: \u0003היכי אעביד\u0004 \u0005[איך אעשה]?\u0006 ופירט את ספקו: אם \u0003אשקליה\u0004 \u0005[אקבלנו]\u0006 לדינר זה — \u0003אזיל ומודה\u0004 \u0005[ילך ויודה]\u0006 לעבודה זרה על שהתקיים רצונו, ואם \u0003לא אשקליה\u0004 \u0005[אקבלנו]\u0006 — \u0003הויא ליה\u0004 \u0005[תהיה לו]\u0006 \u0003איבה\u0004 כלפי! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש\u0004 כהצעה: \u0003טול וזרוק אותו לבור בפניו\u0004 של אותו המין. \u0003אמר\u0004 לו ר' יהודה נשיאה: \u0003כל שכן דהויא ליה\u0004 \u0005[שתהיה לו]\u0006 \u0003איבה\u0004 אם הוא יראה אותי עושה כן! הסביר ריש לקיש את דבריו: \u0003כלאחר יד הוא דקאמינא\u0004 \u0005[שאני אומר].\u0006 כלומר, לא שתזרוק כעושה בכוונה, אלא שייראה הדבר כאילו נפל מידך לבור.","שנינו במשנה שאסור \u0003להשאילן ולשאול מהן\u0004 שלושה ימים לפני אידם. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003להשאילן\u0004 אסור — משום \u0003דקא מרווח להו\u0004 \u0005[שהוא גורם להם רווח],\u0006 \u0003אבל לשאול מהן\u0004 — הרי \u0003מעוטי קא ממעט להו\u0004 \u0005[ממעט הוא מהם]\u0006 את קניינם בזמן חגם! \u0003אמר אביי:\u0004 חכמים גזרו \u0003גזרה\u0004 שלא יבוא גם \u0003לשאול מהן אטו\u0004 \u0005[משום]\u0006 האיסור \u0003להשאילן. רבא אמר: כולה\u0004 \u0005[הכל]\u0006 נאסר \u0003משום דאזיל\u0004 \u0005[שהולך]\u0006 הגוי \u0003ומודה הוא\u0004 לעבודה זרה, שפעמים שיש לו נחת רוח מזה שהוא משאיל לישראל.","ועוד שנינו במשנה שאסור \u0003להלוותם וללוות מהן.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003להלוותם\u0004 — \u0003משום דקא מרווח להו\u0004 \u0005[שהוא גורם להם רווח],\u0006 \u0003אלא ללוות מהן\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 זה אסור? \u0003אמר אביי: גזירה\u0004 היא, \u0003ללוות מהן אטו\u0004 \u0005[משום]\u0006 האיסור \u0003להלוותם. רבא אמר: כולה\u0004 \u0005[והכל]\u0006 נאסר \u0003משום דאזיל\u0004 \u0005[שהולך]\u0006 \u0003ומודה הוא.\u0004","ועוד שנינו שאסור \u0003לפורען ולפרוע מהן.\u0004 ושוב שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לפורען\u0004 — \u0003משום דקא מרווח להו\u0004 \u0005[שהוא גורם להם רווח]\u0006 שהוא נותן להם את הכסף באותו זמן, \u0003אלא לפרוע מהן,\u0004 מדוע? הרי \u0003מעוטי ממעט להו\u0004 \u0005[ממעט\u0006 הוא \u0005להם]!\u0006 וכמו בדינים הקודמים, \u0003אמר אביי: גזירה לפרוע מהן אטו\u0004 \u0005[משום]\u0006 \u0003לפורען. רבא אמר: כולה\u0004 \u0005[הכל]\u0006 \u0003משום דאזיל\u0004 \u0005[שהולך\u0006 \u0003ומודה הוא.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[וצריך]\u0006 לפרש את שלושת האיסורים הללו, ולא די לומר אחד מהם; \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק את האיסור \u0003לשאת ולתת עמהן,\u0004 היו אומרים שטעם הדבר הוא \u0003משום דקא מרווח להו ואזיל\u0004 \u0005[שהוא מרויח להם, והולך]\u0006 הגוי \u0003ומודה\u0004 \u0005[\u0006לעבודה זרה\u0005],\u0006 \u0003אבל לשאול מהן, דמעוטי קא ממעט להו\u0004 \u0005[ש\u0006על ידי כך הוא \u0005ממעט להם]\u0006 — \u0003שפיר דמי\u0004 \u0005[טוב הדבר].\u0006","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 גם \u0003לשאול מהן,\u0004 הייתי אומר: \u0003משום דחשיבא ליה מילתא\u0004 \u0005[שחשוב לו הדבר]\u0006 שישראל נזקק לו, \u0003ו\u0004לכן הוא \u0003אזיל\u0004 \u0005[הולך]\u0006 \u0003ומודה.\u0004 \u0003אבל ללוות מהן,\u0004 הייתי אומר שהוא מותר, משום ש\u0003צערא בעלמא אית ליה\u0004 \u0005[צער בלבד יש לו]\u0006 מזה שהוא נותן כסף, ומדוע? \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]:\u0006 \u0003תוב לא הדרי זוזי\u0004 \u0005[שוב לא יחזרו הכספים\u0006 שלי\u0005],\u0006 שמא לא יחזיר היהודי את החוב.","\u0003ואי תנא\u0004 \u0005[ו\u0006גם \u0005אם היה שונה]\u0006 איסור \u0003ללוות מהן,\u0004 הייתי אומר \u0003משום דקאמר\u0004 \u0005[שהוא,\u0006 הגוי, \u0005אומר]:\u0006 \u0003בעל כרחיה מיפרענא\u0004 \u0005[בעל כרחו איפרע ממנו],\u0006 מן היהודי, שיכול אני להיפרע ממנו מכוח השטר, \u0003והשתא מיהא אזיל\u0004 \u0005[ועכשיו על כל פנים הולך]\u0006 \u0003ומודה\u0004 שהיהודי נזקק לו, \u0003אבל ליפרע מהן\u0004 לגבות מהם את החוב, \u0003דתו לא הדרי זוזי\u0004 \u0005[ששוב אין הכספים חוזרים]\u0006 אליו — \u0003אימא צערא אית ליה, ולא אזיל\u0004 \u0005[אמור שיש לו צער בדבר, ואינו הולך]\u0006 \u0003ומודה,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כל אלה.","שנינו במשנה, \u0003ר' יהודה אומר: נפרעין מהן\u0004 משום שבכך מיצר הוא לו. אמרו לו: אף על פי שמיצר הוא עכשיו — שמח הוא לאחר זמן, שפרע את חובו. ושואלים: \u0003ולית ליה\u0004 \u0005[והאם אין לו]\u0006 \u0003לר' יהודה\u0004 נימוק זה ש\u0003אף על פי שמיצר עכשיו שמח הוא לאחר זמן?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה]\u0006 ברייתא\u0005,\u0006 \u0003ר' יהודה אומר: אשה לא תסוד\u0004 (תמרח סיד על איברי גופה) \u0003במועד\u0004 כדי להסיר את השיער ולעדן את העור, \u0003מפני שניוול הוא לה\u0004 בסיד זה כשהוא עליה, אבל \u0003מודה ר' יהודה בסיד\u0004 כזה \u0003שיכולה\u0004 היא \u0003לקפלו\u0004 (להורידו) \u0003ב\u0004תוך ה\u0003מועד שטופלתו\u0004 (שיכולה היא למורחו) \u0003במועד,\u0004 משום ש\u0003אף על פי שמצירה עכשיו, שמחה היא לאחר זמן,\u0004 כשהיא נראית יפה יותר בהמשך המועד. משמע שר' יהודה עצמו מקבל נימוק זה!","\u0003אמר רב נחמן בר יצחק: הנח להלכות מועד,\u0004 כלומר, למלאכות שהתירו לעשותן בחול המועד, \u0003דכולהו\u0004 \u0005[שכולם]\u0006 בנויות על כך שהוא \u0003מיצר עכשיו,\u0004 שהוא טורח במלאכה, משום \u0003שמחה לאחר זמן,\u0004 במועד עצמו, ומשום שמחת המועד. ואינו כן בהלכות עבודה זרה. \u0003רבינא אמר: גוי לענין פרעון לעולם מיצר\u0004 שצריך לשלם את חובו, ואינו שמח אף לאחר מכן.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 שאסרה להיפרע מהם בכל מקרה, היא ש\u0003לא כ\u0004שיטת \u0003ר' יהושע בן קרחה, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: מלוה בשטר אין נפרעין מהן,\u0004 שהרי יכול הוא תמיד להיפרע מן הגוי בשטר שבידו. אבל \u0003מלוה על פה נפרעין מהן,\u0004 ומדוע? \u0003מפני שהוא כמציל מידם,\u0004 שהרי אין שטר על המילוה, ושמא לא יחזיר לו חובו בזמן אחר.","מסופר, \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב יוסף אחוריה\u0004 \u0005[אחורי]\u0006 \u0003ר' אבא\u0004 בבית המדרש, \u0003ויתיב\u0004 \u0005[ויושב היה]\u0006 \u0003ר' אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא\u0004 כתלמיד לפני רבו, \u0003ויתיב וקאמר\u0004 \u0005[ויושב היה\u0006 רב הונא \u0005ואומר]\u0006 את הדברים הבאים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יהושע בן קרחה, והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כר' יהודה.\u0004","ומסבירים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יהושע\u0004 בן קרחה — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בעניין ההיתר להיפרע מהם מילוה על פה. והלכה \u0003כר' יהודה,\u0004 לגבי זו \u0003דתניא\u0004 \u0005[ששנינו]:\u0006 \u0003הנותן\u0004 \u0003צמר לצבע לצבוע לו\u0004 בגד בצבע \u0003אדום וצבעו\u0004 בצבע \u0003שחור,\u0004 או שנתן לו בגד לצבוע לו \u0003שחור וצבעו אדום,\u0004"],["\u0003ר' מאיר אומר: נותן לו\u0004 האומן לבעל הבית את \u0003דמי צמרו,\u0004 שכיון ששינה מדעת בעל הבית שינוי כזה נעשה בכך כגזלן, שדינו שקונה את החפץ הנגזל על ידי השינוי שעושה בו, ונוטלו, ומחזיר את שוויו כבתחילה. \u0003ר' יהודה אומר:\u0004 לא קנה האומן את הצמר, וצריך בעל הצמר לתת לו את הוצאותיו, ובלבד שלא יפסיד על ידי כך, ולכן, \u0003אם השבח\u0004 כלומר, עליית ערכו של הבגד על ידי הצביעה \u0003יתר על היציאה\u0004 (ההוצאה) שהוציא האומן בצביעה — \u0003נותן לו\u0004 בעל הצמר רק \u0003את היציאה,\u0004 \u0003ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו\u0004 רק \u0003את השבח.\u0004 כל זה אמר רב הונא.","\u0003אהדרינהו\u0004 \u0005[החזיר]\u0006 \u0003רב יוסף לאפיה\u0004 \u0005[את פניו],\u0006 להראות בכך שאין דעתו נוחה בדברים אלה, ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לפסוק \u0003הלכה כר' יהושע בן קרחה\u0004 — \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לומר את הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הואיל ובכל מקום שנחלקו \u0003יחיד ורבים\u0004 \u0003הלכה כרבים\u0004 — יהא אף כאן הדין כן, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבמקרה זה \u0003הלכה כיחיד.\u0004","\u0003אלא הלכה כר' יהודה למה לי\u0004 לומר? \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי כלל ידוע הוא, שאם יש \u0003מחלוקת\u0004 במשנה \u0003ואחר כך\u0004 נאמר הדבר במשנה אחרת ב\u0003סתם,\u0004 בלא מחלוקת ובלא להזכיר שזו דעתו של חכם מסויים — \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כסתם.\u0004","והרי \u0003מחלוקת\u0004 זו בין ר' מאיר ור' יהודה מצויה \u0003בבבא קמא\u0004 \u0005[בשער הראשון\u0006 של מסכת נזיקין\u0005],\u0006 \u0003וסתם\u0004 יש בענין הזה \u0003בבבא מציעא\u0004 \u0005[בשער האמצעי],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 במסכת בבא מציעא: \u0003כל המשנה\u0004 — \u0003ידו על התחתונה, וכל החוזר בו\u0004 — \u0003ידו על התחתונה.\u0004 הרי שסתמו במשנה כשיטת ר' יהודה, האומר שהאומן ששינה מדעת בעל הבית — ידו על התחתונה!","ומסבירים: \u0003ורב הונא,\u0004 מה טעם היה צריך להגיד הלכה זו? \u0003משום\u0004 שהוא סבור ש\u0003אין סדר למשנה,\u0004 ולכן אי אפשר לדעת אם המשנה שבמסכת בבא קמא קודמת לזו שבבבא מציעא או להיפך, \u0003דאיכא למימר\u0004 \u0005[שאפשר לומר]\u0006 ש\u0003סתם\u0004 ה\u0003תנא ברישא\u0004 \u0005[בתחילה]\u0006 כפי שהוא במסכת בבא מציעא \u0003ואחר כך\u0004 שנה את ה\u0003מחלוקת.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין סדר למשנה, \u0003כל מחלוקת ואחר כך סתם\u0004 — \u0003לימא\u0004 \u0005[אמור]\u0006 באותו אופן ש\u0003אין סדר למשנה!\u0004","\u0003ורב הונא\u0004 סבור: \u0003כי לא אמרינן\u0004 \u0005[כאשר אין אנו אומרים]\u0006 \u0003אין סדר\u0004 למשנה — הרי זה \u0003בחדא מסכתא\u0004 \u0005[במסכת אחת],\u0006 שבכל מסכת לעצמה יש משמעות לסדר הדברים, אבל \u0003בתרי מסכתי אמרינן\u0004 \u0005[בשתי מסכתות אומרים אנו]\u0006 שאין סדר למשנה, שאיננו יודעים איזו מהן נשנית אחרונה. \u0003ו\u0004אילו \u0003רב יוסף\u0004 סבור: \u0003כולה נזיקין חדא מסכתא\u0004 \u0005[כל\u0006 מסכת \u0005נזיקין,\u0006 בבא קמא, בבא מציעא ובבא בתרא, \u0005מסכת אחת]\u0006 \u0003היא,\u0004 ויש בה סדר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 טעם אחר היה לו שסבור היה שיש לפסוק כר' יהודה, לא בגלל סדר המשנה, אלא \u0003משום דקתני לה גבי הלכתא פסיקתא\u0004 \u0005[ששנה אותה\u0006 את ההלכה הזו \u0005אצל הלכות פסוקות],\u0006 ומשמע שאף היא הלכה פסוקה וחתוכה, שכן שנינו שם: \u0003כל המשנה\u0004 — \u0003ידו על התחתונה, וכל החוזר בו\u0004 — \u0003ידו על התחתונה.\u0004","מתוך שנזכר כאן שפסקו כר' יהושע בן קרחה, מביאים עוד כמה הלכות שנפסקו כדבריו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יאמר אדם לחבירו\u0004 בשבת: \u0003\"הנראה שתעמוד עמי לערב\",\u0004 וירמוז לו בכך שהוא רוצה לשכור אותו לעבודה במוצאי שבת. \u0003ר' יהושע בן קרחה אומר: אומר אדם לחבירו, \"הנראה שתעמוד עמי לערב\",\u0004 כיון שלא אמר לו דברים במפורש. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכתא\u0004 \u0005[הלכה]\u0006 בענין זה \u0003כר' יהושע בן קרחה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנשאל\u0004 שאלה \u0003לחכם\u0004 בדיני טומאה וטהרה, \u0003ו\u0004אותו חכם \u0003טימא\u0004 — \u0003לא ישאל לחכם\u0004 אחר \u0003ו\u0004אותו חכם \u0003יטהר,\u0004 וכן אם נשאל \u0003לחכם ואסר\u0004 — \u0003לא ישאל לחכם\u0004 אחר \u0003ויתיר.\u0004","\u0003היו שנים,\u0004 שני חכמים, יושבים יחד, \u0003אחד\u0004 מהם \u0003מטמא ואחד מטהר, אחד אוסר ואחד מתיר,\u0004 והשואל אינו יודע מה לעשות, הכלל הוא כך: \u0003אם היה אחד מהם\u0004 מהחולקים \u0003גדול מחבירו בחכמה ובמנין\u0004 — \u0003הלך אחריו, ואם לאו\u0004 — \u0003הלך אחר המחמיר,\u0004 מכיון שאין אתה יודע אחרי מי ללכת. \u0003ר' יהושע בן קרחה אומר:\u0004 אם היה הספק הזה \u0003ב\u0004דבר \u0003של תורה הלך אחר המחמיר,\u0004 אם היה זה \u0003בשל סופרים\u0004 (שמדברי חכמים), \u0003הלך אחר המיקל. אמר רב יוסף: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יהושע בן קרחה.\u0004","ועוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003וכולן\u0004 כל אלה שאמרו שהם פסולים מחמת חטאיהם ואינם נאמנים, \u0003שחזרו בהן\u0004 בתשובה — \u0003אין מקבלין אותן\u0004 עוד \u0003עולמית\u0004 (לעולם), אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם \u0003חזרו בהן במטמוניות\u0004 (בסתר) — \u0003אין מקבלין אותן,\u0004 אבל אם חזרו בהן \u0003בפרהסיא\u0004 — \u0003מקבלין אותן. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הדברים האלה באופן אחר: אם \u0003עשו דבריהם\u0004 (חטאיהם) \u0003במטמוניות,\u0004 עשו אותם בסתר — כאשר יעשו תשובה \u0003מקבלין אותן,\u0004"],["\u0003בפרהסיא\u0004 — \u0003אין מקבלין אותן. ר' שמעון ור' יהושע בן קרחה אומרים: בין כך ובין כך\u0004 בין בצנעה ובין בפרהסיא \u0003מקבלין\u0004 אותם, \u0003שנאמר: \"שובו בנים שובבים\u0004 ארפה משובותיכם\" (ירמיהו ג, כב). \u0003אמר ר' יצחק איש כפר עכו אמר ר' יוחנן: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כאותו הזוג,\u0004 ר' שמעון ור' יהושע בן קרחה, שמקבלים אותם בכל אופן, כשחוזרים בתשובה.","\u0003ר' ישמעאל אומר: שלשה\u0004 ימים \u0003לפניהם\u0004 לפני אידיהם של הגוים, \u0003ושלשה לאחריהם\u0004 — \u0003אסור\u0004 לשאת ולתת עם הגוים. \u0003וחכמים אומרים: לפני אידיהן\u0004 — \u0003אסור,\u0004 אבל \u0003לאחר אידיהן\u0004 — \u0003מותר.\u0004","\u0003אמר רב תחליפא בר אבדימי אמר שמואל: נוצרי, לדברי ר' ישמעאל לעולם אסור\u0004 לאדם מישראל לשאת ולתת עמו, שהרי יום ראשון הוא יום חגו, ושלושה ימים לפניו ושלושה לאחריו הריהם כל השבוע.","שנינו במשנה: \u0003\"וחכמים אומרים: לפני אידיהן אסור, לאחר אידיהן\u0004 \u0003מותר\".\u0004 ושואלים: שיטת \u0003חכמים היינו תנא קמא\u0004 \u0005[זו היא\u0006 שיטתו של \u0005התנא הראשון],\u0006 במשנה הראשונה, שאמר שאסורים שלושה ימים לפני אידיהן! ומשיבים: לגבי השאלה האם \u0003הן\u0004 \u0003בלא\u0004 (מלבד) \u0003אידיהן\u0004 אסורים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003הן בלא אידיהן,\u0004 ששלושה ימים אסורים מלבד יום אידם, \u0003ורבנן בתראי סברי\u0004 \u0005[וחכמים אחרונים\u0006 שבמשנתנו \u0005סבורים]:\u0006 \u0003הן ואידיהן,\u0004 שהאיד בכלל שלושת הימים.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006 באופן אחר\u0005]:\u0006 בדינו של מי ש\u0003נשא ונתן איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 אם עבר ו\u0003נשא ונתן\u0004 — \u0003מותר, ורבנן בתראי סברי\u0004 \u0005[וחכמים אחרונים סבורים]:\u0006 שאם \u0003נשא ונתן\u0004 — \u0003אסור.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לגבי מה שאמר \u0003שמואל איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם],\u0006 ש\u0003אמר שמואל: בגולה\u0004 הקלו, ו\u0003אין אסור אלא יום אידם\u0004 בלבד\u0003, תנא קמא אית ליה\u0004 \u0005[התנא הראשון יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003שמואל, רבנן בתראי לית להו\u0004 \u0005[חכמים אחרונים אין להם,\u0006 אינם מקבלים\u0005]\u0006 את דברי שמואל.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 דבריו של \u0003נחום המדי איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003נחום המדי אומר: אינו אסור אלא יום אחד לפני אידיהן, תנא קמא לית ליה\u0004 \u0005[התנא הראשון אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003נחום המדי, ורבנן בתראי אית להו\u0004 \u0005[וחכמים אחרונים יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003נחום המדי,\u0004 שהרי לא הוזכר בדבריהם מספר הימים האסורים.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של מאמר זה שהזכרנו, מביאים את הדברים במלואם. \u0003נחום המדי אומר: אינו אסור אלא יום אחד לפני אידיהן. אמרו לו: נשתקע הדבר ולא נאמר,\u0004 כלומר דבר זה אינו הלכה כלל, ומוטב שלא ייאמר. ושואלים: \u0003והאיכא רבנן בתראי דקיימי כוותיה\u0004 \u0005[והרי יש חכמים אחרונים\u0006 במשנתנו \u0005שעומדים\u0006 שסבורים \u0005כמותו]!\u0006 ודוחים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? \u0003נחום המדי הוא,\u0004 והוזכרו דבריו בלשון חכמים.","ומביאים דברים נוספים שאמר נחום המדי. \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003נחום המדי אומר:\u0004 למרות שאין מוכרים לגוים בהמה גסה, \u0003מוכרין להן סוס זכר וזקן במלחמה\u0004 לפי שאינם מועילים כלל ללחימה. \u0003אמרו לו: נשתקע הדבר ולא נאמר.\u0004","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003בן בתירא דקאי כוותיה\u0004 \u0005[שעומד\u0006 שסבור \u0005כמותו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בן בתירא מתיר בסוס\u0004 למוכרו לגוים! ומשיבים: \u0003בן בתירא לא מפליג\u0004 \u0005[מחלק]\u0006 \u0003בין זכרים לנקבות, איהו מדקא מפליג\u0004 \u0005[הוא,\u0006 נחום המדי, \u0005כיון שהוא מחלק]\u0006 \u0003בין זכרים לנקבות\u0004 אם כן, משמע \u0003כרבנן סבירא ליה\u0004 \u0005[\u0006ש\u0005כ\u0006דעת \u0005חכמים הוא סבור],\u0006 שבדרך כלל אסור למכור סוס לגוים, והוא מתיר רק במקרה מיוחד זה. \u0003ולרבנן\u0004 \u0005[ול\u0006דעת \u0005חכמים]\u0006 אמרו לו האוסרים כי \u0003נשתקע הדבר ולא נאמר.\u0004","ועוד מחלוקת שצורתה דומה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003נחום המדי אומר:\u0004 צמח \u0003השבת מתעשר,\u0004 כלומר, חייב בהפרשת תרומות ומעשרות, בין כאשר משתמשים בו בצורת \u0003זרע, ו\u0004בין בצורת \u0003ירק, ו\u0004בין בצורת \u0003זירין\u0004 (גבעולים). \u0003אמרו לו: נשתקע הדבר ולא נאמר.\u0004 ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003ר' אליעזר דקאי כוותיה\u0004 \u0005[שעומד,\u0006 סבור, \u0005כמותו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: השבת מתעשרת זרע וירק וזירין!\u0004 ומשיבים: \u0003התם בדגנוניתא\u0004 \u0005[שם\u0006 מדובר בשבת \u0005של גינה],\u0006 שכיון שהוא מין תרבותי ומשובח, הריהו נאכל בכל שלושת האופנים, אבל שבת בר אינו מתעשר אלא זרע וירק, אבל לא זירים.","בעקבות דברים אלה שבין נחום המדי וחכמים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר מניומי לאביי: גברא רבה\u0004 \u0003אתא מאתרין\u0004 \u0005[אדם גדול בא ממקומנו,\u0006 ממדי\u0005],\u0006 נחום המדי, \u0003כל מילתא\u0004 \u0005[דבר]\u0006 ש\u0003אמר, אמרי ליה\u0004 \u0005[אומרים לו]\u0006 חכמים: \u0003נשתקע הדבר ולא נאמר,\u0004 וכי באים לבטל דווקא את דברי חכמי מדי? \u0003אומר\u0004 לו אביי: \u0003איכא חדא דעבדינן כוותיה\u0004 \u0005[יש\u0006 דבר \u0005אחד שאנו עושים כמותו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003נחום המדי אמר: שואל\u0004 (מבקש) \u0003אדם\u0004 בתפילת \"שמונה עשרה\" על \u0003צרכיו\u0004 דברים הנצרכים לו שאינם נכללים בבקשות הקבועות שבסדר התפילה, \u0003ב\u0004ברכת \u0003\"שומע תפלה\".\u0004","\u0003אמר\u0004 לו רב אחא בר מניומי: \u0003בר מינה דההיא\u0004 \u0005[חוץ ממנה, מאותה\u0006 הלכה\u0005],\u0006 שמכאן אין ראיה שקיבלו את דברי נחום המדי, \u0003דתליא\u0004 \u0005[ש\u0006כן \u0005תלויה]\u0006 הלכה זו \u0003ב\u0004מחלוקתם של \u0003אשלי רברבי\u0004 \u0005[אילנות גדולים]\u0006 (כינוי לאנשים גדולים) שעל פיהם אמרו את הדבר,","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: שואל אדם צרכיו ואחר כך יתפלל\u0004 תפילת שמונה עשרה, שיש בה דברי שבח ותהילה, \u0003שנאמר: \"תפלה לעני כי יעטף ולפני ה' ישפך שיחו\" וגו'\u0004 (תהלים קב, א), הרי שקודם הוא מבקש בצערו ועוניו (\"יעטוף\"), ואחר כך הוא שופך שיחה, ו\u0003אין שיחה אלא תפלה, שנאמר: \"ויצא יצחק לשוח בשדה\"\u0004 (בראשית כד, סג).","\u0003ר' יהושע אומר: יתפלל\u0004 תחילה, \u0003ואחר כך ישאל צרכיו, שנאמר: \"אשפך לפניו שיחי צרתי לפניו אגיד\"\u0004 (תהלים קמב, ג), קודם שיחה ואחר כך הזכרת הצרה.","ושואלים: \u0003ור' אליעזר נמי\u0004 \u0005[גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 תחילה: \u0003\"אשפך לפניו שיחי\"!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 הפסוק לשיטתו: \u0003אשפוך לפניו שיחי\u0004 — \u0003בזמן שצרתי לפניו אגיד\u0004 קודם לכן. ושואלים מצד אחר: \u0003ור' יהושע נמי\u0004 \u0005[גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"תפלה לעני כי יעטף\"\u0004 ורק אחר כך ישפוך שיחו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 הכתוב לשיטתו: \u0003אימתי תפלה לעני\u0004 כי יעטוף? \u0003בזמן שלפני ה' ישפוך שיחו,\u0004 שאחר כך מבקש צרכיו.","לגופו של דבר שואלים: \u0003מכדי קראי לא כמר דייקי ולא כמר דייקי\u0004 \u0005[הואיל והכתובים\u0006 עצמם \u0005לא כחכם זה מדוייקים ולא כחכם זה מדוייקים],\u0006 שמפסוק אחד בתהלים עולה סדר אחד ומהפסוק האחר עולה ההיפך, ואם כן, \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חלוקים]?\u0006 שהרי נראה שלא על סמך פסוקים אלה הם מתווכחים, אלא מטעם אחר.","ומשיבים: \u0003כדדריש\u0004 \u0005[כמו\u0006 מה \u0005שדרש]\u0006 \u0003ר' שמלאי, [דדריש\u0004 \u0005[שדרש]\u0006 \u0003ר' שמלאי]: לעולם יסדר אדם שבחו של מקום ואחר כך יתפלל\u0004 ויבקש\u0003,\u0004 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003ממשה רבינו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ה' אלהים אתה החלות להראות את עבדך\u0004 את גדלך ואת ידך החזקה אשר מי אל בשמים ובארץ אשר יעשה כמעשיך וכגבורותיך\" (דברים ג, כד), והרי אלו דברי שבחו של מקום. \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 בפסוק ש\u0005אחריו]\u0006 דברים של תחינה ובקשה: \u0003\"אעברה נא ואראה את הארץ הטובה\".\u0004"],["\u0003ר' יהושע סבר\u0004 \u0005[סבור]:\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003ממשה,\u0004 וכמוהו אנו עושים: תחילה אומרים תפילה שיש בה שבחיו של מקום, ואחר כך בקשה, \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003ממשה,\u0004 שננהג אף אנו כמותו. ומדוע? \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003משה דרב גובריה\u0004 \u0005[שגדול כוחו]\u0006 וגדולים מעשיו, והוא יכול היה לשבח תחילה כראוי. \u0003וחכמים אומרים: לא כדברי זה ולא כדברי זה,\u0004 לא יבקש אדם צרכיו לא קודם התפילה ולא אחריה, \u0003אלא שואל אדם צרכיו ב\"שומע תפלה\",\u0004 וכדבריהם אמר גם נחום המדי.","ובפסק ההלכה בעניין זה, \u0003אמר רב יהודה אמר שמואל, הלכה: שואל אדם צרכיו ב\"שומע תפלה\". אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אף על פי שאמרו\u0004 ש\u0003שואל אדם צרכיו ב\"שומע תפלה\", אבל\u0004 (באמת) \u0003אם בא לומר\u0004 \u0003בסוף כל ברכה וברכה מעין\u0004 עניינה של \u0003כל ברכה וברכה\u0004 — \u0003אומר.\u0004 כלומר, בכל ברכה יכול להוסיף ולבקש על ענייניו הפרטיים מעין אותה ברכה.","וכעין זה \u0003אמר ר' חייא בר אשי אמר רב: אף על פי שאמרו\u0004 ש\u0003שואל אדם צרכיו ב\"שומע תפלה\", אם יש לו חולה בתוך ביתו\u0004 — \u0003אומר בברכת חולים\u0004 בקשה מיוחדת לחולה זה, \u0003ואם צריך לפרנסה\u0004 — \u0003אומר\u0004 ומבקש על כך \u0003בברכת השנים.\u0004","ובצד אחר — \u0003אמר ר' יהושע בן לוי, אף על פי שאמרו: שואל אדם צרכיו ב\"שומע תפלה\", אבל אם בא לומר\u0004 דברי תפילה ותחנונים \u0003אחר תפלתו, אפילו\u0004 מאריך \u0003כסדר\u0004 וידוי של \u0003יום הכפורים\u0004 — \u0003אומר,\u0004 ואין רע בדבר.","\u0003ואלו אידיהן של גוים: קלנדא, וסטרנורא, וקרטיסים, ויום גנוסיא\u0004 (יום חגיגה) \u0003של מלכיהם, ויום הלידה ויום המיתה\u0004 של מלכיהם, אלו \u0003דברי ר' מאיר. וחכמים אומרים: כל מיתה שיש בה שריפה\u0004 פומבית — \u0003יש בה\u0004 חג ל\u0003עבודה זרה, ושאין בה שריפה\u0004 — \u0003אין בה\u0004 חג ל\u0003עבודה זרה. אבל יום תגלחת זקנו ו\u0004יום תגלחת \u0003בלוריתו, ויום שעלה בו מן הים, ויום שיצא מבית האסורין, וגוי שעשה משתה לבנו\u0004 וחוגג באותו יום — בכל אלה \u0003אינו אסור\u0004 במשא ומתן וכיוצא בזה \u0003אלא אותו היום ואותו האיש בלבד\u0004 ולא אנשים אחרים.","\u0003אמר רב חנן בר רבא: קלנדא\u0004 — זמנה \u0003שמונה ימים אחר תקופה\u0004 של טבת — כלומר, אחרי היום הקצר ביותר בשנה, \u0003סטרנורא\u0004 — \u0003שמונה ימים לפני תקופה, וסימנך,\u0004 לבל תטעה ביניהם: \u0003\"אחור וקדם צרתני\" וגו'\u0004 (תהלים קלט, ה), שהחג המאוחר יותר (\"אחור\") הוא הנזכר ראשון במשנה, והמוקדם יותר נזכר אחר כך.","ובענין ימי איד אלה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לפי שראה אדם הראשון\u0004 את ה\u0003יום ש\u0004הוא \u0003מתמעט והולך,\u0004 שהימים מתקצרים (מתקופת שוויון היום והלילה עד היום הקצר), ולא ידע עדיין את מנהגו של עולם, \u0003אמר: אוי לי, שמא בשביל שסרחתי\u0004 (חטאתי) \u0003עולם חשוך בעדי\u0004 (מחשיך עלי) \u0003ו\u0004בסופו של דבר הריהו \u0003חוזר לתוהו ובוהו, וזו היא\u0004 אותה \u0003מיתה שנקנסה עלי מן השמים\u0004 (\"ואל עפר תשוב\", בראשית ג,יט), \u0003עמד וישב שמונה ימים בתענית [ובתפלה].\u0004","\u0003כיון שראה\u0004 שהגיעה \u0003תקופת טבת, וראה יום שמאריך והולך\u0004 מאותו זמן והלאה, \u0003אמר:\u0004 אם כן, מה שנתמעט היום מנהגו של עולם הוא, הלך ועשה שמונה ימים טובים. לשנה האחרת (הבאה) \u0003עשאן לאלו ולאלו\u0004 כלומר, לשמונה הימים שלפני התקופה שהתענה בהם, וגם לאלה שחגג בהם, \u0003ימים טובים. הוא\u0004 אדם הראשון \u0003קבעם\u0004 את החגיגות הללו \u0003לשם שמים, והם\u0004 הגוים \u0003קבעום לשם עבודה זרה.\u0004","ומבררים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003בתשרי נברא העולם,\u0004 אם כן, לפי זה \u0003יומי זוטי חזא\u0004 \u0005[ימים קטנים ראה],\u0006 שראה רק כיצד הימים מתקטנים והולכים מתשרי ואילך, \u0003יומי אריכי אכתי לא חזא\u0004 \u0005[ימים ארוכים עדיין לא ראה],\u0006 ולכן סבור היה שעונש משמים הוא. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003בניסן נברא העולם, הא חזא ליה יומי זוטי ויומי אריכי\u0004 \u0005[הרי ראה\u0006 כבר \u0005ימים קצרים וימים ארוכים],\u0006 שהרי בתקופת ניסן הימים קצרים והם הולכים ומתארכים! ומשיבים: מכל מקום, \u0003[דהוי] זוטי כולי האי לא חזא\u0004 \u0005[\u0006ימים \u0005שיהיו קטנים עד כדי כך,\u0006 כמו לפני תקופת טבת, \u0005לא ראה].\u0006","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יום שנברא בו אדם הראשון, כיון ששקעה עליו חמה, אמר: אוי לי, שבשביל שסרחתי\u0004 (שחטאתי) \u0003עולם חשוך בעדי ויחזור עולם לתוהו ובוהו, וזו היא מיתה שנקנסה עלי מן השמים, היה יושב [בתענית] ובוכה כל הלילה, וחוה בוכה כנגדו. כיון שעלה עמוד השחר, אמר:\u0004 \u0003מנהגו של עולם הוא,\u0004 שהחמה שוקעת ובא הלילה, \u0003עמד והקריב שור שקרניו קודמין\u0004 בבריאתם \u0003לפרסותיו,\u0004 \u0003שנאמר: \"ותיטב לה' משור פר מקרן מפריס\"\u0004 (תהלים סט, לב), שהוא השור היחיד שקודם הקרין קרניים ואחר כך הפריס פרסה.","\u0003ואמר רב יהודה אמר שמואל: שור שהקריב אדם הראשון\u0004 — \u0003קרן אחת\u0004 בלבד \u0003היתה [לו] במצחו, שנאמר: \"ותיטב לה' משור פר מקרן מפריס\".\u0004 ושואלים: \u0003\"מקרין\"\u0004 הלוא \u0003תרתי\u0004 \u0005[שתים,\u0006 שתי קרניים\u0005]\u0006 \u0003משמע! אמר רב נחמן בר יצחק: \"מקרן\" כתיב\u0004 \u0005[נאמר],\u0006 והוא רומז לכך שהיתה לו רק קרן אחת.","\u0003אמר רב מתנה: רומי שעשתה קלנדא\u0004 בתאריך מסויים, \u0003וכל העיירות הסמוכות לה משתעבדות לה\u0004 והן עצמן אינן חוגגות יום זה, האם \u0003אותן עיירות אסורות או מותרות\u0004 לשאת ולתת עם הגוים שבתוכן? \u0003ר' יהושע בן לוי אמר: קלנדא אסורה לכל היא,\u0004 ואף למשועבדים לרומי. \u0003ר' יוחנן אמר: אין אסורה אלא לעובדיה בלבד,\u0004 ואלה שאינם מחזיקים בה — אין זה בשבילם יום של עבודה זרה, ומותר.","\u0003תנא כוותיה\u0004 \u0005[שנה\u0006 החכם בברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: אף על פי שאמרו\u0004 ש\u0003רומי עשתה קלנדא, וכל עיירות הסמוכות לה משתעבדות לה,\u0004 מכל מקום \u0003היא עצמה\u0004 (קלנדא) \u0003אינה אסורה\u0004 במשא ומתן \u0003אלא לעובדיה בלבד.\u0004","וממשיכה הברייתא: חגי הגוים שנקראים \u0003סטרנליא וקרטסים, ו\u0004כן \u0003יום גנוסיא של מלכיהם, ויום שהומלך בו מלך\u0004 — \u0003לפניו אסור, אחריו מותר. וגוי שעשה (בו) משתה לבנו\u0004 — \u0003אין אסור אלא אותו היום\u0004 ולא לפניו ולא לאחריו, \u0003ואותו האיש\u0004 שעשה משתה.","\u0003אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 דבר זה\u0005],\u0006 שאמר ר' יוחנן שאין קלנדא אסורה אלא לעובדיה, \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנה\u0005]:\u0006 \u0003יום תגלחת זקנו ובלוריתו, ויום שעלה בו מן הים, ויום שיצא בו מבית האסורין\u0004 — \u0003אין אסור אלא אותו היום בלבד ואותו האיש.\u0004","ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה ששנינו \u0003\"אותו היום\"\u0004 — הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את הימים ש\u0003לפניו ולאחריו,\u0004 שבזה לא אסרו, \u0003אלא \"אותו האיש\" לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]?\u0006 והרי ברור הדבר שחגיגתו של אדם פרטי אחד אינה אוסרת אנשים אחרים! \u0003לאו לאפוקי\u0004 \u0005[האם לא להוציא]\u0006 את \u0003משעבדיו,\u0004 אלה המשועבדים לו? אם כן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מלשון המשנה שאותו האיש בלבד אסור, אבל אלה המשועבדים לו אינם בכלל זה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: ישראל שבחוצה לארץ עובדי עבודה זרה בטהרה הן, כיצד?\u0004 \u0003גוי שעשה משתה ל\u0004נישואי \u0003בנו וזימן כל היהודים שבעירו\u0004 למשתה זה, \u0003אף על פי ש\u0004הם באותה שעה \u0003אוכלין משלהן ושותין משלהן\u0004 מאכלים כשרים, \u0003ושמש שלהן עומד לפניהם,\u0004 בכל זאת \u0003מעלה עליהם הכתוב כאילו אכלו מזבחי מתים\u0004 כלומר, זבחי עבודה זרה, \u0003שנאמר:\u0004 \"וזבחו לאלהיהם \u0003וקרא לך ואכלת מזבחו\"\u0004 (שמות לד, טו), שהרי בסעודה זו הוא זובח לשם עבודה זרה שלו, ונחשב כאילו אכלו מזבחיו אלה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכוונת הכתוב היא \u0003עד דאכיל\u0004 \u0005[שיאכל]\u0006 ממש מזבחו! \u0003אמר רבא: אם כן,\u0004 אם זו היתה המשמעות, \u0003נימא קרא\u0004 \u0005[שיאמר המקרא]\u0006 \u0003\"ואכלת מזבחו\"\u0004 בלבד, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש התוספת בכתוב \u0003\"וקרא לך\"?\u0004 לומר ש\u0003משעת קריאה\u0004 אסור. \u0003הלכך\u0004 \u0005[על כן],\u0006"],["\u0003כל תלתין יומין\u0004 \u0005[שלושים יום]\u0006 לאחר אותו משתה נישואין שעשה הגוי לבנו, \u0003בין אמר ליה\u0004 \u0005[לו]\u0006 הנכרי לישראל ש\u0003מחמת הלולא\u0004 (שמחת הנישואין) הוא עושה סעודה זו, \u0003ובין לא אמר ליה\u0004 \u0005[לו]\u0006 ש\u0003מחמת הלולא\u0004 — בכל מקרה \u0003אסור,\u0004 שמן הסתם באותם שלושים ימים משום ההילולא הוא עושה את החגיגה. \u0003מכאן ואילך, אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ש\u0003מחמת הלולא\u0004 הוא עושה — \u0003אסור\u0004 הוא\u0003,\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אמר ליה\u0004 \u0005[לו],\u0006 ש\u0003מחמת הלולא\u0004 הוא עושה — \u0003שרי\u0004 \u0005[מותר].\u0006","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שהוא עושה את הסעודה \u0003מחמת הלולא, עד אימת\u0004 \u0005[אימתי]\u0006 נחשב הדבר כנספח וקשור לעבודה זרה? \u0003אמר רב פפא: עד תריסר ירחי שתא\u0004 \u0005[שנים עשר חודשי שנה].\u0006 ושואלים עוד: \u0003ומעיקרא מאימת\u0004 \u0005[ומתחילה,\u0006 מלפני יום השמחה שלו, \u0005מאימתי]\u0006 \u0003אסור? אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מכי רמו שערי באסינתי\u0004 \u0005[מכאשר\u0006 \u0005מטילים\u0006 את \u0005השעורים במכתשת]\u0006 כדי לעשות מהם שיכר, שעושים זאת זמן מסויים לפני השמחה.","ושואלים: \u0003ולבתר תריסר ירחי שתא שרי\u0004 \u0005[ולאחר שנים עשר חודשי שנה\u0006 מנישואי בנו \u0005מותר]\u0006 בכל אופן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא איקלע לבי ההוא גוי לבתר תריסר ירחי שתא\u0004 \u0005[הזדמן לבית גוי אחד לאחר שנים עשר חודשי שנה]\u0006 מנישואי בנו, \u0003ושמעיה דאודי\u0004 \u0005[ושמע אותו ש\u0006הוא \u0005מודה]\u0006 לעבודה זרה בגלל השמחה שהיתה לו, \u0003ופירש\u0004 (ופרש) מהסעודה הזו \u0003ולא אכל\u0004 ממנה! ומשיבים: מכאן אין ראיה, כי להלכה מותר הדבר, אלא \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא,\u0004 ש\u0003אדם חשוב הוא,\u0004 ושמח בו הגוי.","שנינו במשנה: \u0003וקרטסים וכו'.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003קרטסים? אמר רב יהודה אמר שמואל:\u0004 זהו \u0003יום שתפסה בו רומי מלכות,\u0004 ומשום כך עושים הם אותו יום שמחה לדורות. ומקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קרטסים ויום שתפסה בו רומי מלכות,\u0004 משמע שהם שני חגים נבדלים! \u0003אמר רב יוסף: שתי תפיסות תפסה רומי\u0004 את המלכות, \u0003אחת בימי קלפטרא מלכתא\u0004 \u0005[קליאופטרה המלכה]\u0006 שכבשו בה את מצרים, \u0003ואחת שתפסה בימי יונים\u0004 שנים רבות קודם לכן.","ומפרטים: \u0003דכי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: תלתין ותרין קרבי עבדו רומאי בהדי יונאי\u0004 \u0005[שלושים ושנים קרבות עשו הרומאים עם היוונים]\u0006 \u0003ולא יכלו להו\u0004 \u0005[להם]\u0006 לנצחם, \u0003עד דשתפינהו לישראל בהדייהו\u0004 \u0005[ששיתפו\u0006 הרומאים \u0005את ישראל עימם]\u0006 ואז ניצחו אותם, \u0003והכי אתנו בהדייהו\u0004 \u0005[וכך התנו\u0006 הרומאים \u0005איתם,\u0006 עם הישראלים\u0005]:\u0006 \u0003אי מינן מלכי, מנייכו הפרכי\u0004 \u0005[אם מאתנו\u0006 יהיו \u0005המלכים, מאיתכם\u0006 יהיו \u0005המושלים],\u0006 \u0003אי מנייכו מלכי, מינן הפרכי\u0004 \u0005[אם מאיתכם\u0006 יהיו \u0005המלכים, מאיתנו\u0006 יהיו \u0005המושלים].\u0006","\u0003ושלחו להו רומאי ליונאי\u0004 \u0005[להם הרומאים ליוונים]:\u0006 \u0003עד האידנא עבידנא בקרבא\u0004 \u0005[עכשיו עשינו\u0006 הכרעה בשלטון ובעולם \u0005על ידי קרבות],\u0006 \u0003השתא נעביד בדינא\u0004 \u0005[עכשיו נעשה בדין],\u0006 ומה הדין? אם יש \u0003מרגלית ואבן טובה, איזו מהן יעשה בסיס לחבירו? שלחו להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003מרגלית\u0004 תיעשה בסיס \u0003לאבן טובה,\u0004 שהיא יקרה ממנה.","חזרו ושאלו: אם היתה \u0003אבן טובה\u0004 רגילה \u0003ואינך\u0004 (שהוא אבן יקרה ביותר), \u0003איזו מהן יעשה בסיס לחבירו?\u0004 אמרו להם היוונים: \u0003אבן טובה לאינך.\u0004 ושוב שאלו הרומאים: אם היו \u0003אינך וספר תורה, איזו מהן יעשה בסיס לחבירו?\u0004 והשיבו: \u0003אינך לספר תורה.\u0004","\u0003שלחו להו\u0004 \u0005[להם]\u0006 הרומאים: \u0003[אם כן,]\u0004 הרי \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003ספר תורה גבן\u0004 \u0005[אצלנו]\u0006 \u0003וישראל בהדן\u0004 \u0005[איתנו],\u0006 ולכן ראויים אתם להיכנע תחתינו, משום שאנו גם יותר חשובים מכם (אבן טובה), ועמנו ישראל (\"אינך\") שעמם ספר התורה. \u0003כפו להו\u0004 \u0005[אותם]\u0006 הרומאים ולקחו מהם את השלטון בעולם. \u0003עשרין ושית שנין קמו להו בהימנותייהו בהדי\u0004 \u0005[עשרים ושש שנים עמדו להם\u0006 הרומאים \u0005בנאמנותם עם]\u0006 \u0003ישראל\u0004 וקיימו את ההסכם ביניהם, \u0003מכאן ואילך אישתעבדו בהו\u0004 \u0005[השתעבדו בהם]\u0006 הרומאים בישראל.","ומסבירים: \u0003מעיקרא מאי דרוש\u0004 \u0005[מתחילה מה דרשו]\u0006 בכתובים, \u0003ולבסוף מאי דרוש\u0004 \u0005[מה דרשו]?\u0006 \u0003מעיקרא דרוש\u0004 \u0005[מתחילה דרשו]\u0006 את הפסוק שאמר עשו ליעקב בעת שנפגשו: \u0003\"נסעה ונלכה ואלכה לנגדך\"\u0004 (בראשית לג, יב), שעשו משווה עצמו ליעקב, \u0003ולבסוף דרוש\u0004 \u0005[ודרשו]\u0006 את הנאמר בדברי יעקב לעשו: \u0003\"יעבר נא אדני לפני עבדו\"\u0004 (בראשית לג, יד)","שמשמע שיעקב, ישראל, משועבד לעשו ההולך לפניו. ושואלים: \u0003עשרין ושית שנין דקמו בהימנותייהו בהדי ישראל מנא לן\u0004 \u0005[עשרים ושש שנה שעמדו בנאמנותם עם ישראל מנין לנו]?\u0006 ומביאים ראיה לדבר, ש\u0003אמר רב כהנא: כשחלה ר' ישמעאל בר יוסי, שלחו ליה\u0004 \u0005[לו]\u0006 חכמים: \u0003רבי, אמור לנו שנים ושלשה דברים שאמרת לנו\u0004 במסורת \u0003משום אביך,\u0004 ר' יוסי בן חלפתא, ואין אנו זוכרים אותם בדיוק.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאה ושמנים שנה קודם שנחרב הבית\u0004 השני — \u0003פשטה מלכות הרשעה\u0004 (מלכות רומי) \u0003על ישראל\u0004 ומשלה בהם, \u0003שמונים שנה עד\u0004 ש\u0003לא חרב הבית\u0004 — \u0003גזרו\u0004 חכמים \u0003טומאה על ארץ העמים ועל כלי זכוכית, ארבעים שנה עד\u0004 ש\u0003לא חרב הבית\u0004 — \u0003גלתה סנהדרין\u0004 ממקומה בלשכת הגזית, \u0003וישבה לה בחנות\u0004 (מקום שהיה סמוך להר הבית).","ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 מה משנה הדבר היכן ישבה הסנהדרין? \u0003אמר ר' יצחק בר אבדימי: לומר, שלא דנו דיני קנסות.\u0004 ותוהים: \u0003דיני קנסות סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר שלא דנו מאותו זמן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: ברם\u0004 (אולם) \u0003זכור אותו האיש לטוב ור' יהודה בן בבא שמו, שאלמלא הוא נשתכחו דיני קנסות מישראל.\u0004 ותוהים על הלשון: \u0003\"נשתכחו\"\u0004 — \u0003לגרסינהו\u0004 \u0005[שילמדו אותם]\u0006 ולא ישתכחו!","\u0003אלא\u0004 הכוונה היא ש\u0003בטלו דיני קנסות מישראל,\u0004 שלא היו דיינים סמוכים שיוכלו לדון בהם, כיצד? \u0003שגזרה מלכות הרשעה,\u0004 רומי, \u0003שמד על ישראל: כל\u0004 חכם \u0003הסומך\u0004 חכמים לדון \u0003יהרג, וכל הנסמך יהרג, ועיר שסומכין בה\u0004 חכם \u0003תחרב, ו\u0004אם לא היה זה בתוך העיר, \u0003תחום\u0004 (תחום העיר) \u0003שסומכין בו\u0004 כולו \u0003יעקר.\u0004","\u0003מה עשה ר' יהודה בן בבא? הלך וישב בין שני הרים גדולים ו\u0004הרים אלה היו \u0003בין שתי עיירות גדולות, בין שני תחומי שבת, בין אושא לשפרעם,\u0004 כדי שמה שעושה לא יגרום נזק למקום שהוא נמצא בו, כיון שאינו נמצא בשום תחום מסויים, \u0003וסמך שם חמשה זקנים,\u0004 והם: \u0003ר' מאיר ור' יהודה ור' יוסי ור' שמעון ור' אלעזר בן שמוע, ורב אויא מוסיף: אף\u0004 את \u0003ר' נחמיה\u0004 סמך.","\u0003כיון שהכירו בהם אויבים\u0004 והתקרבו למקום, \u0003אמר להם\u0004 ר' יהודה בן בבא: \u0003בני, רוצו\u0004 וברחו מכאן והצילו את עצמכם, שהרי כל הנסמך נהרג בגזירתם. \u0003אמרו לו: רבי, ואתה מה תהא עליך? אמר להם:\u0004 אני איני יכול לרוץ ו\u0003הריני מוטל לפניהם כאבן שאין לה הופכין\u0004 (שאי אפשר להזיז אותה ממקומה). \u0003אמרו\u0004 חכמים: \u0003לא זזו\u0004 הרומאים \u0003משם עד שנעצו לגופו שלש מאות לולניאות\u0004 (חניתות) \u0003של ברזל ועשאוהו לגופו ככברה\u0004 כנפה זו שמלאה חורים. על כל פנים מכאן עולה שהיו דיינים סמוכים, והללו דנו בדיני קנסות שנים רבות אחרי חורבן הבית!","אלא \u0003אמר רב נחמן בר יצחק: לא תימא\u0004 \u0005[תאמר]\u0006 שלא דנו עוד \u0003דיני קנסות\u0004 משגלתה סנהדרין מלשכת הגזית, \u0003אלא שלא דנו דיני נפשות\u0004 עוד, כי כשאין סנהדרין במקומה אין בכוח בית דין לדון דיני נפשות.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שעשו כך, שיצאו חברי הסנהדרין ממקומם וגרמו בכך לביטול דיני נפשות? \u0003כיון דחזו דנפישי להו\u0004 \u0005[שראו שמתרבים להם]\u0006 \u0003רוצחין ולא יכלי למידן\u0004 \u0005[ואין הם יכולים לדון\u0006 אותם למיתה\u0005],\u0006 \u0003אמרו: מוטב נגלי\u0004 \u0005[שנגלה]\u0006 \u0003ממקום למקום כי היכי דלא ליחייבו\u0004 \u0005[כדי שלא יתחייבו\u0006 מיתה\u0005]\u0006 ואנו לא נוכל לקיים בהם את המוטל עלינו. ומנין שהגלות מועילה לעניין זה?","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשית על פי הדבר אשר יגידו לך מן המקום ההוא\"\u0004 (דברים יז, י), \u0003מלמד שהמקום גורם,\u0004 ואם אין הסנהדרין במקום הראוי, שהוא לשכת הגזית שבהר הבית, שוב אינם יכולים לדון דיני נפשות.","כל דיון זה הובא בדרך אגב, ומעתה חוזרים לעיקר הדיון, שר' ישמעאל מסר בשם אביו ר' יוסי, ש\u0003מאה ושמנים\u0004 שנה לפני החורבן פשטה מלכות רומי על ישראל. ושואלים: מאה ושמונים \u0003ותו לא\u0004 \u0005[ולא יותר]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' יוסי ברבי\u0004 (הגדול) כלומר, ר' יוסי בן חלפתא עצמו:"],["\u0003מלכות פרס\u0004 היתה מושלת בעולם \u0003בפני\u0004 (בזמן שהיה) \u0003הבית\u0004 (בית המקדש) בנוי כבר \u0003שלשים וארבע שנה, מלכות יון\u0004 משלה \u0003בפני הבית מאה ושמונים שנה, מלכות חשמונאי\u0004 משלה \u0003בפני הבית מאה ושלש\u0004 שנה, \u0003מלכות בית הורדוס\u0004 גם כן \u0003מאה ושלש\u0004 שנה, \u0003מכאן ואילך\u0004 אחר זמן זה \u0003צא וחשוב\u0004 את חשבונות הזמנים שלך לפי \u0003כמה שנים\u0004 הן \u0003אחר חורבן הבית.\u0004","על כל פנים, \u0003אלמא מאתן ושית הוו\u0004 \u0005[מכאן שמאתיים ושש\u0006 שנים \u0005היו]\u0006 מאז שבטל שלטון היוונים, ואז היתה תחילת התפשטותה של רומי, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003מאה ושמונים\u0004 שנה \u0003הוו\u0004 \u0005[הם]\u0006 השנים שמלכות הרשעה פשטה קודם שחרב הבית! \u0003אלא\u0004 מכאן יש להסיק מה שאמרנו לעיל, ש\u0003עשרין ושית שנין קמו בהימנותייהו בהדי ישראל ולא אישתעבדו בהו\u0004 \u0005[עשרים ושש שנים עמדו\u0006 הרומאים \u0005בנאמנותם עם ישראל,\u0006 לפי ההסכם שביניהם, \u0005ולא השתעבדו בהם],\u0006 \u0003ואמטו להכי לא קא חשיב להו\u0004 \u0005[ומשום כך לא החשיב אותם]\u0006 ר' ישמעאל בר' יוסי בשם אביו, במנין השנים \u0003כשפשטה מלכות הרשעה על ישראל.\u0004","אגב ברייתא זו מביאים, \u0003אמר רב פפא: אי טעי האי תנא\u0004 \u0005[אם טועה תנא זה]\u0006 שהוא מונה את מנין השנים לפי חורבן המקדש (כמבואר לעיל: \"מכאן ואילך צא וחשוב כמה שנים אחר חורבן הבית\"), \u0003ולא ידע\u0004 \u0005[ואינו יודע]\u0006 \u0003פרטי\u0004 השנים \u0003כמה הוה\u0004 \u0005[הוא],\u0006 שמן הסתם אינו טועה ושוכח את המאות אלא את השנה המדוייקת, \u0003לישייליה לספרא\u0004 \u0005[שישאל את הסופר]\u0006 הכותב שטרות כמה הוא \u0003כתיב\u0004 \u0005[כותב],\u0006 שכן הסופרים היו כותבים לפי \"מנין שטרות\" שהוא ראשית שלטון היוונים, \u0003וניטפי עלייהו עשרין שנין, ומשכח ליה לחומריה\u0004 \u0005[ויוסיף עליהם עשרים שנה, וימצא את מספרו],\u0006 וזאת משום שמנין השטרות החל שלוש מאות ושמונים שנה לפני חורבן הבית. \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 לזכור את הדבר: \u0003\"זה לי עשרים שנה אנכי בביתך\"\u0004 (בראשית לא, מא).","ולהיפך, \u0003אי טעי ספרא\u0004 \u0005[אם טועה הסופר]\u0006 ואינו זוכר מה פרט השנה, \u0003נשייליה\u0004 \u0005[שישאל]\u0006 את ה\u0003תנא כמה\u0004 הוא \u0003חשיב\u0004 \u0005[מונה]\u0006 לחורבן המקדש, \u0003ונבצר מינייהו עשרין שנין, ומשכח ליה לחומריה\u0004 \u0005[ויפחית מהם עשרים שנה, וימצא את מספרו],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך],\u0006 שהתנא צריך להוסיף על מספרו של הסופר, והסופר מחסיר ממניינו של התנא: \u0003ספרא בצירא\u0004 \u0005[הסופר ממעט,\u0006 מקצר\u0005],\u0006 \u0003תנא תוספאה\u0004 \u0005[התנא שונה התוספתא]\u0006 כלומר, התנא הוא זה שמוסיף על המספר.","ואגב חשבונות השנים, מביאים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003אליהו: ששת אלפים שנה הוי\u0004 \u0005[הוא]\u0006 זמן קיומו של \u0003העולם, שני אלפים\u0004 ראשונים הם \u0003תוהו\u0004 שממה, שלא היתה בהם תורה, \u0003שני אלפים\u0004 שאחריו הם שנים של \u0003תורה, שני אלפים\u0004 אחרונות הן הזמן המיועד ל\u0003ימות המשיח, בעונותינו שרבו יצאו מהן\u0004 מאלפיים של משיח \u0003מה שיצאו מהן,\u0004 כלומר, כך וכך שנים (שכל תנא מונה אותן לפי זמנו) ועדיין לא הגיע המשיח.","ושואלים: \u0003שני אלפים תורה מאימת\u0004 \u0005[מאימתי]\u0006 אתה מונה אותן? \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 \u0003ממתן תורה עד השתא\u0004 \u0005[עכשיו],\u0006 אלפיים של משיח — \u0003ליכא כולי האי\u0004 \u0005[אין כל כך הרבה],\u0006 \u0003דכי מעיינת בהו\u0004 \u0005[שכאשר אתה מעיין בדבר],\u0006 הרי מבריאת העולם עד מתן תורה \u0003תרי אלפי\u0004 \u0005[שני אלפים]\u0006 שלמים, ועוד \u0003פרטי דהאי אלפא הוא דהואי\u0004 \u0005[פרטים של אלף זה\u0006 שלישי \u0005הוא שישנם],\u0006 שמתן תורה היה בשנת אלפיים ארבע מאות וארבעים ושמונה לבריאת העולם, ונמצא שעד שהחלו אלפיים של משיח לא נגמרו אלפיים של תורה!","\u0003אלא\u0004 הזמן שמונים לאלפיים שנה של תורה הוא מאותו זמן שנאמר באברהם ושרה: \u0003\"ואת הנפש אשר עשו בחרן\"\u0004 (בראשית יב, ה), שפירשו חכמים שאלה היו אנשים ונשים שאותם קירבו אברהם ושרה לתורה, שאז החלה הפצת התורה בעולם, \u0003וגמירי\u0004 \u0005[ולמודים\u0006 אנו במסורת\u0005]\u0006 ש\u0003אברהם בההיא שעתא בר חמשין ותרתי הוה\u0004 \u0005[באותה שעה בן חמישים ושתים היה].\u0006","וכך עולה החשבון הראוי, שכן \u0003כמה\u0004 שנים \u0003בצרן\u0004 \u0005[חסרות]\u0006 לאלפיים שנה של תורה \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששונה]\u0006 ה\u0003תנא,\u0004 אם אתה מונה ממתן תורה ועד תחילת אלפיים של משיח? \u0003ארבע מאה וארבעים ותמניא שנין הויין\u0004 \u0005[ארבע מאות וארבעים ושמונה שנים הן],\u0006 \u0003כי מעיינת ביה\u0004 \u0005[כאשר אתה מעיין בו]\u0006 בחשבון זה, אתה מוצא כי \u0003מ\"הנפש אשר עשו בחרן\" עד מתן תורה, ארבע מאה וארבעים ותמניא שנין הויין\u0004 \u0005[ארבע מאות ארבעים ושמונה שנים הן].\u0006","וגם לגבי ברייתא זו \u0003אמר רב פפא: אי טעי תנא ולא ידע פרטיה כמה הוי\u0004 \u0005[אם טועה התנא ולא יודע\u0006 את \u0005פרט\u0006 השנים \u0005שלו כמה הוא],\u0006 כשהוא שונה: \"וכבר יצאו מאלפיים של משיח כך וכך שנים\" ויודע כמה מאות עברו, ואינו זוכר את השנה המדוייקת, \u0003לישייליה לספרא\u0004 \u0005[שישאל את הסופר] כמה\u0006 הוא \u0003כתיב\u0004 \u0005[כותב]\u0006 למניין שטרות, \u0003ניטפי עלייהו ארבעין ותמני\u0004 \u0005[יוסיף עליהם ארבעים ושמונה],\u0006 \u0003ומשכח ליה לחומריה\u0004 \u0005[וימצא את מספרו],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 לדבר:"],["\u0003\"ארבעים ושמנה עיר\"\u0004 (במדבר לה, ז). \u0003ו\u0004כיוצא בזה לצד האחר, \u0003אי טעי ספרא\u0004 \u0005[ואם טועה הסופר]\u0006 ואינו זוכר את פרטי השנים למניין השטרות, \u0003נשייליה לתנא\u0004 \u0005[ישאל את התנא]\u0006 \u0003כמה קתני\u0004 \u0005[הוא שונה]\u0006 במניין הפרטים מתחילת האלף החמישי, \u0003וניבצר מינייהו\u0004 \u0005[ויפחת ממנו]\u0006 \u0003ארבעים ושמונה, ומשכח ליה לחומריה\u0004 \u0005[וימצא את מספרו],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003ספרא בצירא, תנא תוספאה\u0004 \u0005[הסופר ממעט, התנא מוסיף].\u0006","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: האי מאן דלא ידע\u0004 \u0005[מי שאינו יודע]\u0006 \u0003כמה\u0004 (באיזו) שנה מ\u0003שני\u0004 \u0005[השנים]\u0006 \u0003בשבוע\u0004 (בשבע שנות השמיטה) \u0003הוא עומד, ניטפי חד שתא\u0004 \u0005[שיוסיף שנה אחת]\u0006 על מספר השנים מהחורבן, כדי להתחיל את מניינו בתחילת מחזור שמיטה. \u0003ונחשוב כללי ביובלי\u0004 \u0005[ויחשב את הכללים,\u0006 את מאות השנים, \u0005ביובלות],\u0006 שבכל יובל נשלמים שבעה מחזורי שמיטה. \u0003ופרטי בשבועי\u0004 \u0005[ואת הפרטים בשביעיות],\u0006 כלומר, את מה שנותר לאחר החלוקה ליובלות יחלק לשבע (שנות שמיטה), ואולם הואיל ושנת היובל עצמה גם היא עולה למנין שנות השמיטה,","\u0003נשקל ממאה תרי ונשדי אפרטי\u0004 \u0005[יקח מ\u0006כל \u0005מאה\u0006 שנים שעברו \u0005שתים ויוסיף על הפרטים],\u0006 \u0003ונחשובינהו לפרטי בשבועי\u0004 \u0005[ו\u0006אז \u0005יחשב את הפרטים,\u0006 יחלק אותם ל\u0005שביעיות],\u0006 \u0003ו\u0004לפי הנותר מן החלוקה לשבע \u0003ידע כמה שני\u0004 \u0005[שנים]\u0006 \u0003בשבוע\u0004 (בשמיטה) בה הוא עומד עברו. ולדוגמה, אם המנין לשנות החורבן הוא אלף ותשע מאות ושלושים, יוסיף עליו שנה אחת, ונמצא חשבון הפרטים שלושים ואחת. לאחר מכן יטול שתי שנים מכל מאה שנה (בסך הכל שלושים ושמונה) ויוסיפו על מניין הפרטים, ונמצא המנין ששים ותשע. וכשהוא מחלקו לשבע, נותרו בידו שש שנים, ונמצא שהוא עומד בשנה הששית לשמיטה. \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 שמחסרים שתי שנים מכל מאה: \u0003\"כי זה שנתים הרעב בקרב הארץ\"\u0004 (בראשית מה, ו).","\u0003אמר ר' חנינא: אחר ארבע מאות לחורבן הבית, אם יאמר לך אדם: קח\u0004 (קנה) \u0003שדה שוה אלף דינרים בדינר אחד\u0004 — \u0003לא תקח,\u0004 כי במהרה תבוא הגאולה ואז יחזרו השדות לבעליהם, ולא כדאי הדבר. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003אחר ארבעת אלפים ומאתים ושלשים ואחת שנה לבריאת עולם, אם יאמר לך אדם: קח לך שדה שוה אלף דינרים בדינר אחד\u0004 — \u0003אל תקח.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 במניין השנים? \u0003איכא בינייהו תלת שנין, דמתניתא טפיא תלת שני\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005שלש שנים, שהברייתא מוסיפה\u0006 עוד \u0005שלש שנים],\u0006 שארבע מאות שנים לחורבן הן ארבעת אלפים ומאתיים ועשרים ושמונה לבריאת העולם.","מסופר, \u0003ההוא שטרא דהוה כתיב ביה\u0004 \u0005[שטר אחד שהיה כתוב בו]\u0006"],["\u0003שית שנין יתירתא\u0004 \u0005[שש שנים יתירות]\u0006 על מנין השטרות (שהוא למלכות יוון). \u0003סבור רבנן קמיה דרבה למימר\u0004 \u0005[חשבו חכמים\u0006 שישבו \u0005לפני רבה לומר]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003שטר מאוחר הוא,\u0004 שנכתב לתאריך מאוחר יותר, ותוקפו יהא רק מן התאריך הכתוב בו, ולכן \u0003ניעכביה\u0004 \u0003עד דמטיא זמניה\u0004 \u0005[נעכב אותו עד שיבוא זמנו]\u0006 \u0003ולא טריף\u0004 \u0005[יטרוף]\u0006 המלוה מנכסים שיקנה הלווה עד אז. \u0003אמר רב נחמן:\u0004 לא כך, אלא \u0003האי ספרא דוקנא כתביה\u0004 \u0005[\u0006שטר \u0005זה סופר דקדקן כתבו],\u0006 \u0003והנך שית שנין\u0004 \u0005[ואותן שש השנים]\u0006 ש\u0003מלכו\u0004 היוונים \u0003בעילם\u0004 בלבד, \u0003דאנן לא חשבינן להו\u0004 \u0005[שאנו איננו מונים אותם],\u0006 משום שעדיין לא נתפשטה מלכותם בעולם, \u0003הוא קחשיב ליה\u0004 \u0005[מונה אותם],\u0006 \u0003ובזמניה כתביה\u0004 \u0005[ו\u0006באמת \u0005בזמנו כתבו],\u0006 שתאריך השטר הוא בשנה שנכתב בה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: שש שנים מלכו\u0004 היוונים \u0003בעילם\u0004 בלבד, \u0003ואחר כך פשטה מלכותן בכל העולם כולו,\u0004 ומתאריך זה מונים את השטרות.","\u0003מתקיף לה\u0004 \u0005[מקשה]\u0006 \u0003רב אחא בר יעקב\u0004 על דברי רב נחמן: \u0003ממאי\u0004 \u0005[מנין]\u0006 לנו ש\u0003למלכות יונים מנינן\u0004 \u0005[מונים אנו],\u0006 ושטר זה נכתב למנין השטרות למלכות יוון, אלא שסופר דקדקן כתבו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ליציאת מצרים מנינן\u0004 \u0005[מונים אנו]\u0006 את השנים, שתחילת המנין ליציאת מצרים קודם למנין מלכות יוון אלף שנה, \u0003ושבקיה לאלפא קמא ונקטיה אלפא בתרא\u0004 \u0005[והניח\u0006 הסופר \u0005את האלף הראשון\u0006 ליציאת מצרים \u0005ותפס את האלף השני],\u0006 שכתב רק את מספר פרטי השנים ודילג על האלפים, \u0003והאי\u0004 \u0005[ו\u0006אם כן שטר \u0005זה]\u0006 אכן \u0003מאוחר הוא! אמר רב נחמן:\u0004 כלל הוא, \u0003בגולה אין מונין אלא למלכי יונים בלבד.\u0004","ומעירים: \u0003הוא\u0004 רב אחא בר יעקב \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 שרב נחמן רק \u0003דחויי קא מדחי ליה\u0004 \u0005[דוחה אותו]\u0006 בדחיה כלשהי, ואולם כאשר \u0003נפק דק ואשכח\u0004 \u0005[יצא דקדק ומצא],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 האומרת כך במפורש: \u0003בגולה אין מונין אלא למלכי יונים בלבד.\u0004","\u0003אמר רבינא: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 שמונים למלכות יון, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003באחד בניסן ראש השנה למלכים ולרגלים, ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003למלכים\u0004 — \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003אמר רב חסדא: ל\u0004ענין \u0003שטרות;\u0004","\u0003ותנן\u0004 \u0005[ו\u0006עוד \u0005שנינו\u0006 באותה משנה\u0005]:\u0006 \u0003באחד בתשרי ראש השנה לשנים ולשמיטין, ואמרינן\u0004 \u0005[ואמרנו]\u0006 : \u0003לשנים\u0004 — \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]?\u0006 \u0003ואמר רב חסדא: לשטרות.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 בענין \u0003שטרות אהדדי\u0004 \u0005[מזה על זה],\u0006 האם מונים מתשרי או מניסן?","\u0003ומשנינן\u0004 \u0005[ותירצנו]\u0006 קושיה זו: \u0003כאן\u0004 — הוא כאשר מונים \u0003למלכי ישראל, כאן\u0004 — מונים \u0003למלכי אומות העולם, למלכי אומות העולם מתשרי מנינן\u0004 \u0005[מונים אנו],\u0006 \u0003למלכי ישראל מניסן מנינן\u0004 \u0005[מונים אנו].\u0006","ומכאן נלמד לענייננו: \u0003ואנן השתא\u0004 \u0005[ואנו עכשיו]\u0006 הרי \u0003מתשרי מנינן\u0004 \u0005[אנו מונים]\u0006 בשטרות, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה\u0006 על \u0005דעתך\u0006 לומר\u0005]\u0006 ש\u0003ליציאת מצרים מנינן\u0004 \u0005[מונים אנו]\u0006 ומשמיטים אלף ראשון, אם כן \u0003מניסן בעינן למימני\u0004 \u0005[אנו צריכים למנות]\u0006 את השנים! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[תלמד מכאן]\u0006 ש\u0003למלכי יונים מנינן\u0004 \u0005[מונים אנו]?\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שסתם מנין הוא למלכות יוונים, ויש איפוא מקום לומר כדברי רב נחמן, ששטר זה אינו מאוחר, אלא סופר דקדקן כתבו.","שנינו במשנתנו בין אידיהן של הגויים \u0003יום גינוסיא של מלכיהם.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ויום גינוסיא של מלכיהם\"? אמר רב יהודה: יום שמעמידין\u0004 (ממליכים) \u0003בו גוים את מלכם.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יום גינוסיא ויום שמעמידין בו את מלכם,\u0004 משמע שאין זה אותו יום חג עצמו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא דידיה\u0004 \u0005[זה,\u0006 יום גנוסיא, הוא יום ההמלכה \u0005שלו],\u0006 של המלך, \u0003הא דבריה\u0004 \u0005[זה,\u0006 יום שמעמידים בו את מלכם, \u0005של בנו,\u0006 שממליכים אותו בחיי אביו\u0005].\u0006","ומקשים על הסבר זה: \u0003ומי מוקמי מלכא בר מלכא\u0004 \u0005[והאם מעמידים\u0006 הרומאים \u0005מלך בן מלך]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב יוסף:\u0004 כתוב האמור בנבואה על אדום (רומי): \u0003\"הנה קטן נתתיך בגוים\"\u0004 (עובדיה א, ב) כוונתו \u0003שאין\u0004 הרומאים \u0003מושיבין מלך בן מלך, \"בזוי אתה מאד\"\u0004 (עובדיה א, ב) כוונתו \u0003שאין להן לא כתב ולא לשון\u0004 משלהם, אלא נטלו כתב ולשון מעמים אחרים! \u0003אלא\u0004 יש לדחות מה שאמרנו, ולפרש: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003יום גינוסיא? יום הלידה\u0004 של המלך.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יום גינוסיא ויום הלידה!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא דידיה, הא דבריה\u0004 \u0005[זה שלו, זה של בנו].\u0006","מקשים על כך: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יום גינוסיא שלו, יום גינוסיא של בנו, ויום הלידה שלו ויום הלידה של בנו,\u0004 משמע שיום גינוסיא ויום לידה אינם אותו דבר! \u0003אלא\u0004 אנו צריכים לחזור למה שאמרנו, \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"יום גינוסיא\"? יום שמעמידין בו מלכם, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]\u0006 מה ששנינו בברייתא גם יום גינוסיא וגם יום העמדת מלך, שכן \u0003הא דידיה, הא דבריה\u0004 \u0005[זה שלו, זה של בנו],\u0006","\u0003ואי קשיא לך דלא מוקמי מלכא בר מלכא\u0004 \u0005[ואם קשה לך\u0006 מה שאמרנו \u0005שאין מעמידים מלך בן מלך],\u0006 על כך יש להשיב כי \u0003על ידי שאלה\u0004 בקשה של המלך \u0003מוקמי\u0004 \u0005[מעמידים]\u0006 גם את בנו, \u0003כגון אסוירוס בר\u0004 \u0005[בן]\u0006 \u0003אנטונינוס\u0004 ש\u0003מלך\u0004 בבקשתו של אנטונינוס אביו, כפי שמסופר ש","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אנטונינוס לרבי\u0004 יהודה הנשיא: \u0003בעינא\u0004 \u0005[רוצה אני]\u0006 ש\u0003ימלוך אסוירוס ברי תחותי\u0004 \u0005[בני תחתי]\u0006 ולא איש אחר, \u0003ו\u0004רצוני גם ש\u0003תתעביד טבריא קלניא\u0004 \u0005[שתיעשה\u0006 העיר \u0005טבריה חופשית ממס],\u0006 \u0003ו\u0004אולם \u0003אי אימא להו חדא\u0004 \u0005[אם אומר להם\u0006 למועצה של חשובי הרומאים שבממלכתי רומי דבר \u0005אחד]\u0006 — \u0003עבדי\u0004 \u0005[יעשו],\u0006 \u0003תרי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 — \u0003לא עבדי\u0004 \u0005[יעשו\u0006 בשבילי\u0005].\u0006 השיב לו רבי ברמז, \u0003אייתי גברא, ארכביה אחבריה, ויהב ליה יונה לעילאי [בידיה]\u0004 \u0005[הביא אדם, הרכיב אותו על גבי חבירו, ונתן לו יונה לעליון בידו],\u0006 \u0003ואמר ליה לתתאה\u0004 \u0005[לו לתחתון]:\u0006 \u0003אימר לעילא דלמפרח מן ידיה\u0004 \u0005[אמור לעליון שיפריח מידו]\u0006 את ה\u0003יונה. אמר\u0004 אנטונינוס: \u0003שמע מינה הכי קאמר לי\u0004 \u0005[למד מכאן שכך אמר לי]\u0006 כלומר, כך רצה לרמוז לי: \u0003את בעי מינייהו\u0004 \u0005[אתה תבקש מהם]\u0006 ש\u0003\"אסוירוס ברי\u0004 \u0005[בני]\u0006 \u0003ימלוך תחותי\u0004 \u0005[תחתי]\",\u0006 \u0003ואימא ליה לאסוירוס דתעביד טבריא קלניא\u0004 \u0005[ו\u0006אחר כך \u0005תאמר לו לאסוירוס\u0006 עצמו","\u0005שתיעשה טבריה חופשית].\u0006 ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 אנטונינוס: \u0003מצערין לי חשובי [רומאי]\u0004 \u0005[מצערים אותי חשובי הרומאים]\u0006 שבממלכתי, ומה אעשה כנגדם? מה עשה רבי? \u0003מעייל ליה לגינא\u0004 \u0005[הכניס אותו לגינה],\u0006 \u0003כל יומא עקר ליה פוגלא ממשרא קמיה\u0004 \u0005[בכל יום עקר צנון מהערוגה\u0006 שהיתה \u0005לפניו].\u0006 \u0003אמר\u0004 אנטונינוס, \u0003שמע מינה הכי קאמר לי\u0004 \u0005[למד מכאן שכך אמר לי]:\u0006 \u0003את קטול חד חד מינייהו\u0004 \u0005[אתה הרוג אחד אחד מהם],\u0006 \u0003ולא תתגרה בהו בכולהו\u0004 \u0005[בהם בכולם]\u0006 יחד."],["ושואלים: \u0003ולימא ליה מימר [בהדיא]\u0004 \u0005[ושיאמר לו במפורש]\u0006 את הדברים הללו, ומדוע עשה רבי בדרך רמז שאפשר גם לטעות בה? ומשיבים: \u0003אמר\u0004 רבי: אילו אומר במפורש, \u0003שמעי (בי) חשובי רומי ומצערו ליה\u0004 \u0005[ישמעו (אותי) חשובי הרומאים ויצערו אותו\u0006 כלומר, אותי\u0005].\u0006 ושואלים: \u0003ולימא ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003בלחש!\u0004 ואומרים: גם באופן זה חשש רבי לומר, שמא יישמעו דבריו, \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי עוף השמים יוליך את הקול\"\u0004 (קהלת י, כ).","ועוד מסופר, \u0003הוה ליה ההוא ברתא\u0004 \u0005[היתה לו\u0006 לאנטונינוס \u0005בת אחת]\u0006 ש\u0003שמה\u0004 היה \u0003גירא,\u0004 \u0003קעבדה איסורא\u0004 \u0005[ועשתה\u0006 דבר \u0005איסור,\u0006 בזנות\u0005],\u0006 \u0003שדר ליה\u0004 \u0005[שלח לו]\u0006 אנטונינוס לרבי את הצמח \u0003גרגירא\u0004 שיש בו רמז: גר (=זנתה) גירא, \u0003שדר ליה\u0004 \u0005[שלח לו]\u0006 רבי צמח ששמו \u0003כוסברתא,\u0004 ואנטונינוס הבין שהוא רומז לו: כוס ברתא (=הרוג את הבת). \u0003שדר ליה\u0004 \u0005[שלח לו]\u0006 אנטונינוס את הצמח \u0003כרתי\u0004 שיש בו רמז: אני נכרת אם אני אעשה כן. \u0003שלח ליה\u0004 \u0005[שלח לו]\u0006 רבי \u0003חסא,\u0004 לומר: חוס עליה.","ועוד מסופר, \u0003כל יומא הוה שדר ליה דהבא פריכא במטראתא, וחיטי אפומייהו\u0004 \u0005[כל יום היה שולח לו\u0006 אנטונינוס לרבי \u0005זהב מפורר בתוך שקים גדולים, וחיטים\u0006 היו \u0005מונחים בפיהם\u0006 של השקים\u0005],\u0006 וכך \u0003אמר להו\u0004 \u0005[היה אומר להם]\u0006 אנטונינוס לשליחיו: \u0003אמטיו חיטי\u0004 \u0005[הביאו חיטים]\u0006 \u0003לרבי,\u0004 ולא ידעו שיש שם זהב. \u0003אמר [ליה\u0004 \u0005[לו]\u0006 \u0003רבי]: לא צריכנא, אית לי טובא\u0004 \u0005[אין אני צריך\u0006 זהב, שכן \u0005יש לי הרבה].\u0006 \u0003אמר\u0004 אנטונינוס: \u0003ליהוו למאן דבתרך, דיהבי לבתראי דאתו בתרך, ודאתי מינייהו ניפוק עלייהו\u0004 \u0005[שיהיו לאלה ש\u0006יבואו \u0005אחריך, שיתנו לאחרונים שיבואו אחריך, ו\u0006מי \u0005שיצא מהם יוציא עליהם,\u0006 על חשבון מה שקיבלו הם ממני\u0005].\u0006","ועוד מסופר על אנטונינוס: \u0003הוה ליה ההיא נקרתא דהוה עיילא מביתיה\u0004 \u0005[היתה לו מערה\u0006 מתחת לאדמה \u0005שהיתה נכנסת\u0006 מובילה \u0005מביתו]\u0006 \u0003לבית רבי, כל יומא הוה מייתי תרי עבדי\u0004 \u0005[כל יום היה מביא\u0006 אנטונינוס \u0005שני עבדים]\u0006 שישרתוהו, \u0003חד קטליה אבבא דבי רבי וחד קטליה אבבא דביתיה\u0004 \u0005[אחד היה הורג אותו על פתחו של בית רבי, ואחד היה הורג אותו על הפתח של ביתו\u0006 שלו\u0005],\u0006 כדי שלא יישאר אדם היודע שהלך מביתו לבית רבי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרבי: \u0003בעידנא דאתינא לא נשכח גבר קמך\u0004 \u0005[בזמן שאני בא\u0006 אליך \u0005אל יימצא איש לפניך].\u0006","\u0003יומא חד אשכחיה\u0004 \u0005[יום אחד מצאו]\u0006 אנטונינוס את \u0003ר' חנינא בר חמא דהוה יתיב\u0004 \u0005[שהיה יושב\u0006 שם\u0005].\u0006 \u0003אמר\u0004 לרבי: \u0003לא אמינא לך, בעידנא דאתינא לא נשכח גבר קמך\u0004 \u0005[\u0006האם \u0005לא אמרתי לך שבזמן שאני בא לא יימצא אדם לפניך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003לית דין בר איניש\u0004 \u0005[אין זה בן אדם]\u0006 כלומר, הרי הוא כמלאך, ואין אתה צריך לחשוש ממנו כלל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אנטונינוס לר' חנינא: \u0003אימא ליה לההוא עבדא דגני אבבא דקאים וליתי\u0004 \u0005[אמור לו לאותו עבד שישן על הפתח שיקום ויבוא].\u0006","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' חנינא בר חמא, אשכחיה דהוה קטיל\u0004 \u0005[מצא אותו שהיה הרוג],\u0006 \u0003אמר: היכי אעביד\u0004 \u0005[איך אעשה]?\u0006 \u0003אי איזיל ואימא ליה דקטיל\u0004 \u0005[אם אלך ואומר לו ש\u0006הוא \u0005הרוג],\u0006 הרי \u0003אין משיבין על הקלקלה\u0004 כלומר, אין משיבים דבר של קלקלה וגנאי. \u0003אשבקיה ואיזיל\u0004 \u0005[\u0006אם \u0005אעזבנו ואלך],\u0006 \u0003קא מזלזלינן במלכותא\u0004 \u0005[\u0006נמצא \u0005שאנו מזלזלים במלכות]\u0006 ואין ממלאים הפקודה. \u0003בעא רחמי עליה ואחייה ושדריה\u0004 \u0005[ביקש רחמים עליו והחייהו ושלחו\u0006 לאנטונינוס\u0005].\u0006 \u0003אמר\u0004 אנטונינוס לרבי: \u0003ידענא, זוטי דאית בכו\u0004 \u0005[יודע אני, שהקטן שבכם]\u0006 \u0003מחיה מתים, מיהו בעידנא דאתינא לא נשכח איניש קמך\u0004 \u0005[בכל זאת, בזמן שאני בא אל יימצא אדם לפניך],\u0006 אפילו אדם גדול כר' חנינא.","ועוד מסופר, \u0003כל יומא הוה\u0004 \u0005[יום היה]\u0006 אנטונינוס \u0003משמש\u0004 את \u0003רבי, מאכיל ליה\u0004 \u0005[אותו],\u0006 \u0003משקי ליה\u0004 \u0005[משקה אותו],\u0006 \u0003כי הוה בעי רבי למיסק לפוריא\u0004 \u0005[כאשר היה רבי רוצה לעלות למיטתו],\u0006 \u0003הוה גחין קמי פוריא\u0004 \u0005[היה\u0006 אנטונינוס \u0005מתכופף לפני המיטה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סק עילואי לפורייך\u0004 \u0005[עלה עלי למיטתך],\u0006 \u0003אמר\u0004 לו רבי: \u0003לאו אורח ארעא לזלזולי במלכותא כולי האי\u0004 \u0005[אין\u0006 זו \u0005דרך ארץ לזלזל במלכות כל כך],\u0006 \u0003אמר\u0004 אנטונינוס: \u0003מי ישמני מצע תחתיך לעולם הבא. ועוד\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אנטונינוס: \u0003אתינא לעלמא דאתי\u0004 \u0005[\u0006האם \u0005אבוא לעולם הבא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא יהיה שריד לבית עשו\"\u0004 (עובדיה א, יח)! אמר לו: מדובר שם \u0003ב\u0004מי ש\u0003עושה מעשה עשו,\u0004 ולא אדם כמותך.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"לא יהיה שריד לבית עשו\"\u0004 — \u0003יכול לכל? תלמוד לומר: \"לבית עשו\",\u0004 כלומר בממשיך דרכו, \u0003בעושה מעשה עשו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אנטונינוס, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתיאור השאול: \u0003\"שמה אדום מלכיה וכל נשיאיה\"\u0004 (יחזקאל לב, כט)! \u0003אמר ליה\u0004 \u0005[ לו]\u0006 רבי: \u0003\"מלכיה\"\u0004 — \u0003ולא כל מלכיה, \"כל נשיאיה\"\u0004 — \u0003ולא כל שריה,\u0004 שיש ביניהם כאלה שזוכים לחיי העולם הבא.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"מלכיה\"\u0004 — \u0003ולא כל מלכיה, \"כל נשיאיה\"\u0004 — \u0003ולא כל שריה.\u0004 ומפרשים: \u0003\"מלכיה\" ולא כל מלכיה\u0004 — \u0003פרט לאנטונינוס בן אסוירוס\u0004 שצדיק היה, \u0003\"כל נשיאיה\" ולא כל שריה — פרט לקטיעה בר שלום\u0004, שהיה אחד משרי רומי. ושואלים:","\u0003קטיעה בר שלום מאי הוי\u0004 \u0005[מה הוא]\u0006 מה עניינו? \u0003דההוא קיסרא דהוה סני ליהודאי\u0004 \u0005[שאותו קיסר\u0006 רומאי \u0005שהיה שונא את היהודים],\u0006 \u0003אמר להו לחשיבי דמלכותא\u0004 \u0005[להם לחשובי המלכות]:\u0006 \u0003מי שעלה לו נימא\u0004 (בשר מת) \u0003ברגלו,\u0004 האם \u0003יקטענה ויחיה או יניחנה ויצטער? אמרו לו: יקטענה ויחיה,\u0004 והיה זה מעין משל, שמוטב להשמיד את ישראל, שהם גורמים נזק למלכות.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003קטיעה בר שלום:\u0004 לא כדאי הדבר, משתי סיבות: \u0003חדא, דלא יכלת להו לכולהו\u0004 \u0005[אחת, שאין אתה יכול להם\u0006 \u0005לכולם\u0006 להשמידם], \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי כארבע רוחות השמים פרשתי אתכם\"\u0004 (זכריה ב, י), ויש לשאול: \u0003מאי קאמר\u0004 \u0005[מה אומר\u0006 פסוק זה]? \u0003אלימא דבדרתהון\u0004 \u0005[אם תאמר\u0006 שפירושו שפיזר אותם] \u0003בארבע רוחות,\u0004 אם כן, \u0003האי\u0004 \u0005[זה\u0006 הכתוב] \u0003\"כארבע רוחות\"\u0004 לא היה צריך להיאמר כך, אלא \u0003\"לארבע רוחות\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]! אלא\u0006 הכוונה היא לומר: \u0003כשם שאי אפשר לעולם בלא רוחות, כך אי אפשר לעולם בלא ישראל,\u0004 ולא ניתן אפוא להשמידם. \u0003ועוד\u0004 סיבה, שאם תעשה כן קרו \u0005[יקראו]\u0006 \u0003לך מלכותא קטיעה\u0004 \u0005[מלכות קטועה],\u0006 שאצלך אין יהודים ובמקומות אחרים יש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר: \u0003מימר שפיר קאמרת\u0004 \u0005[לומר יפה אמרת],\u0006 \u0003מיהו כל דזכי מלכא שדו ליה לקמוניא חלילא\u0004 \u0005[ואולם כל מי שמנצח את המלך\u0006 בויכוח \u0005משליכים אותו לבית מלא אפר]\u0006 שייחנק שם. \u0003כד הוה נקטין ליה ואזלין\u0004 \u0005[כאשר היו אוחזים אותו והולכים]\u0006 להוציאו להורג, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לקטיעה \u0003ההיא מטרוניתא\u0004 \u0005[גבירה אחת]:\u0006 \u0003ווי ליה לאילפא דאזלא בלא מכסא\u0004 \u0005[אוי לה לאוניה שהולכת בלא\u0006 לשלם \u0005מכס],\u0006 שאינה יכולה לעבור! שרמזה לו שאינו נימול, ולפיכך אינו בכלל ישראל לעולם הבא. \u0003נפל\u0004 \u0005[התכופף]\u0006 \u0003על רישא דעורלתיה\u0004 \u0005[ראש עורלתו]\u0006 \u0003קטעה\u0004 \u0005[קטע אותה],\u0006 \u0003אמר: יהבית מכסי חלפית ועברית\u0004 \u0005[נתתי את המכס שלי, חלפתי ועברתי].\u0006 \u0003כי קא שדו ליה\u0004 \u0005[כאשר זרקו אותו\u0006 לאותו בית\u0005],\u0006 \u0003אמר: כל נכסאי\u0004 \u0005[נכסי]\u0006 יהיו \u0003לר' עקיבא וחביריו.\u0004 ומעירים כי נשאלה השאלה כיצד יש לחלק את הירושה. מסופר, \u0003יצא ר' עקיבא ודרש:\u0004 נאמר: \u0003\"והיה לאהרן ולבניו\"\u0004 (שמות כט, כח) — הכוונה היא \u0003מחצה לאהרן ומחצה לבניו,\u0004 ואף כאן כיוון שהזכיר את ר' עקיבא לחוד, יש להבין שציוה לחלק את הנכסים מחצה לר' עקיבא ומחצה לחביריו.","וממשיכים בסיפור המעשה, \u0003יצתה בת קול ואמרה: קטיעה בר שלום מזומן לחיי העולם הבא.\u0004 כששמע זאת \u0003בכה רבי ואמר: יש קונה עולמו\u0004 לעולם הבא \u0003בשעה אחת\u0004 כקטיעה בר שלום, \u0003ויש קונה עולמו\u0004 רק \u0003בכמה שנים\u0004 של עבודה.","מסופר, \u0003אנטונינוס שמשיה\u0004 \u0005[שימש אותו]\u0006 את \u0003רבי, אדרכן\u0004 מלך פרס \u0003שמשיה\u0004 \u0005[שימש אותו]\u0006 את \u0003רב. כי שכיב\u0004 \u0005[כאשר מת]\u0006 \u0003אנטונינוס, אמר רבי: נתפרדה חבילה\u0004 שהיינו קשורים יחד בחייו, ועכשיו מת. וכן \u0003כי שכיב\u0004 \u0005[כאשר מת]\u0006 \u0003אדרכן, אמר רב:\u0004"],["\u0003נתפרדה חבילה.\u0004","ועוד בעניין גדולי רומי שנתגיירו, מסופר, \u0003אונקלוס בר\u0004 \u0005[בן]\u0006 \u0003קלונימוס איגייר\u0004 \u0005[התגייר].\u0006 \u0003שדר קיסר גונדא דרומאי אבתריה\u0004 \u0005[שלח הקיסר גדוד של רומאים אחריו]\u0006 לתופסו ולהביאו אליו. \u0003משכינהו בקראי, איגיור\u0004 \u0005[משך אותם\u0006 אונקלוס \u0005במקראות\u0006 שהביא ודרש לפניהם, ו\u0005התגיירו].\u0006 \u0003הדר שדר גונדא דרומאי [אחרינא] אבתריה\u0004 \u0005[חזר\u0006 הקיסר ו\u0005שלח גדוד רומאים אחר אחריו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא תימרו ליה ולא מידי\u0004 \u0005[אל תאמרו לו ולא דבר],\u0006 כדי שלא יגרור אתכם בדבריו. ואכן כך עשו, ונטלוהו עימם.","\u0003כי הוו שקלו ואזלו\u0004 \u0005[כאשר היו הולכים],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 אונקלוס לחיילי הגדוד: \u0003אימא לכו מילתא בעלמא\u0004 \u0005[אומר לכם דבר סתם]\u0006 שאיננו דרשה: \u0003ניפיורא\u0004 שהוא פקיד זוטר \u0003נקט נורא קמי\u0004 \u0005[מחזיק\u0006 את \u0005הלפיד\u0006 להאיר \u0005לפני]\u0006 ה\u0003אפיפיורא\u0004 שהוא פקיד גבוה יותר, וכמו כן אוחז \u0003אפיפיורא לדוכסא\u0004 \u0005[והאפיפיור לדוכס],\u0006 \u0003דוכסא להגמונא\u0004 \u0005[הדוכס להגמון],\u0006 \u0003הגמונא לקומא\u0004 \u0005[ההגמון לשליט],\u0006 ואולם \u0003קומא מי נקט נורא מקמי אינשי\u0004 \u0005[השליט האם מחזיק לפיד לפני אנשים]?\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לא. אמר להו\u0004 \u0005[להם]:\u0006 ואילו \u0003הקדוש ברוך הוא נקט נורא קמי\u0004 \u0005[מחזיק לפיד לפני]\u0006 \u0003ישראל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וה' הלך לפניהם יומם\u0004 ולילה בעמוד אש להאיר להם\" (שמות יג, כא), \u0003איגיור [כולהו]\u0004 \u0005[התגיירו כולם].\u0006","\u0003הדר שדר גונדא אחרינא אבתריה\u0004 \u0005[חזר\u0006 הקיסר ו\u0005שלח גדוד אחר אחריו],\u0006 אחרי אונקלוס, להביאו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא תשתעו מידי בהדיה\u0004 \u0005[אל תדברו איתו דבר].\u0006 \u0003כי נקטי ליה ואזלי\u0004 \u0005[כאשר תפסו אותו והלכו],\u0006 \u0003חזא מזוזתא [דמנחא אפתחא]\u0004 \u0005[ראה מזוזה שמונחת על הפתח],\u0006 \u0003אותיב ידיה עלה\u0004 \u0005[הניח ידו עליה]\u0006 \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי האי\u0004 \u0005[מהו זה]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אימא לן את\u0004 \u0005[אמור לנו אתה].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מנהגו של עולם, מלך בשר ודם יושב מבפנים\u0004 בארמון, \u0003ועבדיו משמרים אותו מבחוץ, ואילו הקדוש ברוך הוא, עבדיו\u0004 (בני ישראל) נמצאים \u0003מבפנים\u0004 בבתיהם \u0003והוא משמרן מבחוץ, שנאמר: \"ה' ישמר צאתך ובואך מעתה ועד עולם\"\u0004 (תהלים קכא, ח), \u0003איגיור\u0004 \u0005[התגיירו]\u0006 גם הם. \u0003תו לא שדר בתריה\u0004 \u0005[שוב לא שלח\u0006 הקיסר \u0005אחריו].\u0006 וחוזרים שוב לענין אנטונינוס.","נאמר לרבקה אמנו בזמן הריונה: \u0003\"ויאמר ה' לה שני גוים בבטנך\"\u0004 (בראשית כה, כג) — \u0003אמר רב יהודה אמר רב: אל תקרי\u0004 (תקרא) \u0003\"גוים\" אלא \"גיים\",\u0004 גאים, גדולים, \u0003זה אנטונינוס ורבי, ש\u0004מרוב עושרם וכבודם \u0003לא פסקו מעל שולחנם לא חזרת ולא קישות ולא צנון, לא בימות החמה ולא בימות הגשמים,\u0004 אף על פי שאינם מצויים בכל עונות השנה. ומדוע הקפידו שיהיו תמיד על שולחנם? ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003צנון מחתך\u0004 את ה\u0003אוכל, חזרת מהפך מאכל, קישות מרחיב מעיים.\u0004","ומקשים: \u0003והא תנא\u0004 \u0005[והרי שנה\u0006 החכם\u0005]\u0006 \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל: למה נקרא שמן קישואין? מפני שקשין לגופו של אדם כחרבות,\u0004 ואם כן נמצא שאינם מאכל ראוי! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא ברברבי\u0004 \u0005[זה בגדולים]\u0006 שאין הם טובים, \u0003הא בזוטרי\u0004 \u0005[זה בקטנים]\u0006 שטובים הם.","שנינו במשנה ש\u0003יום הלידה ויום המיתה\u0004 של מלכים הם בכלל ימי אידיהם של גויים לדברי ר' מאיר, וחכמים אומרים שרק מיתה שיש בה שריפה יש בה עבודה זרה. ואומרים: \u0003מכלל\u0004 הדברים יש להבין ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 ש\u0003לא שנא\u0004 \u0005[אינה שונה]\u0006 \u0003מיתה שיש בה שריפה, ולא שנא\u0004 \u0005[ואינה שונה]\u0006 \u0003מיתה שאין בה שריפה\u0004 — \u0003פלחי\u0004 \u0005[עובדים]\u0006 \u0003בה לעבודה זרה, אלמא\u0004 \u0005[מכאן]\u0006 אתה מסיק שהוא סבור ש\u0003שריפה\u0004 על מלכים \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חוקה\u0004 של עבודה זרה \u0003היא,\u0004 שלא היא גורמת האיסור. ומוסיפים: \u0003מכלל\u0004 דבר זה אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 ש\u0003שריפה חוקה\u0004 של עבודה זרה \u0003היא,\u0004 ויש לתמוה:","\u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שורפין על המלכים\u0004 מלכי ישראל שמתו, \u0003ולא מדרכי האמורי\u0004 הוא, אלא מנהג ישראל. \u0003ואי\u0004 \u0005[ואם]\u0006 שריפה \u0003חוקה\u0004 מחוקות עבודה זרה \u0003היא, אנן היכי שרפינן\u0004 \u0005[אנו כיצד אנו שורפים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ובחקתיהם לא תלכו\"\u0004 (ויקרא יח, ג)!","\u0003אלא\u0004 צריך לומר כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שריפה\u0004 עצמה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חוקה היא, אלא\u0004 משום \u0003חשיבותא\u0004 \u0005[חשיבות\u0006 יתירה\u0005]\u0006 למלך \u0003היא\u0004 ששורפים עליו. \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003לא שנא\u0004 \u0005[אינה שונה]\u0006 \u0003מיתה שיש בה שריפה, ולא שנא\u0004 \u0005[ואינה שונה]\u0006 \u0003מיתה שאין בה שריפה\u0004 — \u0003פלחי\u0004 \u0005[עובדים]\u0006 \u0003בה לעבודה זרה, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מיתה שיש בה שריפה\u0004 — \u0003חשיבא להו ופלחי\u0004 \u0005[חשובה להם ועובדים]\u0006 \u0003בה\u0004 לעבודה זרה, \u0003ושאין בה שריפה\u0004 — \u0003לא חשיבא ולא פלחי\u0004 \u0005[אינה חשובה ואין עובדים]\u0006 \u0003בה.\u0004","כיון שהוזכרה ברייתא דנים בה ל\u0003גופא\u0004 \u0005[לגופה]\u0006 וכך שנינו בה: \u0003שורפין על המלכים ואין בו משום דרכי האמורי,\u0004 וראיה לדבר, \u0003שנאמר\u0004 לצדקיהו: \u0003\"בשלום תמות ובמשרפות אבותיך המלכים\u0004 ישרפו לך\" (ירמיהו לד, ה), \u0003וכשם ששורפין על המלכים\u0004 שמתו, \u0003כך שורפין על הנשיאים,\u0004","\u0003ומה הם שורפין על המלכים? מיטתן וכלי תשמישן,\u0004 שלא ישתמש בהם אחר. \u0003ומעשה שמת רבן גמליאל הזקן, ושרף עליו אונקלוס הגר\u0004 \u0003שבעים מנה צורי.\u0004 ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003מה הן שורפין עליהם\u0004 — \u0003מיטתן וכלי תשמישן,\u0004 ולכאורה משמע שאונקלוס שרף כסף! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא לחפצים וכלי תשמיש \u0003ב\u0004שווי \u0003שבעים מנה צורי.\u0004","ושואלים: \u0003ומידי אחרינא\u0004 \u0005[ודבר אחר]\u0006 \u0003לא\u0004 עושים לכבוד המלכות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עוקרין\u0004 חותכים את פרסות הבהמות \u0003על המלכים\u0004 שמתו, \u0003ואין בו משום דרכי האמורי! אמר רב פפא:\u0004 הכוונה היא ל\u0003סוס שרכב עליו,\u0004 שהוא נחשב ככלי תשמיש מיוחד למלך, ועוקרים את פרסותיו כדי שלא ירכב עליו אדם אחר.","ושואלים: \u0003ובהמה טהורה לא\u0004 מעקרים אותה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עיקור שיש בה טריפה\u0004 שחותך חלק העושה כך את הבהמה לטריפה — \u0003אסור, ושאין בה טריפה\u0004 — \u0003מותר;\u0004 \u0003ואיזהו עיקור שאין בה טריפה\u0004 —"],["\u0003המנשר\u0004 (החותך) \u0003פרסותיה\u0004 של בהמה \u0003מן הארכובה\u0004 (הברך) \u0003ולמטה\u0004 שאינו עושה אותה בכך לטריפה. וכיון שדנים פה בענין טריפה, משמע שמדברים בבהמה טהורה שאסורה או מותרת באכילה! \u0003תרגמא\u0004 \u0005[הסביר אותה]\u0006 את הברייתא \u0003רב פפא:\u0004 מדובר כאן \u0003בעגלה המושכת בקרון\u0004 שהמלך יושב בו, והיא הרי בהמה טהורה.","שנינו במשנה: \u0003יום תגלחת זקנו\u0004 ובלוריתו. \u0003איבעיא להו\u0004 \u0005[נשאלה\u0006 \u0005להם\u0006 ללומדים\u0005]:\u0006 \u0003היכי קתני\u0004 \u0005[כיצד הוא שונה]?\u0006 מה כוונת הדברים? האם הכוונה היא ל\u0003יום תגלחת זקנו והנחת\u0004 (השארת) \u0003בלוריתו,\u0004 שמגלח את שער ראשו ומשאיר בלורית שיער מאחוריו לשם עבודה זרה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא ל\u0003יום תגלחת זקנו והעברת\u0004 (גזיזת) \u0003בלוריתו,\u0004 שזה מאוחר יותר ליום הנחתה? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 תשובה לדבר, \u0003דתניא תרוייהו\u0004 \u0005[ששנינו\u0006 בברייתא את \u0005שניהם],\u0006 בברייתא אחת: \u0003יום תגלחת זקנו והנחת בלוריתו,\u0004 ובברייתא אחרת שנינו: \u0003יום תגלחת זקנו והעברת בלוריתו.\u0004","אגב ענין זה של חגי הרומאים מביאים, \u0003אמר רב יהודה אמר שמואל: עוד\u0004 חגיגה \u0003אחרת יש [להם] ברומי, אחת לשבעים שנה מביאין אדם שלם\u0004 (בלי מום) \u0003ומרכיבין אותו על אדם חיגר\u0004 כרמז שעשיו (השלם) רוכב על יעקב (שצלע לאחר שנאבק עם המלאך), \u0003ומלבישין אותו\u0004 את הרוכב \u0003בגדי אדם הראשון, ומניחין לו בראשו\u0004 את \u0003קרקיפלו\u0004 (עור ראשו) \u0003של ר' ישמעאל,\u0004 שפשטו מעליו הרומיים כשהרגוהו,","\u0003ותלו ליה [בצואריה] מתקל [ר'] זוזא דפיזא\u0004 \u0005[ותולים לו בצווארו משקל (מאתיים) זוזים של פז],\u0006 \u0003ומחפין\u0004 (ומצפים) \u0003את השווקים באינך\u0004 (אבן יקרה מאד), \u0003ומכריזין לפניו: סך קירי פלסתר\u0004 \u0005[חשבון האדון כזב],\u0006 שחשבון הגאולה של יעקב כוזב, \u0003אחוה דמרנא זייפנא\u0004 \u0005[אחיו של אדוננו\u0006 עשיו הוא \u0005זייפן],\u0006 זה \u0003דחמי\u0004 \u0005[שראה]\u0006 חגיגה זו \u0003חמי\u0004 \u0005[ראה],\u0006 \u0003ו\u0004מי ש\u0003לא חמי\u0004 \u0005[ראה]\u0006 \u0003לא חמי\u0004 \u0005[ראה]\u0006 בחייו, כי הדבר הוא רק אחת לשבעים שנה, \u0003מאי אהני לרמאה ברמאותיה ולזייפנא בזייפנותיה\u0004 \u0005[מה\u0006 תועלת \u0005הועיל לרמאי ברמאותו ולזייפן בזייפנותו],\u0006 \u0003ומסיימין בה\u0004 באמירה זו \u0003הכי\u0004 \u0005[כך]:\u0006 \u0003ווי לדין כד יקום דין\u0004 \u0005[אוי לזה כאשר יקום זה],\u0006 שכאשר יקום יעקב — יפול עשיו.","\u0003אמר רב אשי: הכשילן פיהם לרשעים\u0004 הללו, \u0003אי אמרו\u0004 \u0005[אם היו אומרים]\u0006 \u0003\"זייפנא אחוה דמרנא\"\u0004 \u0005[\"זייפן\u0006 הוא \u0005אחיו של אדוננו\"]\u0006 — היה פירוש הדבר \u0003כדקאמרי\u0004 \u0005[כפי שהם אומרים\u0006 ומתכוונים\u0005],\u0006 \u0003השתא דאמרי\u0004 \"אחוה \u0003דמרנא זייפנא\"\u0004 \u0005[עכשיו ש\u0006הם \u0005אומרים\u0006 \"אחיו \u0005של אדוננו זייפן\"],\u0006 אפשר להבין מכאן ש\u0003מרנא גופיה זייפנא\u0004 \u0005[אדוננו עצמו זייפן]\u0006 \u0003הוא.\u0004","ושואלים: \u0003ותנא דידן מאי טעמא לא קחשיב לה\u0004 \u0005[והתנא שלנו\u0006 במשנה \u0005מה טעם אינו מונה אותה]\u0006 אף את החגיגה הזו? ומשיבים: \u0003להאי דאיתא בכל שתא ושתא קחשיב\u0004 \u0005[לזו שישנה בכל שנה ושנה הוא מונה],\u0006 ואילו לזו \u0003דליתא בכל שתא ושתא לא קחשיב\u0004 \u0005[שאינה בכל שנה ושנה\u0006 אלא אחת לשבעים שנה \u0005אינו מונה].\u0006","ושואלים: \u0003הני\u0004 \u0005[\u0006חגים \u0005אלה]\u0006 שמנינו במשנה הם \u0003דרומאי\u0004 \u0005[של הרומאים],\u0006 \u0003ו\u0004חגי עבודה זרה \u0003דפרסאי מאי\u0004 \u0005[של הפרסיים מהם]?\u0006 ומשיבים: \u0003מוטרדי וטוריסקי, מוהרנקי ומוהרין.\u0004 ועוד שואלים: \u0003הני דפרסאי ודרומאי\u0004 \u0005[אלה\u0006 הם חגיהם \u0005של הפרסיים והרומאיים],\u0006 \u0003דבבלאי מאי\u0004 \u0005[\u0006חגיהם \u0005של הבבליים מה הם]?\u0006 ומשיבים: \u0003מוהרנקי ואקניתיה, בחנוני ועשר באדר.\u0004","\u0003אמר רב חנן בר רב חסדא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חנן בר רבא אמר רב: חמשה בתי עבודה זרה קבועין הן, אלו הן: בית בל בבבל, בית נבו ב\u0004עיר \u0003כורסי, תרעתא שב\u0004עיר \u0003מפג, צריפא שבאשקלון, נשרא שבערביא. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל אמר: \u0003הוסיפו עליהן\u0004 את יריד שבעין בכי, נדבכה שבעכו. איכא דאמרי \u0005[יש שאומרים]\u0006 שהיה שונה: \u0003נתברא שבעכו. רב דימי מנהרדעא מתני איפכא\u0004 \u0005[היה שונה להיפך]:\u0006 \u0003יריד שבעכו, נדבכה שבעין בכי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן בר רב חסדא לרב חסדא: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קבועין הן\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי אמר אבוה דאימך\u0004 \u0005[כך אמר אבי אמך]\u0006 רב חנן בר רבא: \u0003קבועין הן לעולם,\u0004 כלומר, \u0003תדירא כולה שתא פלחי להו\u0004 \u0005[תדיר, בכל השנה עובדים אותם],\u0006 ואין להם יום איד אחד בלבד.","\u0003אמר שמואל:\u0004 הלכה היא ש\u0003בגולה אינו אסור אלא יום אידם בלבד,\u0004 ולא הימים שלפניהם ואחריהם, משום שאנו חיים בין הגוים ואין אנו יכולים להימנע מלשאת ולתת איתם זמן מרובה כל כך. ושואלים: \u0003ויום אידם\u0004 עצמו \u0003נמי מי אסיר\u0004 \u0005[גם כן האם אסור]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יהודה שרא ליה\u0004 \u0005[התיר לו]\u0006 \u0003לרב ברונא לזבוני חמרא\u0004 \u0005[למכור\u0006 לגוים \u0005יין],\u0006 \u0003ולרב גידל לזבוני חיטין בחגתא דטייעי\u0004 \u0005[למכור חיטים בחג של הערבים\u0006 הסוחרים\u0005]!\u0006 ומשיבים: \u0003שאני חגתא דטייעי, דלא קביעא\u0004 \u0005[שונה חגם של הערבים, שאינו קבוע],\u0006 ולכן לא גזרו בו.","\u0003עיר שיש בה עבודה זרה\u0004 — \u0003חוצה לה\u0004 מחוץ לעיר הזו \u0003מותר\u0004 לשאת ולתת עימהם. אם \u0003היה חוצה לה עבודה זרה\u0004 — \u0003תוכה לה\u0004 בתוך העיר עצמה \u0003מותר. מהו לילך לשם\u0004 לאותו מקום שיש בו עבודה זרה? \u0003בזמן שהדרך מיוחדת לאותו מקום\u0004 בלבד — \u0003אסור\u0004 ללכת, מפני שנראה כהולך לחגיגתם, \u0003ואם היה יכול להלך בה\u0004 בדרך זו \u0003למקום אחר\u0004 — \u0003מותר\u0004 ללכת בדרך.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003חוצה לה,\u0004 כמה הוא המרחק מן העיר שנחשב הדבר מחוצה לה? \u0003אמר ר' שמעון בן לקיש משום\u0004 (בשם) \u0003ר' חנינא: כגון עטלוזא\u0004 (השוק) \u0003של עזה\u0004 שהוא מחוץ לחומות העיר. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' שמעון בן לקיש מר' חנינא: עטלוזא של עזה, מהו?\u0004 האם מותר לעשות בו מסחר ביום אידם של בני עזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 וכי \u0003לא הלכת לצור מימיך, וראית\u0004 שם \u0003ישראל וגוי\u0004"],["\u0003ששפתו שתי קדירות על גבי כירה אחת, ולא חשו להם חכמים\u0004 לאסור את הבשר שבקדירה של ישראל, למרות שהאיסור סמוך להיתר? ואף כאן לא חששו חכמים לאסור משא ומתן בעטלוזא הסמוכה לעזה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"לא חשו להם חכמים\"\u0004 וכיצד למדים לענייננו?","\u0003אמר אביי:\u0004 לא חששו חכמים לאסור \u0003משום בשר נבילה,\u0004 ו\u0003לא אמרינן\u0004 \u0005[\u0006ו\u0005אין אנו אומרים]:\u0006 \u0003דלמא מהדר אפיה ישראל לאחוריה\u0004 \u0005[שמא מחזיר היהודי\u0006 את \u0005פניו לאחוריו]\u0006 \u0003ו\u0004באותה שעה \u0003שדי\u0004 \u0005[זורק]\u0006 ה\u0003גוי\u0004 בשר \u0003נבילה ב\u0004תוך ה\u0003קדירה\u0004 שלו. \u0003דכוותה הכא נמי\u0004 \u0005[שכיוצא בה כאן גם כן]\u0006 בענין של עטלוזא של עזה \u0003לא חשו להם חכמים\u0004 לשאת ולתת בעטלוזא \u0003משום דמי עבודה זרה\u0004 המצויים בידיהם של אנשי עזה הסמוכה.","ואילו \u0003רבא אמר: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא חשו להם חכמים\"\u0004 בעיר צור? \u0003משום בישולי גוים,\u0004 שלמרות שהנכרי מבשל בצידו אין חוששים לכך שהיהודי יעבור עבירה ויאכל משלו.","\u0003דכוותה, הכא נמי\u0004 \u0005[שכיוצא בה כאן גם כן]\u0006 \u0003לא חשו להם חכמים\u0004 לאסור על היהודים לשאת ולתת בעטלוזא \u0003משום\u0004 חשש שמא ישאו ויתנו עם אנשי עזה ב\u0003יום אידם.\u0004","\u0003רבה בר עולא אמר:\u0004 \u0003לא חשו להם חכמים משום צינורא\u0004 \u0005[נתז],\u0006 שמא ניתז מתבשילו של הגוי לתוך קדרתו של היהודי,","\u0003דכוותה הכא נמי\u0004 \u0005[כיוצא בה כאן גם כן]\u0006 \u0003לא חשו להם חכמים\u0004 לשאת ולתת בעטלוזא \u0003משום לפני אידיהן\u0004 של עזה.","שנינו במשנה: \u0003מהו לילך לשם\u0004 לעיר שיש בה עבודה זרה? בזמן שהדרך מיוחדת לאותו מקום — אסור, ואם היה יכול להלך בה למקום אחר — מותר. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עיר שיש בה עבודה זרה\u0004 — \u0003אסור ליכנס לתוכה ולא\u0004 לצאת \u0003מתוכה לעיר אחרת, דברי ר' מאיר. וחכמים אומרים: כל זמן שהדרך מיוחדת לאותו מקום\u0004 — \u0003אסור\u0004 להיכנס לתוכה. \u0003אין הדרך מיוחדת לאותו מקום\u0004 — \u0003מותר.\u0004","\u0003ישב לו קוץ\u0004 כלומר, ננעץ ברגלו קוץ, והיה אותו אדם מצוי אז \u0003בפני עבודה זרה\u0004 — \u0003לא ישחה\u0004 (יתכופף) \u0003ויטלנה\u0004 את הקוץ מתוך בשרו, \u0003מפני שנראה כמשתחוה לעבודה זרה, ואם אינו נראה\u0004 — \u0003מותר.\u0004 וכן אם \u0003נתפזרו לו מעותיו בפני עבודה זרה\u0004 — \u0003לא ישחה ויטלם, מפני שנראה כמשתחוה לעבודה זרה, ואם אינו נראה\u0004 — \u0003מותר.\u0004","וכן \u0003מעיין המושך\u0004 ועובר \u0003לפני\u0004 פסל \u0003עבודה זרה\u0004 — \u0003לא ישחה וישתה\u0004 ממנו, \u0003מפני שנראה כמשתחוה לעבודה זרה, ואם אינו נראה\u0004 — \u0003מותר. פרצופות\u0004 (דמות פרצופים של בני אדם) \u0003המקלחין מים לכרכין\u0004 שיוצאים מים מפיהם — \u0003לא יניח פיו על פיהם וישתה\u0004 מהם, \u0003מפני שנראה כמנשק לעבודה זרה. כיוצא בו לא יניח פיו על\u0004 גבי \u0003סילון\u0004 (צינור) \u0003וישתה,\u0004 והטעם שם הוא \u0003מפני הסכנה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אינו נראה\"\u0004 שאמרנו באותה ברייתא? \u0003אילימא דלא מתחזי\u0004 \u0005[אם תאמר שאינו נראה\u0006 לאחרים\u0005],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: כל מקום שאסרו חכמים\u0004 דבר \u0003מפני מראית העין, אפילו\u0004 עושה זאת \u0003בחדרי חדרים\u0004 — \u0003אסור,\u0004 ואף כאן אף על פי שאין רואים אותו, מכל מקום אסור, שנראה כעושה זאת! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אם אינו נראה כמשתחוה לעבודה זרה\u0004 אלא מפנה צידו או גבו אליה — \u0003מותר.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לשנות את ההלכות הללו כולן למרות שהן נראות דומות זו לזו. \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק \u0003קוץ,\u0004 הייתי אומר שנאסר הדבר, \u0003משום דאפשר למיזל קמיה ומשקליה\u0004 \u0005[שיכול ללכת\u0006 מעט \u0005לפניו\u0006 מעבר לעבודה זרה \u0005וליטלו]\u0006 את הקוץ ממנו, \u0003אבל מעות\u0004 ש\u0003לא אפשר\u0004 ללכת למקום אחר, אלא צריך ללקטם דווקא משם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאסר הדבר.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 רק \u0003מעות\u0004 — הייתי אומר שאסור הדבר כיון שהוא הפסד \u0003דממונא\u0004 \u0005[של ממון]\u0006 בלבד, \u0003אבל קוץ\u0004 שהוא עניין \u0003דצערא\u0004 \u0005[של צער]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאסר הדבר, ומותר לו להתכופף. \u0003ואי תנא הני תרתי\u0004 \u0005[ואם היה שונה\u0006 את \u0005שני אלה]\u0006 בלבד, הייתי אומר שנאסרו \u0003משום דליכא\u0004 \u0005[שאין]\u0006 בכך \u0003סכנה\u0004 אם לא יעשה זאת שם, \u0003אבל מעיין דאיכא\u0004 \u0005[שיש]\u0006 \u0003סכנה, דאי לא שתי מיית\u0004 \u0005[שאם אינו שותה ימות],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאסר ואין מקפידים בכך, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 להיאמר גם דבר זה."],["ויש לשאול עוד, דין \u0003פרצופות למה לי\u0004 להזכיר בברייתא? שאם להשמיענו משום ענין סכנת נפשות — כבר למדנו דבר זה במעיין! ומשיבים: דבר זה לא נכתב לגופו, אלא \u0003משום דקבעי למיתני\u0004 \u0005[שרצה לשנות]:\u0006 \u0003כיוצא בו לא יניח פיו על גבי הסילון\u0004 (צינור) \u0003וישתה, מפני הסכנה.\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003סכנה\u0004 זו? סכנת בליעת \u0003עלוקה\u0004 המצויה במים. וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא ישתה אדם מים לא מן הנהרות ולא מן האגמים, לא בפיו ולא בידו אחת, ואם שתה\u0004 — \u0003דמו בראשו, מפני הסכנה. מאי\u0004 \u0005[מהי]\u0006 \u0003סכנה\u0004 זו? \u0003סכנת עלוקה.\u0004","\u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003לר' חנינא,\u0004 ש\u0003אמר ר' חנינא: הבולע נימא\u0004 (עלוקה) \u0003של מים\u0004 — \u0003מותר\u0004 לחלל עליו את השבת מפני הסכנה ו\u0003להחם\u0004 (לחמם) \u0003לו חמין בשבת\u0004 כדי להמית את העלוקה בשתיית החמין. \u0003ומעשה באחד שבלע נימא של מים, והתיר ר' נחמיה להחם לו חמין בשבת.\u0004 ושואלים: \u0003אדהכי והכי\u0004 \u0005[בינתיים]\u0006 עד שמביאים לו את החמין, מה יעשה? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ליגמע חלא\u0004 \u0005[שיגמע חומץ].\u0006","\u0003אמר רב אידי בר אבין: האי מאן דבלע זיבורא\u0004 \u0005[מי שבולע צרעה]\u0006 — \u0003מחייא לא חיי\u0004 \u0005[לחיות לא יחיה],\u0006 שהעקיצה תגרום למותו, אלא \u0003מיהו לשקיה רביעתא דחלא שמגז\u0004 \u0005[מכל מקום שישקו אותו רביעית של חומץ חריף],\u0006 \u0003אפשר דחיי פורתא\u0004 \u0005[שיחיה מעט]\u0006 \u0003עד דמפקיד אביתיה\u0004 \u0005[שיצווה לביתו,\u0006 למשפחתו\u0005]\u0006 כל מה שהוא רוצה לומר בטרם ימות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא ישתה אדם מים בלילה, ואם שתה\u0004 — \u0003דמו בראשו,\u0004 הוא אחראי למותו, והוא \u0003מפני הסכנה.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מהי]\u0006 ה\u0003סכנה\u0004 שיש בדבר? \u0003סכנת שברירי\u0004 שהוא רוח רעה השורה על המים. ומוסיפים: \u0003ואם\u0004 הוא \u0003צחי, מאי תקנתיה\u0004 \u0005[צמא, מה תקנתו\u0006 לעשות\u0005]?\u0006 \u0003אי איכא אחרינא בהדיה\u0004 \u0005[אם יש\u0006 אדם \u0005אחר איתו],\u0006 \u0003ליתרייה ולימא ליה\u0004 \u0005[שיעיר אותו ויאמר לו]:\u0006 \u0003\"צחינא מיא\"\u0004 \u0005[צמא אני למים].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 אם אין אחר איתו, \u0003נקרקש בנכתמא אחצבא\u0004 \u0005[שיקיש במכסה על הכד],\u0006 \u0003ונימא איהו לנפשיה\u0004 \u0005[ושיאמר הוא לעצמו]\u0006 לחש זה: \u0003\"פלניא בר פלניתא\u0004 \u0005[פלוני בן פלונית],\u0006 \u0003אמרה לך אימך אזדהר\u0004 \u0005[היזהר]\u0006 \u0003משברירי ברירי רירי ירי רי בכסי חיורי\u0004 \u0005[בכוסות לבנות]\",\u0006 שזהו הלחש לרוח רעה זו.","\u0003עיר שיש בה עבודה זרה, והיו בה חנויות מעוטרות\u0004 לשם עבודה זרה, \u0003ושאינן מעוטרות, זה היה מעשה בבית שאן, ואמרו חכמים: המעוטרות\u0004 — \u0003אסורות\u0004 בקנייה מהן, משום שהן עשויות לעבודה זרה זו, \u0003ושאינן מעוטרות\u0004 — \u0003מותרות.\u0004","\u0003אמר ר' שמעון בן לקיש: לא שנו\u0004 שאסורות \u0003אלא\u0004 חנויות שהן \u0003מעוטרות בוורד והדס, דקא מתהני מריחא\u0004 \u0005[שהוא נהנה מן הריח],\u0006 שפרחים אלה הרי הם תקרובת לעבודה זרה, \u0003אבל\u0004 אם היו \u0003מעוטרות בפירות\u0004 — \u0003מותרות\u0004 בקנייה מהן, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח), \u0003נהנה הוא\u0004 ש\u0003אסור\u0004 כלומר, אסור לו ליהנות, כדי שלא ידבק בו משהו מן העבודה הזרה,"],["\u0003אבל מהנה\u0004 לגרום הנאה לעבודה זרה \u0003שרי\u0004 \u0005[מותר],\u0006 שאף שהוא גורם הנאה לעבודה זרה, שנוטלת מכס ממה שמכר בעל החנות, אין זה אסור מן התורה. \u0003ור' יוחנן אמר: אפילו\u0004 היו החנויות \u0003מעוטרות בפירות\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 שהרי \u0003קל וחומר\u0004 הוא: אם \u0003נהנה\u0004 מן העבודה זרה — \u0003אסור, מהנה\u0004 את העבודה זרה — \u0003לא כל שכן\u0004 שאסור!","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ריש לקיש ממה ששנינו, \u0003ר' נתן אומר: יום שעבודה זרה מנחת בו את המכס\u0004 שעושים הנחה בתשלומי המכס לכבודה של עבודה זרה, ש\u0003מכריזין ואומרים: כל מי שנוטל עטרה\u0004 של ורד וכיוצא בה \u0003ויניח בראשו ובראש חמורו לכבוד עבודה זרה\u0004 — \u0003יניח לו את המכס, ואם לאו\u0004 (לא) — \u0003אל יניח לו את המכס,\u0004","\u0003יהודי שנמצא שם מה יעשה?\u0004 אם \u0003יניח\u0004 את העטרה בראשו ובראש חמורו — \u0003נמצא נהנה\u0004 מעבודה זרה, \u0003לא יניח\u0004 עטרה בראשו — \u0003נמצא מהנה\u0004 אותה, שהרי הם מרויחים מן המכס שהוא נותן!","\u0003מכאן אמרו\u0004 חכמים: \u0003הנושא ונותן בשוק של עבודה זרה,\u0004 הואיל ובעל כרחו הוא נהנה או מהנה לעבודה זרה, לכן \u0003בהמה\u0004 שקנה שם \u0003תיעקר, פירות\u0004 או \u0003כסות\u0004 או \u0003כלים ירקבו,\u0004 אם היו לו \u0003מעות וכלי מתכות,\u0004 שאינם נרקבים, \u0003יוליכם לים המלח\u0004 ויאבדו שם. \u0003ואיזהו עיקור\u0004 האמור בבהמה? \u0003המנשר\u0004 (חותך) \u0003פרסותיה מן הארכובה ולמטה.\u0004","ומכאן לענייננו, \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]:\u0006 אם \u0003יניח\u0004 — \u0003נמצא נהנה, לא יניח\u0004 — \u0003נמצא מהנה\u0004 עבודה זרה, ואסור הדבר, וקשה לריש לקיש שאמר שהוא מותר!","\u0003אמר רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' שמעון בן לקיש:\u0004 \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים על]\u0006 \u0003ר' נתן, ואנא דאמרי כרבנן דפליגי עליה\u0004 \u0005[ואני שאמרתי כ\u0006דעת \u0005חכמים שחלוקים עליו]\u0006 אמרתי. ומעירים: \u0003ו\u0004מכאן משמע ש\u0003ר' יוחנן,\u0004 שפסק כר' נתן, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא פליגי\u0004 \u0005[אין\u0006 חכמים \u0005חלוקים]\u0006 אלא הכל מסכימים שמהנה אסור.","ושואלים: \u0003ולא פליגי\u0004 \u0005[\u0006וכי \u0005אין\u0006 חכמים \u0005חלוקים]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הולכין ליריד\u0004 לשוק \u0003של גוים\u0004 שנועד לכבוד עבודה זרה, \u0003ולוקחין\u0004 (קונים) \u0003מהם בהמה עבדים ושפחות, בתים ושדות וכרמים, וכותב\u0004 שטרות \u0003ומעלה\u0004 (מאשר) אותם \u0003בערכאות\u0004 (בבתי משפט) \u0003שלהן,\u0004 שאף שיש להם מכך הנאה וכבוד מותר, \u0003מפני שהוא כמציל מידם.\u0004","\u0003ואם היה כהן\u0004 — \u0003מטמא ב\u0004טומאת \u0003חוצה לארץ,\u0004 אף על פי שאסור לכהן לצאת לחוץ לארץ שהיא ארץ טמאה, כדי \u0003לדון ולערער עמהם\u0004 על קניינים שלו. \u0003וכשם שמטמא\u0004 הכהן \u0003בחוצה לארץ, כך מטמא\u0004 הכהן \u0003בבית הקברות.\u0004","ותוהים: \u0003בבית הקברות סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? הלוא \u0003טומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא,\u0004 וכיצד יתירו לו! \u0003אלא\u0004 אין הכוונה לבית הקברות ממש, כי אם ל\u0003בית הפרס\u0004 מקום שנחרש בו קבר, וחכמים טימאוהו מספק שמא יש בו מת, שהוא רק איסור \u0003דרבנן\u0004 \u0005[של חכמים],\u0006 ובכגון זה התירו חכמים לכהן.","וממשיכה הברייתא: \u0003ו\u0004כן \u0003מטמא\u0004 הכהן ויוצא לחוץ לארץ כדי \u0003ללמוד תורה ולישא אשה, אמר ר' יהודה: אימתי\u0004 אמרו דבר זה? \u0003בזמן שאין מוצא\u0004 רב \u0003ללמוד\u0004 ממנו בארץ, \u0003אבל בזמן שמוצא\u0004 ממי \u0003ללמוד\u0004 — \u0003אינו מטמא.\u0004","\u0003ר' יוסי אומר: אפילו בזמן שמוצא\u0004 ממי \u0003ללמוד\u0004 — \u0003יטמא, לפי שאין אדם זוכה ללמוד מכל\u0004 אדם, ולכן אף שיש בארץ אדם היכול ללמד, שמא הוא ימצא רב המתאים לו דווקא בחוצה לארץ.","וכן \u0003אמר ר' יוסי: מעשה ביוסף הכהן שהלך אחר רבו לצידן,\u0004 למרות שהיא חוצה לארץ ואדמתה טמאה, \u0003ללמוד תורה. ואמר ר' יוחנן: הלכה כר' יוסי.\u0004","ולענייננו, הרי ברייתא המתירה לקנות ביריד ולהנות את העבודה זרה, \u0003אלמא פליגי\u0004 \u0005[מכאן\u0006 שחכמים \u0005חלוקים]\u0006 על ר' נתן, ודעתו דעת יחיד היא! ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003ר' יוחנן: לעולם\u0004 תאמר ש\u0003לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 וגם לשיטת ברייתא זו מהנה לעבודה זרה אסור,","\u0003ו\u0004מה שהתירה הברייתא לקנות ביריד של גוים — \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאסור, מדובר \u0003בלוקח\u0004 (קונה) \u0003מן התגר\u0004 (סוחר), \u0003דשקלי מיכסא מיניה\u0004 \u0005[שלוקחים מכס ממנו]\u0006 לעבודה זרה, \u0003כאן\u0004 כשהתירו, מדובר \u0003בלוקח מבעל הבית, דלא שקלי מיכסא מיניה\u0004 \u0005[שאין נוטלים מכס ממנו],\u0006 ואם כן אינו מהנה לעבודה זרה.","ושבים לדון בברייתא של ר' נתן. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם קנה \u0003בהמה\u0004 — \u0003תיעקר.\u0004 ושואלים: \u0003והא איכא\u0004 \u0005[והרי יש\u0006 בכך\u0005]\u0006 \u0003צער בעלי חיים! אמר אביי:\u0004 אף שיש בזה צער בעלי חיים, במקום הצורך מותר הוא, שכן \u0003אמר רחמנא\u0004 \u0005[ה']\u0006 ליהושע: \u0003\"את סוסיהם תעקר\"\u0004 (יהושע יא, ו).","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ואיזוהי עיקור? מנשר פרסותיה מן הארכובה ולמטה. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003אין מקדישין\u0004 דבר למקדש, \u0003ואין מחרימין\u0004 בחרם (שסתמו לצורך המקדש), \u0003ואין מעריכין\u0004 ערכו של דבר לתת דמיו לגבוה (כאמור בויקרא כז) \u0003בזמן הזה,\u0004 שהרי אין מקדש, ונמצא שהדבר שהקדיש נעשה תקלה לרבים, שישתמשו בו ויבואו לידי מעילה. \u0003ואם\u0004 בכל זאת \u0003הקדיש והחרים והעריך,\u0004 אם היתה זו \u0003בהמה\u0004 — \u0003תיעקר,\u0004 אם היו אלה \u0003פירות כסות וכלים\u0004 —"],["\u0003ירקבו,\u0004 אם היו אלה \u0003מעות וכלי מתכות\u0004 — \u0003יוליכם לים המלח,\u0004 שם יאבדו. \u0003ואיזהו עיקור? נועל דלת בפניה\u0004 שלא תאכל, \u0003והיא מתה מאיליה!\u0004 ומדוע עושה בדרך זו ולא על ידי השרת פרסות?","\u0003אמר אביי: שאני התם\u0004 \u0005[שונה שם]\u0006 בהקדש, שאין משירים את הפרסות \u0003משום בזיון קדשים.\u0004 אגב שהובאה ברייתא זו, שואלים: אם צריך להמית את בעל החיים שהוקדש, מדוע לא יעשו בדרך פשוטה יותר, \u0003ונשחטיה מישחט\u0004 \u0005[שישחט אותו]!\u0006 ומשיבים: אם יעשה כן \u0003אתו בהו\u0004 \u0005[יבואו בהם]\u0006 \u0003לידי תקלה\u0004 שמא יבואו לאכול מבשרו, ונמצאים נהנים מן ההקדש.","ושואלים: \u0003ולישויה גיסטרא\u0004 \u0005[ושיעשהו שבר כלי],\u0006 שיחבול וישחיתנו וייעשה נבילה, ובוודאי לא יבואו לאוכלו, ולמה לצער אותו במניעת אוכל עד שימות? \u0003אמר אביי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונתצתם את מזבחתם [וגו'] \"לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג —ד)","משמע שדבר של קודש אסור להשחית אותו בידיים. \u0003רבא אמר\u0004 טעם אחר, מדוע אינו משיר פרסותיה של בהמה שהקדיש — \u0003מפני שנראה\u0004 הוא במעשה זה \u0003כמטיל מום בקדשים.\u0004 ותוהים: מהי לשון זו של \u0003נראה?\u0004 הלוא \u0003מום מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 והוא איסור של תורה! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בזמן שבית המקדש קיים, דחזי\u0004 \u0005[שראויה]\u0006 בהמה \u0003להקרבה\u0004 והוא מטיל בה מום, ואולם \u0003השתא דלא חזי\u0004 \u0005[עכשיו שאינה ראויה]\u0006 \u0003להקרבה לית לן בה\u0004 \u0005[אין לנו בכך]\u0006 איסור מן התורה של הטלת מום בקדשים, ואינו אלא נראה כעושה כן.","ומקשים: \u0003וליהוי\u0004 \u0005[ושיהא\u0006 זה\u0005]\u0006 נחשב \u0003כ\u0004דינו של \u0003מטיל מום בבעל מום, דאף על גב דלא חזי\u0004 \u0005[שאף על פי שאינו ראוי]\u0006 \u0003להקרבה\u0004 — \u0003אסור\u0004 בכל זאת להטיל בו מום! ומשיבים: יש להבחין בין בעל מום בזמן המקדש, לבהמה זו שבימינו, \u0003בעל מום, נהי\u0004 \u0005[אם אמנם]\u0006 \u0003דלא חזי לגופיה\u0004 \u0005[שאינו ראוי לגופו],\u0006 מכל מקום \u0003לדמי חזי\u0004 \u0005[לדמים\u0006 הוא \u0005ראוי],\u0006 להקריב בדמיו בהמה אחרת, ואם כן יש בו צד של הקרבה, ולכן אסור להטיל בו מום. \u0003לאפוקי הכא, דלא לדמי חזי ולא לגופיה חזי\u0004 \u0005[להוציא כאן,\u0006 בימינו, \u0005שלא לדמים\u0006 הוא \u0005ראוי ולא לגופו\u0006 הוא \u0005ראוי].\u0006","\u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003ר' יונה לר' עילאי דקאי אפיתחא\u0004 \u0005[שעומד על פיתחה]\u0006 של העיר \u0003צור,\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קתני\u0004 \u0005[שנינו]\u0006 \u0003\"בהמה תיעקר\", עבד\u0004 שקנה שם \u0003מאי\u0004 \u0005[מה]\u0006 דינו? והסביר את שאלתו: \u0003עבד ישראל לא קא מיבעיא\u0004 \u0005[נשאלת]\u0006 \u0003לי\u0004 שאלה זו, שכן ברור שאין האדון רשאי לפגוע בו, \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלת]\u0006 \u0003לי\u0004 השאלה, הרי זה ב\u0003עבד גוי, מאי\u0004 \u0005[מה]\u0006 דינו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי קא מיבעיא לך\u0004 \u0005[מה,\u0006 מדוע \u0005נשאלת לך\u0006 השאלה\u0005]?\u0006 הרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הגוים והרועי בהמה דקה\u0004 — \u0003לא מעלין\u0004 אותם מן הבור \u0003ולא מורידין\u0004 אותם בידיים לבור, הרי שאסור לגרום להם מיתה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: קתני\u0004 \u0005[שנינו]\u0006 בברייתא השנייה לעיל ש\u0003לוקחין\u0004 (קונים) \u0003מהן\u0004 ביריד של גוים \u0003בהמה עבדים ושפחות,\u0004 האם הכוונה היא דוקא \u0003עבד ישראל או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו עבד גוי? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 שמדובר דווקא ב\u0003עבד ישראל, דאי\u0004 \u0005[שאם]\u0006 \u0003עבד גוי למאי מיבעי ליה\u0004 \u0005[למה צריך אותו]?\u0006 מה הטעם להתיר לו לקנות אותו? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' שמעון בן לקיש: אפילו עבד גוי\u0004 קונים מהם, \u0003מפני שמכניסו תחת כנפי השכינה\u0004 כשנעשה עבד לישראל ומתגייר.","\u0003אמר רב אשי\u0004 על הסבר זה: \u0003אטו\u0004 \u0005[וכי]\u0006 כשקונה \u0003בהמה מאי\u0004 \u0005[מה]\u0006 \u0003\"מכניס תחת כנפי השכינה\" איכא\u0004 \u0005[יש],\u0006 שהותר הדבר? \u0003אלא\u0004 מותר הדבר \u0003משום מעוטייהו\u0004 \u0005[מיעוטם]\u0006 שממעט מנכסיהם של הגוים, \u0003והכא נמי דממעטי שרי\u0004 \u0005[וכאן גם כן\u0006 משום \u0005שמתמעטים\u0006 על ידי כך מנכסיהם \u0005מותר\u0006 הדבר\u0005].\u0006","מסופר, \u0003ר' יעקב זבן סנדלא\u0004 \u0005[קנה סנדלים]\u0006 ביריד, \u0003ר' ירמיה זבן פיתא\u0004 \u0005[קנה פת].\u0006 \u0003אמר ליה חד לחבריה\u0004 \u0005[לו אחד לחבירו]:\u0006 \u0003יתמא\u0004 \u0005[יתום]\u0006 כלומר, שאין לו רב ומדריך, \u0003עבד רבך הכי\u0004 \u0005[וכי עשה רבך כן]?\u0006 \u0003אמר ליה אידך\u0004 \u0005[לו האחר]:\u0006 \u0003יתמא, עבד רבך הכי\u0004 \u0005[יתום, וכי עשה רבך כן]?\u0006 ומסבירים, \u0003ו\u0004באמת, \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003מבעל הבית זבון\u0004 \u0005[קנו],\u0006 \u0003וכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003סבר: חבראי\u0004 \u0003מתגר זבן\u0004 \u0005[חברי מסוחר קנה],\u0006 ש\u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: לא שנו\u0004 שאסור לקנות ביריד של גוים \u0003אלא\u0004 דווקא \u0003בלוקח מן התגר,\u0004 משום \u0003דשקלי מיכסא מיניה\u0004 \u0005[שלוקחים מכס ממנו]\u0006 לעבודה זרה ונמצא מהנה אותה מנכסיו, \u0003אבל בלוקח מבעל הבית, דלא שקלי מיניה מיכסא\u0004 \u0005[שאין נוטלים ממנו מכס]\u0006 — \u0003מותר.\u0004","\u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: אילמלא\u0004 \u0005[אם]\u0006 \u0003היה ר' יוחנן הא זימנא באתרא דקא שקלי מיכסא\u0004 \u0005[בזמן הזה במקום שנוטלים מכס],\u0006 \u0003אפילו מבעל הבית הוה אסר\u0004 \u0005[היה אוסר]\u0006 לקנות, שגם מהם נוטלים. \u0003אלא אינהו, היכי זבון\u0004 \u0005[הם, איך קנו]?\u0006 \u0003מבעל הבית שאינו קבוע זבון\u0004 \u0005[קנו].\u0006","\u0003אלו דברים אסורים למכור לגוי\u0004 בכל זמן, משום שמשתמשים בהם במיוחד לתקרובת עבודה זרה: \u0003אצטרובלין, ובנות שוח, ופטוטרות\u0004 (שיבוארו להלן בגמרא), \u0003ולבונה, ותרנגול הלבן. ר' יהודה אומר: מותר למכור לו תרנגול לבן בין התרנגולין\u0004 כאשר הגוי קונה כמה תרנגולים שונים יחד; \u0003ובזמן שהוא בפני עצמו\u0004 — \u0003קוטע את אצבעו ומוכרו לו, לפי שאין\u0004 הם \u0003מקריבים חסר לעבודה זרה.\u0004","\u0003ושאר כל הדברים, סתמן\u0004 שקונה ממנו סתם — \u0003מותר, ופירושן\u0004 כשפירש שהוא לשם עבודה זרה — \u0003אסור; ר' מאיר אומר: אף דקל טב, וחצב, ונקלב\u0004 — \u0003אסור למכור לגוים.\u0004"]]};
